INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-superman-hollywood',
      'คำสาปซูเปอร์แมนแห่งฮอลลีวูด (ชะตากรรมมรณะของผู้สวมผ้าคลุม)',
      'The Curse of Superman (The Tragic Hollywood Hex)',
      'curse',
      'แคลิฟอร์เนีย',
      'California',
      'ลอสแอนเจลิส',
      'Los Angeles',
      34.0928,
      -118.3287,
      'creepy_wind',
      'หนึ่งในคำสาปที่โด่งดังและน่าสะพรึงกลัวที่สุดของวงการภาพยนตร์ฮอลลีวูด เชื่อกันว่ามีอาถรรพ์ตกทอดสู่ผู้ที่รับบทเป็น ''ซูเปอร์แมน'' หรือเกี่ยวข้องกับตัวละครนี้ จอร์จ รีฟส์ ผู้รับบทซูเปอร์แมนทางโทรทัศน์ถูกยิงเสียชีวิตอย่างมีเงื่อนงำในปี 1959 ต่อมา คริสโตเฟอร์ รีฟ ผู้รับบทซูเปอร์แมนในภาพยนตร์คลาสสิก ประสบอุบัติเหตุตกหลังม้าจนเป็นอัมพาตทั้งตัว รวมถึงนักแสดงร่วมและทีมงานหลายคนที่ต้องเผชิญกับอุบัติเหตุร้ายแรงและการเสียชีวิตก่อนวัยอันควร',
      'The Curse of Superman refers to a series of devastating misfortunes that have struck actors and creators associated with the DC Comics character. George Reeves, star of the 1950s TV series, died of a mysterious gunshot wound days before his wedding. Christopher Reeve, who famously immortalized the hero on film, was paralyzed in a horse-riding accident in 1995. Even comic creators Jerry Siegel and Joe Shuster struggled in poverty after selling the character rights.',
      'ต้นตอของคำสาปมักถูกโยงไปถึงความคับแค้นใจของผู้สร้างสรรค์ตัวละคร เจอร์รี ซีเกล และ โจ ชูสเตอร์ ที่ขายลิขสิทธิ์ซูเปอร์แมนให้แก่สำนักพิมพ์ด้วยเงินเพียง 130 ดอลลาร์ จนกลายเป็นตำนานคำสาปประจำวงการบันเทิง',
      'Rooted in the historical copyright exploitation of Siegel and Shuster, the legend has been analyzed in numerous pop-culture documentaries and investigated by Hollywood historians.',
      'ห้ามล้อเลียนชะตากรรมอันน่าเศร้าของนักแสดงผู้ล่วงลับ',
      'Never mock or trivialize the real-life tragedies of the Superman actors.',
      'https://i.ytimg.com/vi/H4NF9OYsTZ4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/H4NF9OYsTZ4/hqdefault.jpg","title":"คำสาปซูเปอร์แมนแห่งฮอลลีวูด (ชะตากรรมมรณะของผู้สวมผ้าคลุม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=H4NF9OYsTZ4","title":"Haunted Hollywood | Ep 1 | George Reeves | The Curse Of Superman","thumbnail":"https://i.ytimg.com/vi/H4NF9OYsTZ4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-27-club-musicians',
      'อาถรรพ์คลับ 27 (ชะตากรรมศิลปินดนตรีระดับตำนาน)',
      'The Curse of the 27 Club (Forever 27 Music Legends)',
      'curse',
      'วอชิงตัน',
      'Washington',
      'ซีแอตเทิล',
      'Seattle',
      47.6062,
      -122.3321,
      'whisper',
      'สโมสรแห่งความตาย 27 ปี (The 27 Club) เป็นปรากฏการณ์ลี้ลับทางดนตรีที่นักดนตรีอัจฉริยะระดับโลกต่างเสียชีวิตลงในวัยเพียง 27 ปีอย่างน่าตกใจ ตั้งแต่ โรเบิร์ต จอห์นสัน นักดนตรีบลูส์ผู้มีตำนานขายวิญญาณให้ซาตานที่ทางแยก ตามมาด้วย จิมิ เฮนดริกซ์, เจนิส จอปลิน, จิม มอร์ริสัน, เคิร์ต โคเบน แห่งวงเนอร์วานา และ เอมี ไวน์เฮาส์ หลายคนเชื่อว่าความอัจฉริยะของพวกเขาแลกมาด้วยสัญญาปีศาจที่ต้องชดใช้ด้วยชีวิตเมื่ออายุครบ 27 ปีบริบูรณ์',
      'The 27 Club is a cultural and supernatural phenomenon referring to the disproportionate number of legendary musicians who died at exactly age 27. Beginning with bluesman Robert Johnson, who allegedly made a Faustian pact with the devil at a Mississippi crossroads, the club includes Brian Jones, Jimi Hendrix, Janis Joplin, Jim Morrison, Kurt Cobain, and Amy Winehouse. Many speculate whether dark occult forces claim these prodigies at their artistic peak.',
      'การศึกษาทางสถิติของบริติชเมดิคอลเจอร์นัล (BMJ) ในปี 2011 ชี้ว่าความเสี่ยงไม่ได้สูงกว่าวัยอื่นในแง่คณิตศาสตร์ แต่รูปแบบการเสียชีวิตของดาวเด่นแห่งยุคทำให้คลับ 27 กลายเป็นตำนานร่วมสมัยที่ลึกซึ้งที่สุดในวัฒนธรรมร็อก',
      'Analyzed in multiple cultural studies and music documentaries, the 27 Club remains a poignant symbol of the devastating pressures of fame and the mythology of tortured artistic genius.',
      'ห้ามทำพิธีกรรมอัญเชิญวิญญาณศิลปินบริเวณทางแยกข้ามถนนในเวลาเที่ยงคืน',
      'Never perform dark crossroads summoning rituals invoking the departed musicians.',
      'https://i.ytimg.com/vi/o2EcmWmeoho/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/o2EcmWmeoho/hqdefault.jpg","title":"อาถรรพ์คลับ 27 (ชะตากรรมศิลปินดนตรีระดับตำนาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=o2EcmWmeoho","title":"The 27 Club | Full Documentary","thumbnail":"https://i.ytimg.com/vi/o2EcmWmeoho/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-kennedy-family-tragedies',
      'คำสาปตระกูลเคนเนดี (มหาภัยวิบัติแห่งตระกูลการเมืองอเมริกา)',
      'The Curse of the Kennedy Family Tragedies',
      'curse',
      'แมสซาชูเซตส์',
      'Massachusetts',
      'บาร์นสเตเบิล',
      'Hyannis Port',
      41.6323,
      -70.3025,
      'whisper',
      'ตระกูลการเมืองที่ทรงอิทธิพลที่สุดในประวัติศาสตร์สหรัฐอเมริกา แต่กลับถูกหลอกหลอนด้วยโศกนาฏกรรมต่อเนื่องจนได้รับการขนานนามว่า ''คำสาปเคนเนดี'' เริ่มจากการลอบสังหารประธานาธิบดี จอห์น เอฟ. เคนเนดี ในปี 1963 และการลอบสังหารวุฒิสมาชิก โรเบิร์ต เอฟ. เคนเนดี ในปี 1968 ตามด้วยอุบัติเหตุเครื่องบินตกของบุตรและสมาชิกตระกูลหลายรุ่น เล่าลือกันว่ามีต้นตอมาจากคำสาปของแรบไบชาวยิวในยุโรป หรือบาปกรรมจากการค้าสุราเถื่อนในอดีต',
      'The Kennedy Curse is a series of premature deaths, assassinations, and plane crashes that have afflicted the prominent American political dynasty for decades. Most famous was the 1963 assassination of President John F. Kennedy in Dallas, followed five years later by the assassination of his brother Senator Robert F. Kennedy. Subsequent generations suffered plane crashes (including JFK Jr. in 1999) and skiing fatalities, fueling folklore of a generational hex.',
      'เอ็ดเวิร์ด เคนเนดี เคยกล่าวถึง ''คำสาปอันมืดมิดที่แขวนอยู่เหนือครอบครัวเคนเนดี'' ระหว่างการให้การคดีอุบัติเหตุแชปปาควิคดิกในปี 1969 ซึ่งกลายเป็นการยอมรับตำนานนี้สู่สาธารณชน',
      'Mentioned on record by Ted Kennedy after the Chappaquiddick incident, the tragedies surrounding Hyannis Port have been thoroughly chronicled in global biographies and investigative documentaries.',
      'ห้ามลบหลู่สถานที่รำลึกหรือจัดกิจกรรมท้าทายในพื้นที่ประวัติศาสตร์ของตระกูล',
      'Never disrespect memorial grounds or treat family tragedies with casual mockery.',
      'https://i.ytimg.com/vi/CdgrdnsacIc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CdgrdnsacIc/hqdefault.jpg","title":"คำสาปตระกูลเคนเนดี (มหาภัยวิบัติแห่งตระกูลการเมืองอเมริกา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CdgrdnsacIc","title":"The Kennedy Family Curse: The Strange Events Surrounding America''s most Famous Family","thumbnail":"https://i.ytimg.com/vi/CdgrdnsacIc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-macbeth-scottish-play',
      'คำสาปบทละครแม็คเบ็ธ (อาถรรพ์แห่งบทละครสก็อตแลนด์)',
      'The Curse of Macbeth (The Scottish Play Hex)',
      'curse',
      'ลอนดอน',
      'London',
      'เซาธ์วาร์ก',
      'Southwark',
      51.5081,
      -0.0972,
      'creepy_wind',
      'บทละครโศกนาฏกรรมชิ้นเอกของ วิลเลียม เชกสเปียร์ ที่เหล่านักแสดงละครเวทีทั่วโลกต่างหวาดกลัวและปฏิเสธที่จะเอ่ยชื่อ ''แม็คเบ็ธ'' ในโรงละคร โดยเลี่ยงไปเรียกว่า ''The Scottish Play'' เชื่อกันว่าเชกสเปียร์ได้ใช้คาถาเวทมนตร์ของแม่มดจริงในการประพันธ์ฉากแม่มดสามตน ทำให้แม่มดตัวจริงโกรธแค้นและสาปแช่งบทละครนี้ ตลอดหลายศตวรรษ การแสดงแม็คเบ็ธมักเกิดอุบัติเหตุดาบจริงแทงนักแสดงเสียชีวิต เพดานเวทีพังถล่ม หรือเกิดเพลิงไหม้โรงละครวอดวาย',
      'For over four centuries, actors have feared speaking the name ''Macbeth'' inside a theater, substituting it with ''The Scottish Play''. Legend says William Shakespeare used authentic Black Magic incantations in the opening lines of the Three Witches, enraging a real coven who cursed the production forever. Since its premier in 1606, staging the play has resulted in fatal prop-sword woundings, falling sandbags, and theater fires like the deadly Astor Place Riot in 1849.',
      'หากใครเผลอเอ่ยชื่อแม็คเบ็ธในโรงละคร ต้องทำพิธีล้างอาถรรพ์ทันทีด้วยการเดินออกจากห้อง หมุนตัวสามรอบ ถ่มน้ำลายข้ามไหล่ซ้าย และเคาะประตูขออนุญาตกลับเข้ามาใหม่',
      'The theatrical counter-curse ritual—exiting the building, spinning three times widdershins, spitting, and reciting a line from The Merchant of Venice—is universally observed across professional stages today.',
      'ห้ามพูดชื่อ ''แม็คเบ็ธ'' ภายในโรงละครเด็ดขาด หากไม่ได้อยู่ระหว่างการแสดงบนเวที',
      'Never utter the word ''Macbeth'' inside a theatrical dressing room or backstage.',
      'https://i.ytimg.com/vi/sqD2gvF98Cc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/sqD2gvF98Cc/hqdefault.jpg","title":"คำสาปบทละครแม็คเบ็ธ (อาถรรพ์แห่งบทละครสก็อตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sqD2gvF98Cc","title":"The Curse of Macbeth \"The Scottish Play\"","thumbnail":"https://i.ytimg.com/vi/sqD2gvF98Cc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-lizzie-borden-house',
      'บ้านลิซซี บอร์เดน (คดีขวานสังหารโหด 40 แผลแห่งฟอลล์ริเวอร์)',
      'The Lizzie Borden Axe Murder House (Fall River)',
      'curse',
      'แมสซาชูเซตส์',
      'Massachusetts',
      'ฟอลล์ริเวอร์',
      'Fall River',
      41.7011,
      -71.1558,
      'creepy_wind',
      'ในเช้าวันที่ 4 สิงหาคม 1892 เกิดคดีฆาตกรรมสะเทือนขวัญที่สุดในประวัติศาสตร์อเมริกา แอนดรูว์ บอร์เดน มหาเศรษฐีเจ้าของบ้าน และแอ็บบี ภรรยาใหม่ ถูกฟันด้วยขวานจนกะโหลกแหลกละเอียดคากองเลือดภายในบ้าน ลิซซี บอร์เดน บุตรสาวตกเป็นผู้ต้องสงสัยคนสำคัญ แม้เธอจะพ้นผิดในชั้นศาล แต่บ้านหลังนี้ก็กลายเป็นสถานที่ต้องคำสาปที่เต็มไปด้วยเสียงกรีดร้อง รอยเท้าปริศนา และเงาร่างสตรีถือขวานที่ยังคงเดินวนเวียนอยู่ในห้องรับแขก',
      'On August 4, 1892, wealthy businessman Andrew Borden and his wife Abby were bludgeoned to death with a hatchet in their Fall River home. Although daughter Lizzie Borden was famously acquitted of the brutal double homicide, popular folklore immortalized the nursery rhyme: ''Lizzie Borden took an axe and gave her mother forty whacks.'' Now operating as a bed and breakfast, guests report bloodcurdling cries, cold drafts, and sightings of an apparition clutching a hatchet.',
      'คดีลิซซี บอร์เดน เป็นหนึ่งในคดีฆาตกรรมปริศนาที่ยังปิดไม่ลงของสหรัฐฯ ปัจจุบันบ้านหลังนี้เปิดเป็นโรงแรมและพิพิธภัณฑ์ที่ได้รับความนิยมสูงสำหรับผู้ชื่นชอบคดีฆาตกรรมในประวัติศาสตร์',
      'Featured extensively in American legal history and crime psychology, the Borden House preserved the Victorian crime scene furniture, drawing true-crime researchers from around the world.',
      'ห้ามวางขวานหรือสิ่งของมีคมบนเตียงนอนในห้องเกิดเหตุ',
      'Never bring replica hatchets onto the bed where Abby Borden''s body was discovered.',
      'https://i.ytimg.com/vi/XYDiEcyDUBU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XYDiEcyDUBU/hqdefault.jpg","title":"บ้านลิซซี บอร์เดน (คดีขวานสังหารโหด 40 แผลแห่งฟอลล์ริเวอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XYDiEcyDUBU","title":"\"Lizzie Borden Took an Axe\" | Full Episode","thumbnail":"https://i.ytimg.com/vi/XYDiEcyDUBU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-sallie-house-atchison',
      'บ้านแซลลี (คฤหาสน์ผีสิงและวิญญาณเด็กหญิงผู้เคียดแค้น)',
      'The Sallie House (Haunted Doctor''s Residence of Atchison)',
      'curse',
      'แคนซัส',
      'Kansas',
      'แอตชิสัน',
      'Atchison',
      39.5631,
      -95.1217,
      'creepy_wind',
      'บ้านหลังเล็กในเมืองแอตชิสันที่เคยเป็นคลินิกของนายแพทย์ชาร์ลส์ ฟินนีย์ ในศตวรรษที่ 19 เด็กหญิงวัย 6 ขวบนามว่า แซลลี ถูกนำตัวมาผ่าตัดไส้ติ่งอักเสบฉุกเฉิน ทว่าแพทย์เริ่มลงมีดผ่าตัดก่อนที่ยาสลบจะออกฤทธิ์เต็มที่ ทำให้แซลลีเจ็บปวดทรมานจนช็อกเสียชีวิตคาเตียง วิญญาณของเธอกลายเป็นวิญญาณเคียดแค้นที่มักโจมตีผู้ชาย โดยเฉพาะสามีที่เข้ามาอาศัย จะถูกข่วนเป็นรอยเล็บลึกเลือดซิบ ผลักตกบันได และเกิดเหตุไฟไหม้สิ่งของเองในบ้าน',
      'In the late 19th century, this Atchison home was the office of Dr. Charles Finney. A six-year-old girl named Sallie was brought in with acute appendicitis; believing her appendix was on the verge of bursting, the doctor began surgery before the anesthesia took full effect. Sallie died screaming in agony on the table. In the 1990s, resident Tony Pickman experienced terrifying physical attacks, with deep burning scratch marks appearing across his chest and objects bursting into flames.',
      'บ้านแซลลีได้รับการบันทึกและถ่ายทำในรายการ Sightings ทางสถานีโทรทัศน์ และถือเป็นหนึ่งในสถานที่สิงสถิตของพลังงานโพลเทอร์ไกสท์ที่รุนแรงที่สุดในแถบมิดเวสต์ของสหรัฐฯ',
      'Documented with thermal camera anomalies and real-time laceration injuries by paranormal TV crews, the Sallie House remains a focal point for poltergeist research.',
      'ผู้ชายห้ามเข้าไปท้าทายหรืออยู่คนเดียวในห้องใต้ดินของบ้านแซลลี',
      'Men are cautioned against entering the basement alone or uttering taunts to the entity.',
      'https://i.ytimg.com/vi/BqCgWLk-DTY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/BqCgWLk-DTY/hqdefault.jpg","title":"บ้านแซลลี (คฤหาสน์ผีสิงและวิญญาณเด็กหญิงผู้เคียดแค้น)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=BqCgWLk-DTY","title":"Haunted Heartland: The Sallie House in Atchison, KS","thumbnail":"https://i.ytimg.com/vi/BqCgWLk-DTY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-amityville-horror-defao',
      'บ้านสยองขวัญอมิตีวิลล์ (โศกนาฏกรรม 112 โอเชียนอเวนิว)',
      'The Amityville Horror (112 Ocean Avenue Tragedy)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'อมิตีวิลล์',
      'Amityville',
      40.6667,
      -73.4158,
      'whisper',
      'ในคืนวันที่ 13 พฤศจิกายน 1974 โรนัลด์ เดเฟโอ จูเนียร์ ได้ใช้ปืนไรเฟิลสังหารพ่อ แม่ และพี่น้องรวม 6 ศพ ขณะที่ทุกคนกำลังนอนหลับ โดยอ้างว่าได้ยิน ''เสียงกระซิบจากบ้าน'' สั่งให้ฆ่า หนึ่งปีต่อมา ครอบครัวลุตซ์ย้ายเข้ามาอยู่และต้องหนีเตลิดออกมาในเวลาเพียง 28 วัน หลังเผชิญกับเมือกสีเขียวไหลออกจากกำแพง ฝูงแมลงวันนับร้อยตัวในห้องนอน กลิ่นเหม็นเน่า และร่างเงาดวงตาสีแดงของหมูปีศาจนามว่า โจดี้',
      'On November 13, 1974, Ronald DeFeo Jr. shot and killed all six members of his family with a Marlin rifle at 112 Ocean Avenue, claiming demonic voices inside the house commanded him to kill. Thirteen months later, George and Kathy Lutz moved in with their children, only to flee in terror 28 days later, reporting levitating beds, green slime oozing from keyholes, swarms of flies, and glowing red pig-like eyes peering through windows.',
      'เรื่องราวนี้ถูกนำไปเขียนเป็นหนังสือนวนิยายขายดีของ เจย์ แอนสัน และสร้างเป็นแฟรนไชส์ภาพยนตร์สยองขวัญชื่อก้องโลก ''The Amityville Horror'' ซึ่งนำพา เอ็ด และ ลอร์เรน วอร์เรน เข้ามาสืบสวน',
      'Investigated by demonologists Ed and Lorraine Warren, the Amityville case spawned dozens of Hollywood films and sparked intense international debates between believers and skeptics.',
      'ห้ามบุกรุกหรือรบกวนความเป็นส่วนตัวของเจ้าของบ้านในปัจจุบัน',
      'Never trespass or photograph the private residential property on Ocean Avenue.',
      'https://i.ytimg.com/vi/tJksOcN1050/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/tJksOcN1050/hqdefault.jpg","title":"บ้านสยองขวัญอมิตีวิลล์ (โศกนาฏกรรม 112 โอเชียนอเวนิว)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=tJksOcN1050","title":"Spine-Chilling: The Real Amityville Horror (Paranormal Documentary)","thumbnail":"https://i.ytimg.com/vi/tJksOcN1050/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-robert-the-doll-key-west',
      'โรเบิร์ต ตุ๊กตาผีสิงแห่งคีย์เวสต์ (อาถรรพ์ตุ๊กตากะลาสีห้ามถ่ายรูป)',
      'Robert the Doll (The Cursed Sailor Doll of Key West)',
      'curse',
      'ฟลอริดา',
      'Florida',
      'คีย์เวสต์',
      'Key West',
      24.5551,
      -81.78,
      'whisper',
      'ตุ๊กตาผ้าขนาดเท่าเด็กสวมชุดกะลาสีที่มอบให้แก่ โรเบิร์ต ยูจีน ออตโต ในปี 1904 โดยคนรับใช้ชาวบาฮามาสที่ชำนาญเวทมนตร์วูดู ยูจีนรักตุ๊กตาตัวนี้มากและมักพูดคุยกับมัน พ่อแม่ของเขาเริ่มได้ยินเสียงหัวเราะเยาะเย้ยอันน่าสะพรึงกลัวและพบเห็นเฟอร์นิเจอร์ถูกคว่ำทำลาย ปัจจุบันตุ๊กตาถูกเก็บไว้ที่พิพิธภัณฑ์ฟอร์ทอีสต์มาร์เทลโล โดยมีกฎเหล็กว่า ''ผู้ใดจะถ่ายรูปโรเบิร์ต ต้องขออนุญาตตุ๊กตาก่อนอย่างสุภาพ'' มิฉะนั้นจะถูกคำสาปประสบอุบัติเหตุ ล้มละลาย หรือเจ็บป่วยร้ายแรง',
      'Given in 1904 to young Robert Eugene Otto by an abused Bahamian servant skilled in voodoo and black magic, Robert is a straw-filled sailor doll that soon exhibited malevolent behavior. Eugene''s family reported hearing sinister chuckles and discovering mutilated toys. Displayed today at the Fort East Martello Museum, visitors must politely ask the doll''s permission before taking a photograph; those who fail to do so receive letters of apology later describing ruined cameras, broken bones, and sudden bankruptcies.',
      'พิพิธภัณฑ์ฟอร์ทอีสต์มาร์เทลโลได้รับจดหมายขอขมาและขอให้ถอนคำสาปจากผู้เข้าชมหลายพันฉบับจากทั่วโลก และเป็นแรงบันดาลใจหลักในการสร้างตัวละคร ''ชัคกี้'' ในภาพยนตร์ Child''s Play',
      'Walls surrounding Robert''s glass case are pinned with hundreds of real apology letters from tourists worldwide begging the doll to lift curses placed upon them after taking disrespectful photos.',
      'ห้ามถ่ายภาพตุ๊กตาโรเบิร์ตโดยไม่ได้กล่าวขออนุญาตต่อหน้าตุ๊กตาก่อน',
      'Never snap a photo of Robert the Doll without verbally asking his permission first.',
      'https://i.ytimg.com/vi/Sq0LuZrDbHo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Sq0LuZrDbHo/hqdefault.jpg","title":"โรเบิร์ต ตุ๊กตาผีสิงแห่งคีย์เวสต์ (อาถรรพ์ตุ๊กตากะลาสีห้ามถ่ายรูป)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Sq0LuZrDbHo","title":"Robert The Doll and The Most Haunted Places in Key West","thumbnail":"https://i.ytimg.com/vi/Sq0LuZrDbHo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-sloss-furnaces-graveyard-shift',
      'สลอสส์ เฟอร์เนสเซส (เตาหลอมเหล็กมรณะและคำสาปเจมส์ สแลก)',
      'Sloss Furnaces & The Graveyard Shift Curse (Birmingham)',
      'curse',
      'แอละแบมา',
      'Alabama',
      'เบอร์มิงแฮม',
      'Birmingham',
      33.5207,
      -86.7911,
      'creepy_wind',
      'โรงงานถลุงเหล็กขนาดยักษ์ที่เปิดดำเนินการในปี 1882 มีประวัติศาสตร์อันโหดร้ายของการใช้แรงงานทาสและคนงานผิวดำในสภาพอากาศร้อนจัดกว่า 120 องศาฟาเรนไฮต์ หัวหน้าคนงานนามว่า เจมส์ ''สแลก'' วอร์มวูด เป็นทรราชที่บังคับให้คนงานทำงานกะดึกอันตรายจนมีคนงานเสียชีวิตกว่า 47 คนจากอุบัติเหตุตกลงไปในน้ำเหล็กหลอมเหลว ในปี 1906 วอร์มวูดเสียหลักตกลงไปในเตาหลอมเหล็กหลอมละลายทั้งเป็น นับแต่นั้นวิญญาณคลุ้มคลั่งของเขายังคงหลอกหลอนและทำร้ายคนงานจนโรงงานต้องปิดตัว',
      'Operating from 1882 to 1971, Sloss Furnaces produced pig iron under brutal, scorching conditions exceeding 120 degrees Fahrenheit. The graveyard shift was overseen by foreman James ''Slag'' Wormwood, who forced workers into fatal speeds, causing 47 men to incinerate in molten iron vats. In 1906, Slag mysteriously plummeted to his death into the furnace slag. His aggressive, scorched phantom continues to stalk the catwalks, pushing night watchmen and leaving painful burn marks.',
      'สลอสส์ เฟอร์เนสเซส ได้รับการขึ้นทะเบียนเป็นโบราณสถานแห่งชาติในปี 1981 และเป็นโรงงานถลุงเหล็กยุคปฏิวัติอุตสาหกรรมเพียงแห่งเดียวในโลกที่ได้รับการอนุรักษ์ไว้เป็นพิพิธภัณฑ์',
      'A National Historic Landmark, Sloss Furnaces is renowned for hundreds of recorded paranormal encounters and physical assault reports by security guards on the night shift.',
      'ห้ามเดินขึ้นไปบนสะพานแคทวอล์กเหนือเตาหลอมเหล็กในเวลากลางคืน',
      'Never walk the rusted industrial catwalks above the blast furnace alone after dark.',
      'https://i.ytimg.com/vi/yIrpxcRTeyk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yIrpxcRTeyk/hqdefault.jpg","title":"สลอสส์ เฟอร์เนสเซส (เตาหลอมเหล็กมรณะและคำสาปเจมส์ สแลก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yIrpxcRTeyk","title":"The Untold Story Of Sloss Furnances - Birmingham, Alabama","thumbnail":"https://i.ytimg.com/vi/yIrpxcRTeyk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-clinton-road-ghost-boy',
      'คลินตัน โรด (ถนนอาถรรพ์ที่สุดในอเมริกาและสะพานเด็กผี)',
      'Clinton Road & The Ghost Boy of Dead Man''s Curve',
      'curse',
      'นิวเจอร์ซีย์',
      'New Jersey',
      'พาสเซอิก',
      'Passaic County',
      41.1444,
      -74.4539,
      'whisper',
      'ถนนลาดยางคดเคี้ยวระยะทาง 10 ไมล์ที่ตัดผ่านป่าทึบไร้แสงไฟส่องสว่าง มีชื่อเสียงว่าเป็น ''ถนนที่มีผีดุและแปลกประหลาดที่สุดในอเมริกา'' ณ สะพานข้ามลำธารเดดแมนส์เคิร์ฟ มีตำนานของ ''เด็กชายผี'' หากใครโยนเหรียญเพนนีลงไปในลำธารเบื้องล่าง วิญญาณของเด็กจะโยนเหรียญนั้นกลับขึ้นมาคืนให้ นอกจากนี้ตลอดสองข้างทางยังมีรายงานการพบเห็นสัตว์ประหลาดกลายพันธุ์ ซากปราสาทแม่มดครอสลีย์ และรถยนต์ผีสิงที่ไล่กวดผู้ขับขี่ก่อนหายวับไป',
      'Stretching for ten desolate, unlit miles through the woods of West Milford, Clinton Road is widely regarded as America''s most haunted stretch of asphalt. At Dead Man''s Curve bridge, folklore says if you toss a coin into the river below, the ghost of a drowned boy will throw it right back up onto the pavement. Drivers report phantom pickup trucks tailgating with blinding high beams before vanishing into thin air, alongside sightings of mutant hellhounds.',
      'ถนนแห่งนี้เคยเป็นสถานที่ทิ้งศพของฆาตกรต่อเนื่องฉายา ''ดิ ไอซ์แมน'' (Richard Kuklinski) ซึ่งยิ่งเพิ่มบรรยากาศความน่าสะพรึงกลัวและเรื่องเล่าขานในนิตยสาร Weird NJ',
      'Clinton Road was notoriously used by Mob hitman Richard Kuklinski to dispose of bodies, intertwining dark true crime history with urban supernatural folklore.',
      'ห้ามจอดรถดับเครื่องยนต์กลางสะพานเดดแมนส์เคิร์ฟในเวลาเที่ยงคืน',
      'Never turn off your engine and headlights while stopped on the bridge at Dead Man''s Curve.',
      'https://i.ytimg.com/vi/PFiJqFsboSs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/PFiJqFsboSs/hqdefault.jpg","title":"คลินตัน โรด (ถนนอาถรรพ์ที่สุดในอเมริกาและสะพานเด็กผี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=PFiJqFsboSs","title":"CLINTON ROAD: The Worlds Most Haunted Highway (Full Movie)","thumbnail":"https://i.ytimg.com/vi/PFiJqFsboSs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-stull-cemetery-gateway-hell',
      'สุสานสตัลล์ (หนึ่งในเจ็ดประตูนรกแห่งรัฐแคนซัส)',
      'Stull Cemetery & The Gateway to Hell Legend',
      'curse',
      'แคนซัส',
      'Kansas',
      'ดักลาส',
      'Douglas County',
      38.9719,
      -95.4561,
      'creepy_wind',
      'สุสานชนบทเล็กๆ บนเนินเขาที่มีชื่อเสียงระดับโลกในฐานะ ''หนึ่งในเจ็ดประตูนรกบนโลกมนุษย์'' ตำนานเล่าว่าในคืนวันฮาโลวีนและวันศารทวิษุวัต พญามารลูซิเฟอร์จะเสด็จขึ้นมายังพื้นโลก ณ สุสานแห่งนี้เพื่อพบกับวิญญาณของแม่มดที่ถูกแขวนคอและฝังไว้ที่นี่ ซากโบสถ์หินร้างที่เคยตั้งอยู่ในสุสานมีเรื่องเล่าประหลาดว่า แม้ฝนจะตกหนักเพียงใด แต่น้ำฝนก็ไม่เคยตกลงมาถึงพื้นภายในกำแพงโบสถ์เลยแม้แต่หยดเดียว',
      'Stull Cemetery is steeped in American urban legend as one of Earth''s Seven Gateways to the Underworld. According to decades of folklore, the Devil himself appears in the cemetery twice a year—on the vernal equinox and on Halloween—to visit the grave of an executed witch. The ruined stone church that stood inside the grounds was reputed to be roofless yet mysteriously immune to rainfall within its perimeter until it was demolished in 2002.',
      'เรื่องเล่านี้โด่งดังจนสมเด็จพระสันตะปาปาจอห์น ปอลที่ 2 เคยทรงสั่งให้นักบินเปลี่ยนเส้นทางบินไม่ให้บินผ่านเหนือน่านฟ้าเมืองสตัลล์ และกลายเป็นสถานที่สำคัญในซีรีส์ดัง Supernatural',
      'Immortalized in the TV series ''Supernatural'' as the final battleground of the Apocalypse, the cemetery is heavily patrolled by Douglas County sheriff deputies to deter trespassers.',
      'ห้ามบุกรุกเข้าไปในสุสานสตัลล์หลังพระอาทิตย์ตกดินเด็ดขาด มีโทษจับกุมทันที',
      'Strict no-trespassing orders are enforced; unauthorized night entry results in immediate arrest.',
      'https://i.ytimg.com/vi/OnMkP30lFAY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/OnMkP30lFAY/hqdefault.jpg","title":"สุสานสตัลล์ (หนึ่งในเจ็ดประตูนรกแห่งรัฐแคนซัส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=OnMkP30lFAY","title":"The Terrifying Legends and Truth About Stull Kansas","thumbnail":"https://i.ytimg.com/vi/OnMkP30lFAY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-seven-gates-hell-york',
      'ประตูนรกทั้งเจ็ดแห่งยอร์ก (ตำนานป่าคลั่งและสถานบำบัดเพลิงไหม้)',
      'The Seven Gates of Hell of Hellam Township (York)',
      'curse',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'ยอร์ก',
      'York County',
      40.0075,
      -76.6022,
      'jungle_curse',
      'ในป่าลึกของตำบลเฮลลัม มีเรื่องเล่าของสถานบำบัดผู้ป่วยทางจิตในศตวรรษที่ 19 ที่เกิดเหตุเพลิงไหม้วอดวาย ผู้ป่วยที่คุ้มคลั่งหลบหนีเข้าไปในป่า นายแพทย์จึงสั่งให้สร้างประตูด่านตรวจ 7 ชั้นเพื่อกักขัง ทว่าผู้ป่วยหลายคนถูกยิงเสียชีวิตอย่างโหดร้าย ตำนานเมืองระบุว่า หากใครเดินผ่านประตูเหล็กทั้ง 7 บานในป่าตามลำดับได้ครบในคืนเดือนดับ ประตูบานที่เจ็ดจะเปิดออกสู่ขุมนรกโดยตรง และผู้ที่ก้าวผ่านจะไม่สามารถกลับออกมาได้อีกตลอดกาล',
      'Hidden in the wooded backcountry of Hellam Township lie the fabled Seven Gates of Hell. Local legend claims an asylum deep in the forest caught fire in the 1800s, unleashing inmates into the wilderness; doctors erected seven guarded gates to trap them, leading to brutal slayings. The myth holds that anyone who walks through all seven iron gates sequentially in the dark will be swallowed alive into hell, never returning to the mortal world.',
      'แม้ในความเป็นจริง ประตูบางส่วนจะเป็นเพียงประตูฟาร์มของคางคกตระกูลไฮแลนด์ แต่ความคล้ายคลึงของชื่อเมือง ''Hellam'' กับคำว่า ''Hell'' ทำให้ตำนานนี้หยั่งรากลึกในวัฒนธรรมพื้นบ้านเพนซิลเวเนีย',
      'Investigated by folklorists and Weird Pennsylvania, the legend combines rural isolation with historic fears of 19th-century psychiatric institutions.',
      'ห้ามเดินตามหาประตูบานที่เจ็ดกลางป่าในเวลาหลังเที่ยงคืน',
      'Never attempt to pass through all seven gates after dark without a guide.',
      'https://i.ytimg.com/vi/SK_ogZzWFb8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SK_ogZzWFb8/hqdefault.jpg","title":"ประตูนรกทั้งเจ็ดแห่งยอร์ก (ตำนานป่าคลั่งและสถานบำบัดเพลิงไหม้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SK_ogZzWFb8","title":"This Town In Pennsylvania is Home to The 7 Gates of Hell","thumbnail":"https://i.ytimg.com/vi/SK_ogZzWFb8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-bobby-mackey-slaughterhouse-well',
      'บ็อบบี้ แม็คกีย์ มิวสิกเวิลด์ (บ่อน้ำโรงฆ่าสัตว์สังเวยซาตาน)',
      'Bobby Mackey''s Music World (The Slaughterhouse Well)',
      'curse',
      'เคนทักกี',
      'Kentucky',
      'ไวลเดอร์',
      'Wilder',
      39.0689,
      -84.4847,
      'creepy_wind',
      'สถานบันเทิงเพลงคันทรีที่สร้างทับบนซากโรงฆ่าสัตว์เก่าในศตวรรษที่ 19 ภายในห้องใต้ดินมี ''บ่อน้ำทิ้งเลือด'' โบราณ ซึ่งเคยถูกใช้โดยลัทธิบูชาซาตานเพื่อทำพิธีตัดศีรษะสังหารหญิงสาวนามว่า เพิร์ล ไบรอัน ในปี 1896 และนำศีรษะของเธอโยนลงไปในบ่อน้ำเพื่อไม่ให้ใครพบ ตำนานเล่าว่าบ่อน้ำนี้คือประตูนรกที่มีสิ่งลี้ลับคอยข่วน ตี และด่าทอผู้มาเยือน ป้ายหน้าร้านเคยติดข้อความว่า ''ยินดีต้อนรับสู่บ็อบบี้ แม็คกีย์ แต่เราไม่รับประกันความปลอดภัยจากวิญญาณ''',
      'Bobby Mackey''s Music World is an infamous honky-tonk tavern built upon an 1890s slaughterhouse well used for blood disposal. In 1896, occultists Scott Jackson and Alonzo Walling decapitated pregnant maiden Pearl Bryan and allegedly dropped her severed head into the well as a demonic sacrifice. Today, the basement well is considered a demonic portal where caretakers and paranormal investigators are routinely scratched, shoved, and threatened by disembodied voices.',
      'คดีฆาตกรรมเพิร์ล ไบรอัน เป็นคดีประวัติศาสตร์ที่โด่งดังระดับชาติของสหรัฐฯ ทั้งสองถูกตัดสินประหารชีวิตด้วยการแขวนคอ และก่อนตายพวกเขาสาปแช่งว่าจะกลับมาหลอกหลอนสถานที่แห่งนี้',
      'Featured on Ghost Adventures and Destination Truth, the honky-tonk holds a notorious place in American paranormal lore as one of the most violent active haunting locations.',
      'ห้ามจ้องมองลงไปในบ่อน้ำโรงฆ่าสัตว์ในห้องใต้ดินเป็นเวลานาน',
      'Never lean over or shout insults into the dark slaughterhouse well pit.',
      'https://i.ytimg.com/vi/j6IwtCFJbu0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/j6IwtCFJbu0/hqdefault.jpg","title":"บ็อบบี้ แม็คกีย์ มิวสิกเวิลด์ (บ่อน้ำโรงฆ่าสัตว์สังเวยซาตาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j6IwtCFJbu0","title":"GHOST ADVENTURES  Episode 1 - Bobby Mackey''s Music World","thumbnail":"https://i.ytimg.com/vi/j6IwtCFJbu0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-shanley-hotel-hauntings',
      'โรงแรมแชนลีย์ (โรงแรมอาถรรพ์แห่งหุบเขารอนเดาท์)',
      'The Haunted Shanley Hotel of Napanoch (Ulster County)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'นาปาน็อค',
      'Napanoch',
      41.7481,
      -74.3739,
      'whisper',
      'โรงแรมโบราณที่สร้างขึ้นในปี 1895 ท่ามกลางประวัติศาสตร์อันโศกเศร้าของการเสียชีวิตของเด็กทารกถึง 3 คนของเจ้าของโรงแรม เจมส์ แชนลีย์ และการจมน้ำตายของเด็กหญิงลูกสาวช่างตัดผมในบ่อน้ำหลังโรงแรม ในช่วงยุคห้ามจำหน่ายสุรา โรงแรมแห่งนี้ถูกใช้เป็นบ่อนการพนัน ซ่องโสเภณีลับ และสถานที่กบดานของแก๊งมาเฟีย ผู้เข้าพักมักได้ยินเสียงเด็กร้องไห้กระซิก เสียงผิวปากเพลงโบราณ และมีลมเย็นยะเยือกพัดผ่านห้องพักอย่างกะทันหัน',
      'Constructed in 1895 in the Shawangunk Mountains, the Shanley Hotel is steeped in tragic heartbreak. Proprietor James Shanley saw three of his infant children die within months of birth, followed by the accidental drowning of a barber''s young daughter in the property well. During Prohibition, the hotel operated as an illegal speakeasy and bordello. Ghost hunters routinely record EVPs of weeping children, moving rocking chairs, and phantom cigar smoke.',
      'โรงแรมแชนลีย์ได้รับการขนานนามว่าเป็นหนึ่งในสถานที่ที่มีผีดุและมีกิจกรรมเหนือธรรมชาติมากที่สุดในรัฐนิวยอร์ก ปัจจุบันเปิดให้นักล่าผีเข้าพักค้างคืนเพื่อทำการทดลองทางวิทยาศาสตร์',
      'Operating exclusively as a paranormal research retreat, the hotel maintains extensive guest logbooks recording spontaneous clock chime stoppages and spectral apparitions.',
      'ห้ามท้าทายวิญญาณเด็กในห้องพักของครอบครัวแชนลีย์',
      'Never provoke or taunt the spirits of the deceased Shanley infants.',
      'https://i.ytimg.com/vi/WKJgUIcwdFw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/WKJgUIcwdFw/hqdefault.jpg","title":"โรงแรมแชนลีย์ (โรงแรมอาถรรพ์แห่งหุบเขารอนเดาท์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=WKJgUIcwdFw","title":"Inside the Haunted Shanley Hotel","thumbnail":"https://i.ytimg.com/vi/WKJgUIcwdFw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-emille-bell-child-sacrifice',
      'ระฆังเอมิลเลแห่งซิลลา (เสียงร่ำไห้ของทารกในเนื้อสัมฤทธิ์)',
      'The Cursed Emille Bell & Child Sacrifice of Silla',
      'curse',
      'คย็องซังเหนือ',
      'North Gyeongsang',
      'คย็องจู',
      'Gyeongju',
      35.8294,
      129.2289,
      'temple_bell',
      'ระฆังศักดิ์สิทธิ์ของกษัตริย์ซ็องด็อกแห่งอาณาจักรซิลลา น้ำหนักกว่า 19 ตัน ซึ่งเป็นหนึ่งในระฆังโบราณที่ใหญ่ที่สุดในเอเชีย ตำนานเล่าว่าการหล่อระฆังครั้งแรกประสบความล้มเหลว เนื้อโลหะแตกร้าวและไร้เสียงกังวาน พระภิกษุจึงทำตามนิมิตด้วยการนำทารกของหญิงยากจนมาโยนลงในเบ้าหลอมทองสัมฤทธิ์เดือดพล่านเพื่อสังเวยแก่เทพเจ้า เมื่อหล่อเสร็จ ระฆังกลับส่งเสียงดังก้องกังวานไกลนับสิบไมล์ ทว่าเสียงสะท้อนสุดท้ายจะฟังคล้ายเสียงทารกร้องไห้เรียกหาแม่ว่า ''เอ-มิล-เล'' (เพราะแม่ของข้า)',
      'Cast in 771 AD during the Unified Silla Dynasty, the Bell of King Seongdeok (known colloquially as the Emille Bell) weighs nearly 19 tons. Legend holds that multiple attempts to cast the bell failed until a monk had a prophetic dream demanding the sacrifice of an innocent child. A peasant mother gave up her infant daughter, who was cast into the boiling bronze molten vat. When struck, the bell''s mournful acoustic resonance is said to weep: ''Emi-lleh'' (Mother''s fault).',
      'ระฆังเอมิลเลถูกเก็บรักษาไว้ที่พิพิธภัณฑสถานแห่งชาติคย็องจู และถือเป็นสมบัติประจำชาติหมายเลข 29 ของเกาหลีใต้ โดยปัจจุบันทางการได้สั่งห้ามตีระฆังเพื่ออนุรักษ์โบราณวัตถุ',
      'Although metallurgical testing found no trace of human phosphorus in the bronze alloy, the tragic folktale remains deeply embedded in Korean cultural consciousness and national lore.',
      'ห้ามแตะต้องหรือเคาะตัวระฆังทองสัมฤทธิ์โบราณ',
      'Never strike or touch the surface of the sacred King Seongdeok Bell.',
      'https://i.ytimg.com/vi/vbzUSYQDHM4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/vbzUSYQDHM4/hqdefault.jpg","title":"ระฆังเอมิลเลแห่งซิลลา (เสียงร่ำไห้ของทารกในเนื้อสัมฤทธิ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=vbzUSYQDHM4","title":"Tour episode l THE SCARY LEGEND OF THE DIVINE BELL OF KING SEONGDEOK","thumbnail":"https://i.ytimg.com/vi/vbzUSYQDHM4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-goddess-of-death-lemb',
      'รูปปั้นเทพีแห่งความตายแห่งเลมบ์ (อาถรรพ์เทวรูปกลืนชีวิต 4 ตระกูล)',
      'The Goddess of Death Statue of Lemb (The Cyprus Hex)',
      'curse',
      'พาฟอส',
      'Paphos',
      'เลมบา',
      'Lemba',
      34.8081,
      32.4086,
      'creepy_wind',
      'เทวรูปหินปูนโบราณแกะสลักรูปสตรีเปลือยยุคก่อนประวัติศาสตร์ อายุราว 3,500 ปีก่อนคริสตกาล ขุดพบที่หมู่บ้านเลมบาบนเกาะไซปรัส มีชื่อเสียงในฐานะ ''รูปปั้นเทพีแห่งความตาย'' เนื่องจากเจ้าของเทวรูปนี้ถึง 4 ตระกูลติดต่อกัน ต่างล้มตายจนสูญสิ้นทั้งตระกูลภายในเวลาไม่กี่ปี ครอบครัวสุดท้ายที่เหลือรอดเพียงพี่ชายสองคนตัดสินใจบริจาคเทวรูปนี้ให้แก่พิพิธภัณฑ์แห่งชาติสกอตแลนด์ ทว่าไม่นานหลังจากนั้น ภัณฑารักษ์ผู้รับมอบเทวรูปก็เสียชีวิตอย่างกะทันหัน',
      'Carved from pure limestone around 3500 BC in Cyprus, this ancient fertility idol became feared worldwide as the ''Goddess of Death''. Acquired by Lord Elphont, all seven members of his household died within six years. The statue passed through three more wealthy families—each suffering total annihilation of their family members within years. The surviving sons of the fourth family donated it to the National Museum of Scotland, where the curator who handled the accession died shortly after.',
      'ปัจจุบันรูปปั้นนี้ถูกเก็บรักษาไว้ในตู้กระจกนิรภัยภายในพิพิธภัณฑ์แห่งชาติสกอตแลนด์ที่เอดินเบอระ โดยไม่มีใครกล้าแตะต้องด้วยมือเปล่าอีกต่อไป',
      'Housed in Edinburgh, museum staff keep the artifact strictly behind sealed glass, retaining its reputation in British antiquarian circles as one of history''s deadliest artifacts.',
      'ห้ามนำเทวรูปออกจากตู้กระจกนิรภัย หรือสัมผัสหินปูนด้วยมือเปล่า',
      'Never attempt to touch or remove the Lemb limestone idol from its glass vault.',
      'https://i.ytimg.com/vi/_sqiLYqw968/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_sqiLYqw968/hqdefault.jpg","title":"รูปปั้นเทพีแห่งความตายแห่งเลมบ์ (อาถรรพ์เทวรูปกลืนชีวิต 4 ตระกูล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_sqiLYqw968","title":"The Goddess Of Death \"Women From Lemb Statue\"","thumbnail":"https://i.ytimg.com/vi/_sqiLYqw968/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-sancy-diamond-stolen',
      'คำสาปเพชรซองซี (เพชรสีเหลืองซีดในกระเพาะคนรับใช้ผู้ซื่อสัตย์)',
      'The Curse of the Sancy Diamond (The Bleached Yellow Hex)',
      'curse',
      'ปารีส',
      'Paris',
      'ปารีส',
      'Paris',
      48.8606,
      2.3376,
      'whisper',
      'เพชรสีเหลืองซีดรูปทรงหยดน้ำขนาด 55.23 กะรัตที่มีประวัติศาสตร์เปื้อนเลือด เคยเป็นของ ชาร์ลส์ เดอะ โบลด์ ดยุคแห่งเบอร์กันดี ผู้สวมเพชรนี้ออกรบก่อนถูกสังหารอย่างทารุณในสนามรบ ต่อมาตกเป็นของ นิโกลัส เดอ อาร์แล็ง เดอ ซองซี เขาได้ส่งคนรับใช้ผู้ซื่อสัตย์นำเพชรไปเป็นหลักประกันเงินกู้ ทว่าคนรับใช้ถูกโจรดักซุ่มโจมตี ก่อนตายเขาได้กลืนเพชรลงไปในท้อง เมื่อซองซีผ่าศพคนรับใช้ก็พบเพชรอยู่ในกระเพาะอาหาร คำสาปแห่งความตายยังคงติดตามกษัตริย์ยุโรปหลายพระองค์ที่ครอบครองเพชรนี้',
      'The Sancy is a 55.23-carat pale yellow diamond with origins in ancient India. Worn by Charles the Bold when he was slain in battle in 1477, it was later purchased by French ambassador Nicolas de Harlay, seigneur de Sancy. When a loyal courier carrying the gem was ambushed by thieves, he swallowed the diamond to protect it; Sancy later exhumed the loyal servant''s body and cut open his stomach to retrieve the gem. Tragic fates followed later royal owners, including King Charles I of England and King Louis XVI.',
      'ปัจจุบันเพชรซองซีถูกจัดแสดงอย่างปลอดภัยในหอศิลป์อะพอลโล พระราชวังลูฟวร์ ประเทศฝรั่งเศส เป็นหนึ่งในเพชรประวัติศาสตร์ที่เก่าแก่และสมบูรณ์ที่สุดในโลก',
      'Acquired by the Louvre Museum in 1978, the Sancy Diamond remains one of the crown jewels of French heritage, celebrated for its unique shield-cut facets.',
      'ห้ามเคาะหรือสัมผัสตู้กระจกจัดแสดงเพชรซองซีในพิพิธภัณฑ์ลูฟวร์',
      'Never touch or pound on the display case housing the Sancy Diamond in the Louvre.',
      'https://i.ytimg.com/vi/wik6P4sdq7Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/wik6P4sdq7Q/hqdefault.jpg","title":"คำสาปเพชรซองซี (เพชรสีเหลืองซีดในกระเพาะคนรับใช้ผู้ซื่อสัตย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=wik6P4sdq7Q","title":"The Secret History of Royal Jewels | Free Documentary","thumbnail":"https://i.ytimg.com/vi/wik6P4sdq7Q/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-florentine-diamond-habsburg',
      'เพชรฟลอเรนไทน์ที่สาบสูญ (คำสาปมรณะแห่งราชวงศ์ฮับส์บูร์ก)',
      'The Lost Florentine Diamond of the Habsburgs',
      'curse',
      'เวียนนา',
      'Vienna',
      'เวียนนา',
      'Vienna',
      48.2065,
      16.3653,
      'whisper',
      'เพชรสีเหลืองอมเขียวประกายสดใสขนาด 137.27 กะรัต เจียระไนเป็นรูปดาวเก้าแฉกคู่ เป็นมรดกล้ำค่าของตระกูลเมดิชีแห่งฟลอเรนซ์ ก่อนจะตกเป็นสมบัติของราชวงศ์ฮับส์บูร์กแห่งออสเตรีย มีตำนานเล่าว่าเพชรเม็ดนี้มีคำสาปของความล่มสลาย ผู้ครอบครองทุกคนต่างพบจุดจบอันน่าเศร้า พระนางมารี อ็องตัวแนต ถูกตัดศีรษะด้วยกิโยติน ดยุกฟรานซ์ เฟอร์ดินานด์ ถูกลอบสังหารจนเกิดสงครามโลกครั้งที่ 1 หลังสงครามจักรวรรดิฮับส์บูร์กล่มสลาย เพชรเม็ดนี้ถูกขโมยและสูญหายไปอย่างไร้ร่องรอยจนถึงปัจจุบัน',
      'The Florentine Diamond, an extraordinary 137.27-carat light yellow gem cut in an intricate double rose pattern, belonged to the Medici family before becoming the crown jewel of the Austrian Habsburgs. Tragedy tracked its possessors: Queen Marie Antoinette was beheaded in the French Revolution, and Archduke Franz Ferdinand was assassinated in 1914, triggering World War I and shattering the Austro-Hungarian Empire. During the imperial exile in 1918, the diamond was stolen and never seen again.',
      'นักประวัติศาสตร์เชื่อว่าเพชรฟลอเรนไทน์อาจถูกลักลอบนำไปตัดแบ่งเป็นเพชรเม็ดเล็กในสหรัฐอเมริกาเพื่อทำลายร่องรอย ทว่าชะตากรรมที่แท้จริงของมันยังคงเป็นหนึ่งในปริศนาอัญมณีที่ยิ่งใหญ่ที่สุดในโลก',
      'Rumored to have been recut into smaller stones in South America, the lost Florentine Diamond remains the Holy Grail of disappeared royal gem mysteries.',
      'ห้ามซื้อขายหรือครอบครองอัญมณีหลวงที่ถูกขโมยในระหว่างการล่มสลายของราชวงศ์',
      'Never trade or fence stolen imperial regalia plundered during war exile.',
      'https://i.ytimg.com/vi/uC3BmBRSp8Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/uC3BmBRSp8Y/hqdefault.jpg","title":"เพชรฟลอเรนไทน์ที่สาบสูญ (คำสาปมรณะแห่งราชวงศ์ฮับส์บูร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=uC3BmBRSp8Y","title":"FLORENTINE DIAMOND | Rare Habsburg Family Jewels Displayed Publicly For First Time","thumbnail":"https://i.ytimg.com/vi/uC3BmBRSp8Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-lake-ronkonkoma-drownings',
      'คำสาปทะเลสาบรอนคอนโคมา (เจ้าหญิงอินเดียนแดงตามหาคนรัก)',
      'The Lady of the Lake Curse of Lake Ronkonkoma (New York)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'ซัฟฟอล์ก',
      'Suffolk County',
      40.8312,
      -73.1189,
      'water_spirit',
      'ทะเลสาบน้ำจืดที่ใหญ่ที่สุดบนเกาะลองไอแลนด์ มีความลึกผิดปกติและไม่มีทางน้ำไหลออกตามธรรมชาติ ตำนานชนเผ่าพื้นเมืองเซตอว์เก็ตเล่าถึง เจ้าหญิงเบิร์ดส์-อะ-สวีต ผู้ตกหลุมรักหนุ่มผู้ตั้งถิ่นฐานผิวขาว ทว่าความรักถูกขัดขวางโดยบิดาของเธอ เจ้าหญิงพายเรือออกไปกลางทะเลสาบและใช้มีดแทงหัวใจตนเองจมน้ำเสียชีวิต คำสาประบุว่า ''ทุกๆ ปี เจ้าหญิงจะฉุดดึงชายหนุ่มหนึ่งคนลงไปจมน้ำตายใต้ก้นทะเลสาบเพื่อเป็นคนรักของเธอ'' สถิติระบุว่าผู้จมน้ำเสียชีวิตในทะเลสาบนี้เกือบทั้งหมดเป็นเพศชาย',
      'Lake Ronkonkoma is a deep kettle lake on Long Island with unusual subterranean currents. Native American folklore tells of Princess Birds-A-Sweet, who fell in love with a white settler. Forbidden from marrying him by her father, the heartbroken princess rowed into the middle of the lake and stabbed herself to death. The curse states that she claims at least one young male life each year to be her eternal lover; historical coroner records show that an overwhelming majority of drowning victims are young men.',
      'ชาวบ้านในท้องถิ่นเชื่อว่าก้นทะเลสาบเชื่อมต่อกับมหาสมุทรแอตแลนติกผ่านถ้ำใต้ดิน เนื่องจากร่างของผู้จมน้ำบางรายไม่เคยถูกพบในทะเลสาบ แต่กลับไปลอยอยู่ในอ่าวลองไอแลนด์ซาวด์',
      'Featured in Weird New York, the eerie statistical pattern of male drowning victims has kept the legend alive among local lifeguards and residents for generations.',
      'ผู้ชายห้ามลงไปว่ายน้ำกลางทะเลสาบรอนคอนโคมาคนเดียวในเวลาพลบค่ำ',
      'Young men are cautioned against swimming alone into the deep center waters of the lake.',
      'https://i.ytimg.com/vi/wqOlNMRDl0s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/wqOlNMRDl0s/hqdefault.jpg","title":"คำสาปทะเลสาบรอนคอนโคมา (เจ้าหญิงอินเดียนแดงตามหาคนรัก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=wqOlNMRDl0s","title":"Lady Of The Lake | The Haunted Tale Of Lake Ronkonkoma","thumbnail":"https://i.ytimg.com/vi/wqOlNMRDl0s/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-boleskine-house-crowley',
      'คฤหาสน์โบเลสคีน (พิธีกรรมอับราเมอลินและคำสาปอเลสเตอร์ โครว์ลีย์)',
      'Boleskine House & Aleister Crowley''s Dark Hex (Loch Ness)',
      'curse',
      'ไฮแลนด์',
      'Highland',
      'อินเวอร์เนสส์',
      'Inverness',
      57.2652,
      -4.4789,
      'creepy_wind',
      'คฤหาสน์โดดเดี่ยวริมชายฝั่งทะเลสาบเนสส์ ในปี 1899 อเลสเตอร์ โครว์ลีย์ ผู้ได้รับการขนานนามว่าเป็น ''ชายที่ชั่วร้ายที่สุดในโลก'' ได้ซื้อบ้านหลังนี้เพื่อทำพิธีกรรมอับราเมอลิน (Sacred Magic of Abramelin) ซึ่งเป็นพิธีกรรมมนต์ดำโบราณเพื่ออัญเชิญปีศาจทั้ง 115 ตนจากนรก ทว่าโครว์ลีย์ต้องละทิ้งพิธีกรรมกลางคันโดยไม่ได้ส่งปีศาจกลับลงไป ทำให้พลังงานชั่วร้ายสิงสถิตอยู่ในบ้าน ผู้ครอบครองต่อมา ทั้งมือกีตาร์ จิมมี เพจ แห่งวง Led Zeppelin ต่างเผชิญกับเรื่องสยองขวัญ และบ้านเกิดเพลิงไหม้ปริศนาถึงสองครั้ง',
      'Perched above the southeastern shores of Loch Ness, Boleskine House was bought in 1899 by occultist Aleister Crowley to perform the grueling six-month Sacred Magic of Abramelin the Mage, intended to summon the Guardian Angel alongside 115 infernal spirits. Summoned away abruptly to Paris, Crowley left the rituals uncompleted, leaving malevolent demonic entities unbanished. Subsequent owners suffered suicides, madness, and unexplained fires in 2015 and 2019.',
      'จิมมี เพจ มือกีตาร์วง Led Zeppelin ซื้อบ้านหลังนี้ในยุค 1970 เพื่อศึกษาศาสตร์ลี้ลับ ปัจจุบันมูลนิธิ Boleskine House Foundation กำลังอยู่ระหว่างการบูรณะอาคารประวัติศาสตร์แห่งนี้',
      'A pivotal site in occult history and modern rock folklore, Boleskine House connects ancient Scottish Highland lore with twentieth-century ceremonial magic.',
      'ห้ามทำพิธีกรรมไสยศาสตร์หรือบุกรุกเข้าไปในซากคฤหาสน์โบเลสคีน',
      'Never attempt unauthorized occult rituals or trespass on the Boleskine estate.',
      'https://i.ytimg.com/vi/593_RAHV7qs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/593_RAHV7qs/hqdefault.jpg","title":"คฤหาสน์โบเลสคีน (พิธีกรรมอับราเมอลินและคำสาปอเลสเตอร์ โครว์ลีย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=593_RAHV7qs","title":"Aleister Crowley: The Other Loch Ness Monster (2000)","thumbnail":"https://i.ytimg.com/vi/593_RAHV7qs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-unlucky-mummy-british-museum',
      'คำสาปมัมมี่โชคร้าย (แผ่นฝาโลงนักบวชหญิงแห่งอามุน-รา)',
      'The Unlucky Mummy of the British Museum (Priestess of Amun)',
      'curse',
      'ลอนดอน',
      'London',
      'แคมเดน',
      'Camden',
      51.5194,
      -0.127,
      'creepy_wind',
      'แผ่นฝาโลงไม้โบราณหมายเลข 22542 ของนักบวชหญิงแห่งวิหารอามุน-ราในนครเธบส์ ยุคราชวงศ์ที่ 21 มีใบหน้าสตรีสลักนูนต่ำที่งดงามทว่าแฝงความดุดัน ผู้ที่เกี่ยวข้องกับการขุดค้นและครอบครองฝาโลงนี้ในศตวรรษที่ 19 ต่างประสบเคราะห์ร้ายรุนแรง ชายหนุ่มผู้ซื้อถูกปืนลั่นใส่จนต้องตัดแขน เพื่อนร่วมคณะเสียชีวิตกระทันหันและล้มละลาย เมื่อถูกนำมามอบให้บริติชมิวเซียม ช่างภาพที่ถ่ายรูปฝาโลงเสียชีวิตในเวลาต่อมา และมีข่าวลือว่าฝาโลงนี้ถูกแอบขนขึ้นเรือไททานิคจนทำให้เรืออัปปาง',
      'Artifact No. 22542 at the British Museum is the painted mummy board of an unnamed priestess of Amun-Ra from Thebes (circa 950 BC). In the late 1800s, British travelers who purchased it in Luxor suffered catastrophic accidents: one was accidentally shot by his servant, another went bankrupt, and two died suddenly. When gifted to the museum, a photographer who took its portrait died soon after, sparking the worldwide legend that the mummy caused the sinking of the Titanic.',
      'แม้พิพิธภัณฑ์แห่งชาติอังกฤษจะยืนยันว่าฝาโลงไม่เคยถูกนำออกจากลอนดอนและไม่เคยอยู่บนเรือไททานิค แต่นักหนังสือพิมพ์ชื่อดัง วิลเลียม ที. สเตด ผู้เล่าเรื่องคำสาปนี้ กลับเสียชีวิตบนเรือไททานิคจริง',
      'Journalist W.T. Stead popularized the curse before tragically perishing aboard the Titanic in 1912. The mummy board remains one of the most requested exhibits in the British Museum.',
      'ห้ามจ้องมองดวงตาบนภาพสลักฝาโลงด้วยความดูหมิ่นเหยียดหยาม',
      'Never mock or disrespect the carved eyes of the Priestess of Amun-Ra.',
      'https://i.ytimg.com/vi/zuGIF0QgT9s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zuGIF0QgT9s/hqdefault.jpg","title":"คำสาปมัมมี่โชคร้าย (แผ่นฝาโลงนักบวชหญิงแห่งอามุน-รา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zuGIF0QgT9s","title":"The Unlucky Mummy - British Museum","thumbnail":"https://i.ytimg.com/vi/zuGIF0QgT9s/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-old-alton-bridge-goatman',
      'สะพานโอลด์อัลตัน (สะพานปีศาจมนุษย์แพะแห่งเท็กซัส)',
      'Old Alton Bridge & The Goatman''s Hex (Denton)',
      'curse',
      'เท็กซัส',
      'Texas',
      'เดนตัน',
      'Denton',
      33.1293,
      -97.1039,
      'creepy_wind',
      'สะพานโครงเหล็กโบราณที่สร้างข้ามลำห้วยคอปเปอร์แคนยอนในปี 1884 ตำนานเล่าถึง ออสการ์ วอชเบิร์น ชายผิวดำผู้เพาะพันธุ์แพะจนประสบความสำเร็จและได้รับฉายาว่า ''Goatman'' ทว่าเขาถูกกลุ่มเหยียดผิวเคเคเคบุกจับตัวและนำมาแขวนคอบนสะพาน เมื่อคนร้ายชะโงกหน้าลงไปดู พบว่าบ่วงเชือกว่างเปล่าและร่างของวอชเบิร์นหายไปอย่างไร้ร่องรอย นับแต่นั้นมีคำสาปว่า หากใครขับรถข้ามสะพานโดยดับไฟหน้า หรือเคาะราวสะพานสามครั้ง จะพบกับอสูรหัวแพะดวงตาสีแดงฉานพุ่งเข้าจู่โจม',
      'Built in 1884 across Copperas Creek, Old Alton Bridge is locally dubbed the ''Goatman''s Bridge''. Legend recalls Oscar Washburn, a successful Black goat farmer who was seized by a masked mob and thrown over the railing with a noose around his neck. Looking over the edge, the lynchers found an empty rope and no corpse below. Ever since, motorists who honk their horn twice on the bridge report phantom headlights, hoofbeats on the wooden deck, and a towering horned satyr-like beast.',
      'สะพานโอลด์อัลตันถูกปิดไม่ให้รถยนต์สัญจรในปี 2001 และปรับเป็นสะพานคนเดินในอุทยาน เป็นหนึ่งในสถานที่สำรวจปรากฏการณ์ลี้ลับที่มีชื่อเสียงที่สุดของรัฐเท็กซัส',
      'Featured on BuzzFeed Unsolved and Ghost Adventures, the bridge''s tragic racial history blends with urban Texas lore of a vengeful horned guardian lurking in the creek.',
      'ห้ามเคาะราวสะพานเหล็กสองครั้งในเวลาเที่ยงคืนเพื่อเรียกปีศาจแพะ',
      'Never knock twice on the iron bridge trestles at midnight to summon the Goatman.',
      'https://i.ytimg.com/vi/7fxjcJj1v0g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7fxjcJj1v0g/hqdefault.jpg","title":"สะพานโอลด์อัลตัน (สะพานปีศาจมนุษย์แพะแห่งเท็กซัส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7fxjcJj1v0g","title":"The Untold Story Of The Demonic Goatman''s Bridge - Texas","thumbnail":"https://i.ytimg.com/vi/7fxjcJj1v0g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-dead-children-playground-alabama',
      'สนามเด็กเล่นของวิญญาณ (เดด ชิลเดรนส์ เพลย์กราวด์ ฮันต์สวิลล์)',
      'Dead Children''s Playground (Maple Hill Cemetery)',
      'curse',
      'แอละแบมา',
      'Alabama',
      'ฮันต์สวิลล์',
      'Huntsville',
      34.7397,
      -86.5742,
      'whisper',
      'สนามเด็กเล่นที่ซ่อนตัวอยู่ในหุบเขาเล็กๆ ที่โอบล้อมด้วยหน้าผาหินปูนสูงชัน ติดกับสุสานเมเปิลฮิลล์ สุสานที่เก่าแก่ที่สุดของเมืองฮันต์สวิลล์ ซึ่งเป็นที่ฝังศพของเหยื่อเด็กจำนวนมากที่เสียชีวิตจากโรคระบาดไข้หวัดใหญ่สเปนในปี 1918 ในยามค่ำคืน ชิงช้าในสนามเด็กเล่นมักจะแกว่งไกวเองอย่างรุนแรงไปมาพร้อมกันโดยไม่มีลมพัด ผู้มาเยือนมักได้ยินเสียงหัวเราะกระซิบของเด็ก เสียงฝีเท้าเล็กๆ วิ่งบนขี้เลื่อย และเห็นลูกบอลแสงออร์บลอยวนเวียนรอบเครื่องเล่น',
      'Tucked inside a secluded limestone hollow surrounded by the cliffside graves of Maple Hill Cemetery lies a public park officially called Maple Hill Park, but known universally as Dead Children''s Playground. During the 1918 Spanish Flu pandemic, dozens of local infants and children were buried in adjacent plots. Visitors after dark observe swings rocking vigorously in unison on windless nights, alongside phantom giggles, tiny dust footprints, and glowing orbs hovering near the slide.',
      'ในปี 2007 เทศบาลเมืองเคยสั่งรื้อถอนเครื่องเล่นเพื่อขยายพื้นที่สุสาน ทว่าชาวเมืองต่างไม่พอใจและกดดันจนเทศบาลต้องติดตั้งอุปกรณ์สนามเด็กเล่นชุดใหม่เอี่ยมกลับคืนสู่สถานที่เดิม',
      'Public outcry forced the city to reinstall modern playground equipment in 2008, cementing this park as one of the South''s most tender yet eerie paranormal monuments.',
      'ห้ามทิ้งขยะ หรือทำลายของเล่นที่ผู้คนนำมาวางอุทิศให้วิญญาณเด็ก',
      'Never steal or vandalize toys left as memorial offerings on the swings.',
      'https://i.ytimg.com/vi/jgfOgvpsBvI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jgfOgvpsBvI/hqdefault.jpg","title":"สนามเด็กเล่นของวิญญาณ (เดด ชิลเดรนส์ เพลย์กราวด์ ฮันต์สวิลล์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jgfOgvpsBvI","title":"Haunted Huntsville - The Dead Children''s Playground","thumbnail":"https://i.ytimg.com/vi/jgfOgvpsBvI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-skirrid-mountain-inn-hangman',
      'โรงแรมสเกอร์ริดเมาน์เทนอินน์ (ผับตะแลงแกง 900 ปีแห่งเวลส์)',
      'The Skirrid Mountain Inn (The Hangman''s Pub of Wales)',
      'curse',
      'มอนมัทเชียร์',
      'Monmouthshire',
      'อะเบอร์กาวินนี',
      'Abergavenny',
      51.8797,
      -2.9778,
      'creepy_wind',
      'หนึ่งในผับและโรงแรมที่เก่าแก่ที่สุดในเวลส์ มีประวัติย้อนหลังไปกว่า 900 ปี ในศตวรรษที่ 17 ระหว่างการกบฏมอนมัท ชั้นหนึ่งของผับถูกใช้เป็นศาลพิพากษาของ ''ผู้พิพากษาจอมแขวนคอ'' จอร์จ เจฟฟรีย์ส และคานไม้โอ๊กโบราณเหนือบันไดถูกใช้เป็นตะแลงแกงแขวนคอนักโทษไปมากกว่า 180 คน จนถึงปัจจุบัน รอยบากของเชือกป่านยังคงฝังลึกอยู่ในเนื้อไม้ แขกที่มาพักมักรู้สึกเหมือนมีบ่วงเชือกที่มองไม่เห็นรัดคอจนหายใจไม่ออก และได้ยินเสียงชักดิ้นชักงอของนักโทษ',
      'Claiming an unbroken lineage stretching back nine centuries, the Skirrid Mountain Inn served as a court of law during the Monmouth Rebellion under the infamous ''Hanging Judge'' George Jeffreys. Over 180 rebels and convicts were summarily sentenced and hanged directly from the heavy oak beam above the staircase; deep rope friction grooves remain visible in the wood today. Overnight guests report sudden sensations of invisible nooses tightening around their throats and gasping footsteps on the landing.',
      'โรงแรมสเกอร์ริดตั้งอยู่ใกล้กับภูเขาสเกอร์ริดฟอว์ ซึ่งตำนานเวลส์เล่าว่าภูเขาได้แตกแยกออกเป็นสองส่วนในวันที่พระเยซูคริสต์ถูกตรึงกางเขน ทำให้พื้นที่แถบนี้เปี่ยมด้วยความเชื่อเรื่องอาถรรพ์โบราณ',
      'Featuring heavily on British paranormal programs like Most Haunted, the inn embraces its grim judicial past while serving traditional Welsh ales beside the execution beam.',
      'ห้ามนำบ่วงเชือกคล้องคอตัวเองเล่นใต้คานไม้แขวนคอโบราณ',
      'Never place a mock noose around your neck beneath the historic execution beam.',
      'https://i.ytimg.com/vi/25cPM8iV1qE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/25cPM8iV1qE/hqdefault.jpg","title":"โรงแรมสเกอร์ริดเมาน์เทนอินน์ (ผับตะแลงแกง 900 ปีแห่งเวลส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=25cPM8iV1qE","title":"Real Paranormal at Wales’ Most Haunted Inn… | Skirrid Mountain Inn","thumbnail":"https://i.ytimg.com/vi/25cPM8iV1qE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-tramping-ground-nc',
      'ลานเหยียบย่ำของพญามาร (วงกลมดินอาถรรพ์ที่ไม่มีพืชขึ้นแห่งนอร์ทแคโรไลนา)',
      'The Devil''s Tramping Ground (Chatham County)',
      'curse',
      'นอร์ทแคโรไลนา',
      'North Carolina',
      'แชทแฮม',
      'Chatham County',
      35.5847,
      -79.4883,
      'creepy_wind',
      'วงกลมดินปริศนาเส้นผ่านศูนย์กลาง 40 ฟุตกลางป่าทึบใกล้เมืองเบียริงครีก ซึ่งไม่มีต้นไม้ ใบหญ้า หรือมอสส์ชนิดใดสามารถเจริญเติบโตได้เลยนับตั้งแต่เริ่มมีการบันทึกในศตวรรษที่ 18 ตำนานพื้นบ้านเล่าว่า ในยามค่ำคืนพญามารจะขึ้นมาเดินวนเป็นวงกลมเพื่อครุ่นคิดแผนการทำลายล้างมนุษยชาติ กิ่งไม้หรือสิ่งของใดๆ ที่คนนำไปวางไว้ในวงกลมตอนหัวค่ำ จะถูกพลังงานที่มองไม่เห็นผลักหรือโยนออกไปนอกวงกลมจนหมดสิ้นก่อนรุ่งเช้า สัตว์ป่าและสุนัขจะส่งเสียงเห่าหอนและไม่ยอมก้าวเหยียบเข้าไปในวงกลมเด็ดขาด',
      'Located in the woods near Siler City, the Devil''s Tramping Ground is a barren 40-foot circular clearing where no vegetation has grown for centuries. North Carolina lore asserts that every night at the witching hour, the Devil paces in circles within the perimeter, contemplating evil schemes against humankind. Any object placed inside the circle at dusk—whether stones, branches, or tent stakes—is violently ejected outside the perimeter by morning, while dogs cower and whimper at its edge.',
      'นักปฐพีวิทยาของกระทรวงเกษตรสหรัฐฯ เคยนำตัวอย่างดินไปตรวจวิเคราะห์ แต่ไม่พบสารพิษหรือความเป็นกรดด่างที่ผิดปกติใดๆ ที่จะอธิบายว่าเหตุใดพืชจึงไม่ยอมขึ้น',
      'Investigated by state agricultural scientists, soil samples failed to reveal chemical anomalies explaining the complete sterile barrenness, cementing its status as North Carolina''s oldest mystery.',
      'ห้ามกางเต็นท์นอนค้างแรมในใจกลางวงกลมดินอาถรรพ์',
      'Never attempt to pitch a tent and sleep inside the barren circle overnight.',
      'https://i.ytimg.com/vi/Xc68WAdGgKo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Xc68WAdGgKo/hqdefault.jpg","title":"ลานเหยียบย่ำของพญามาร (วงกลมดินอาถรรพ์ที่ไม่มีพืชขึ้นแห่งนอร์ทแคโรไลนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Xc68WAdGgKo","title":"The Devil''s Tramping Ground: The Spot Where Nothing Grows","thumbnail":"https://i.ytimg.com/vi/Xc68WAdGgKo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-whaley-house-san-diego',
      'บ้านตระกูลฮวาเลย์ (บ้านผีดุที่สุดในอเมริกาแห่งซานดิเอโก)',
      'The Whaley House (America''s Most Haunted Residence)',
      'ghost',
      'แคลิฟอร์เนีย',
      'California',
      'ซานดิเอโก',
      'San Diego',
      32.7533,
      -117.1939,
      'whisper',
      'บ้านอิฐเก่าแก่สองชั้นในโอลด์ทาวน์ซานดิเอโก สร้างขึ้นในปี 1857 โดย โทมัส ฮวาเลย์ บนพื้นที่ที่เคยเป็นลานประหารชีวิตด้วยการแขวนคอของเมือง โดยเฉพาะการแขวนคอจอมโจรชื่อดัง ''แยงกี้ จิม'' โรบินสัน ตั้งแต่ก่อนสร้างบ้านเสร็จ ครอบครัวฮวาเลย์ได้ยินเสียงฝีเท้าหนักๆ ของรองเท้าบู๊ตเดินอยู่บนชั้นสอง ต่อมาทารกของตระกูลเสียชีวิตด้วยไข้หวัดใหญ่ และลูกสาว วิโอเล็ต ยิงตัวตายหลังหย่าร้าง ผู้มาเยือนมักเห็นวิญญาณของโทมัสสวมหมวกทรงสูง และกลิ่นซิการ์ลอยคลุ้งในห้องรับแขก',
      'Erected in 1857 by merchant Thomas Whaley, this Greek Revival home was built directly over Old San Diego''s public gallows where thief ''Yankee Jim'' Robinson was hanged in 1852. Even as construction began, heavy thumping boot steps were heard pacing the floorboards. Family tragedies compounded the haunting: an infant died of scarlet fever, and daughter Violet committed suicide here in 1885. The US Commerce Department officially certified the Whaley House as ''haunted'' in the 1960s.',
      'นิตยสาร LIFE และรายการโทรทัศน์หลายสำนักยกให้บ้านฮวาเลย์เป็น ''บ้านที่มีผีดุที่สุดในสหรัฐอเมริกา'' ปัจจุบันเปิดเป็นพิพิธภัณฑ์ประวัติศาสตร์ที่มีชื่อเสียงที่สุดของรัฐแคลิฟอร์เนีย',
      'Documented extensively by the San Diego Historical Society, the Whaley House is preserved with period-accurate mid-19th-century furnishings and historical courtroom exhibits.',
      'ห้ามท้าทายวิญญาณแยงกี้ จิม บริเวณซุ้มประตูด้านหน้าที่เคยเป็นจุดตั้งตะแลงแกง',
      'Never utter taunts to Yankee Jim near the archway that marked the gallows site.',
      'https://i.ytimg.com/vi/ToaTWwUxR2o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ToaTWwUxR2o/hqdefault.jpg","title":"บ้านตระกูลฮวาเลย์ (บ้านผีดุที่สุดในอเมริกาแห่งซานดิเอโก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ToaTWwUxR2o","title":"WHALEY HOUSE TOUR | Inside America''s Most Haunted House | San Diego, CA","thumbnail":"https://i.ytimg.com/vi/ToaTWwUxR2o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-crescent-hotel-room-218',
      'โรงแรมเครสเซนต์และห้อง 218 (โรงพยาบาลลวงโลกแห่งอาร์คันซอ)',
      'The 1886 Crescent Hotel & Spa (Room 218 Hauntings)',
      'ghost',
      'อาร์คันซอ',
      'Arkansas',
      'ยูเรกาสปริงส์',
      'Eureka Springs',
      36.4069,
      -93.7381,
      'whisper',
      'โรงแรมหินปูนสไตล์วิกตอเรียนบนยอดเขาโอซาร์ก สร้างขึ้นในปี 1886 ในยุค 1930 นอร์แมน เบเกอร์ แพทย์จอมปลอมได้เปลี่ยนโรงแรมให้เป็น ''โรงพยาบาลรักษามะเร็ง'' หลอกลวงผู้ป่วยนับร้อยด้วยการฉีดน้ำยาผสมหินปูนจนผู้ป่วยทุกข์ทรมานเสียชีวิตในห้องใต้ดิน วิญญาณที่โด่งดังที่สุดคือ ''ไมเคิล'' ช่างตัดหินชาวไอริชที่พลัดตกจากหลังคาห้อง 218 เสียชีวิตระหว่างการก่อสร้าง แขกที่พักห้องนี้มักเห็นมือลึกลับเอื้อมออกมาจากกระจก และเสียงเคาะประตูห้องน้ำจากด้านใน',
      'Perched atop the Ozark Mountains, the Crescent Hotel holds a gruesome past. In 1937, fraudulent radio charlatan Norman Baker converted the resort into a bogus cancer hospital, scamming and torturing hundreds of terminal patients until they perished in his basement morgue. In Room 218, guests encounter ''Michael'', an Irish stonemason who fell to his death during the 1886 construction; visitors report cold phantom hands touching their faces and the bathroom mirror vibrating.',
      'ในปี 2019 คนสวนของโรงแรมได้ขุดพบขวดโหลแก้วโบราณนับร้อยใบที่นอร์แมน เบเกอร์ ฝังไว้หลังโรงแรม ภายในบรรจุชิ้นส่วนเนื้อเยื่อมนุษย์และตัวอย่างเนื้องอกมะเร็งจริง',
      'Featured on Ghost Hunters, the discovery of Baker''s buried specimen jars in 2019 made international headlines, corroborating the grim historical malpractice on the grounds.',
      'ห้ามนั่งบนเตียงห้อง 218 และตะโกนท้าทายช่างตัดหินไมเคิล',
      'Never taunt Michael the stonemason while staying overnight in Room 218.',
      'https://i.ytimg.com/vi/yrgmK5nePxY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yrgmK5nePxY/hqdefault.jpg","title":"โรงแรมเครสเซนต์และห้อง 218 (โรงพยาบาลลวงโลกแห่งอาร์คันซอ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yrgmK5nePxY","title":"The Dark Story of America''s Most Haunted Hotel: The Crescent Hotel","thumbnail":"https://i.ytimg.com/vi/yrgmK5nePxY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-bachelors-grove-monk-cemetery',
      'สุสานแบชเลอร์สโกรฟ (สุสานผีดุและสตรีในชุดขาวแห่งชิคาโก)',
      'Bachelor''s Grove Cemetery & The Madonna of Bachelor''s Grove',
      'ghost',
      'อิลลินอยส์',
      'Illinois',
      'คุกเคาน์ตี',
      'Midlothian',
      41.6311,
      -87.7714,
      'creepy_wind',
      'สุสานร้างในศตวรรษที่ 19 ที่ซ่อนตัวอยู่ในเขตอนุรักษ์ป่ารูบิโอวูดส์ ใกล้เมืองชิคาโก ได้รับการยกย่องเป็นหนึ่งในสุสานที่มีผีดุที่สุดในโลก ในยุคห้ามจำหน่ายสุรา บ่อน้ำข้างสุสานเคยเป็นที่ทิ้งศพของแก๊งสเตอร์อัล คาโปน ภาพถ่ายผีที่โด่งดังที่สุดในประวัติศาสตร์ (The Madonna of Bachelor''s Grove) ถูกถ่ายขึ้นที่นี่ในปี 1991 เผยให้เห็นหญิงสาวโปร่งแสงนั่งอย่างโดดเดี่ยวบนแผ่นป้ายหลุมศพ นอกจากนี้ยังมีรายงานบ้านผีสิงสีขาวที่ปรากฏขึ้นและค่อยๆ ย่อส่วนเล็กลงจนหายไป',
      'Hidden deep inside the Rubio Woods Forest Preserve, Bachelor''s Grove is an abandoned 19th-century cemetery notorious for intense paranormal activity. During Prohibition, Al Capone''s Chicago Mob used its stagnant lagoon to dump murder victims. In 1991, the Ghost Research Society captured the famous ''Madonna of Bachelor''s Grove'' photograph showing a semi-transparent woman in white sitting on a tombstone. Other phenomena include a phantom farmhouse that shrinks as witnesses approach.',
      'ภาพถ่ายมาดอนนาแห่งแบชเลอร์สโกรฟได้รับการตีพิมพ์ใน Chicago Sun-Times และนิตยสาร National Geographic World ในฐานะหนึ่งในภาพถ่ายติดวิญญาณที่ยากจะอธิบายได้ทางวิทยาศาสตร์',
      'Heavily vandalized in the 1970s, the cemetery is preserved by local historians, remaining a legend tripping destination for generations of Midwesterners.',
      'ห้ามขีดเขียน หรือทำลายป้ายหลุมศพโบราณในสุสานร้างเด็ดขาด',
      'Never desecrate or vandalize historic tombstones within the forest preserve.',
      'https://i.ytimg.com/vi/vIbLakE7ASw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/vIbLakE7ASw/hqdefault.jpg","title":"สุสานแบชเลอร์สโกรฟ (สุสานผีดุและสตรีในชุดขาวแห่งชิคาโก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=vIbLakE7ASw","title":"BACHELOR’S GROVE: The MOST HAUNTED Place In America (HORRIFYING Paranormal Activity)","thumbnail":"https://i.ytimg.com/vi/vIbLakE7ASw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-st-augustine-lighthouse-girls',
      'ประภาคารเซนต์ออกัสติน (เสียงหัวเราะของเด็กหญิงในหอคอย)',
      'The Ghost Girls of St. Augustine Lighthouse',
      'ghost',
      'ฟลอริดา',
      'Florida',
      'เซนต์ออกัสติน',
      'St. Augustine',
      29.8736,
      -81.2881,
      'water_spirit',
      'ประภาคารอิฐสูง 165 ฟุตที่สร้างขึ้นในปี 1874 ริมชายฝั่งแอตแลนติก ในระหว่างการก่อสร้างในปี 1873 เด็กหญิงสามคน ซึ่งเป็นบุตรสาวของผู้คุมงานก่อสร้าง ไฮเซเกียล พิตตี กำลังเล่นรถเข็นรางขนส่งวัสดุอย่างสนุกสนาน ทว่าสลักเบรกเกิดหลุด ทำให้รถเข็นพุ่งทะยานตกจากหน้าผาลงสู่ทะเลลึก เด็กหญิงทั้งสามจมน้ำเสียชีวิตอย่างน่าเศร้า จนถึงปัจจุบัน ผู้ดูแลประภาคารมักได้ยินเสียงเด็กผู้หญิงหัวเราะและวิ่งขึ้นลงบันไดวน 219 ขั้น และมีพยานเห็นเด็กหญิงในชุดลูกไม้สีฟ้าเกาะราวระเบียงโคมไฟบนยอดประภาคาร',
      'Standing 165 feet above Anastasia Island, the St. Augustine Lighthouse is haunted by a tragic Victorian accident. In 1873, during tower construction, three young daughters of superintendent Hezekiah Pittee were playing in a wooden rail supply cart when the retaining wooden stop broke, plunging the cart into the churning ocean where all three drowned. Keepers and tourists regularly hear youthful giggling echoes on the 219 spiral stairs and spot a girl in a blue ruffled dress peering down from the catwalk.',
      'ประภาคารแห่งนี้เป็นสถานที่ถ่ายทำตอนแรกสุดที่มีชื่อเสียงของรายการ Ghost Hunters (Syfy) ซึ่งสามารถบันทึกภาพเงาดำที่ชะโงกหน้ามองลงมาจากบันไดวนบนยอดหอคอยได้อย่างชัดเจน',
      'Featured as a landmark episode of Syfy''s Ghost Hunters, the lighthouse operates as an active maritime museum, hosting popular nighttime ''Dark of the Moon'' tours.',
      'ห้ามวิ่งเล่นหรือล้อเลียนเสียงเด็กร้องไห้บนบันไดวนของประภาคาร',
      'Never run recklessly or mock the laughter of the Pittee sisters on the spiral staircase.',
      'https://i.ytimg.com/vi/fU-8Rg4CgeI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fU-8Rg4CgeI/hqdefault.jpg","title":"ประภาคารเซนต์ออกัสติน (เสียงหัวเราะของเด็กหญิงในหอคอย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fU-8Rg4CgeI","title":"The Haunted Shadows Of The St. Augustine Lighthouse","thumbnail":"https://i.ytimg.com/vi/fU-8Rg4CgeI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-farnsworth-house-confederates',
      'คฤหาสน์ฟาร์นสเวิร์ธ (รังซุ่มยิงสไนเปอร์แห่งสมรภูมิเกตตีสเบิร์ก)',
      'The Farnsworth House Inn (Gettysburg Sniper Ghosts)',
      'ghost',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'เกตตีสเบิร์ก',
      'Gettysburg',
      39.8273,
      -77.2347,
      'creepy_wind',
      'บ้านอิฐในเมืองเกตตีสเบิร์กที่เคยเป็นรังซุ่มยิงของพลแม่นปืนฝ่ายสมาพันธรัฐ (ฝ่ายใต้) ในระหว่างศึกเกตตีสเบิร์กปี 1863 รอยกระสุนปืนกว่า 100 นัดยังคงฝังแน่นอยู่บนผนังอิฐด้านทิศใต้ เชื่อกันว่ากระสุนที่ยิงสังหาร เจนนี เวด (พลเรือนหญิงเพียงคนเดียวที่เสียชีวิตในสมรภูมิ) ถูกยิงออกไปจากหน้าต่างห้องใต้หลังคาของบ้านหลังนี้ แขกที่เข้าพักมักได้ยินเสียงฝีเท้าของทหารเดินบนชั้นบน กลิ่นดินปืนและกลิ่นยาสูบโบราณลอยคลุ้ง และมีทหารในเครื่องแบบสีเทานั่งมองที่ปลายเตียง',
      'During the decisive Battle of Gettysburg in July 1863, Confederate sharpshooters occupied the brick Farnsworth House, using the garret windows to pick off Union soldiers. Over 100 bullet holes still pockmark the exterior masonry wall. Historians believe the fatal stray bullet that killed Jenny Wade—the only civilian fatality of the battle—was fired from this very attic. Guests in the inn report being tucked in by unseen hands, hearing pacing boots overhead, and smelling pungent black powder.',
      'เกตตีสเบิร์กได้รับการยกย่องเป็นหนึ่งในสมรภูมิรบที่มีผีดุที่สุดในโลก มีการจัดทัวร์ประวัติศาสตร์และทัวร์ผีรอบคฤหาสน์ฟาร์นสเวิร์ธอย่างต่อเนื่องยาวนานหลายสิบปี',
      'Preserving authentic Civil War artifacts, bone saws, and sharpshooter nests, the Farnsworth House is celebrated in American travel guides as a quintessential haunted battlefield landmark.',
      'ห้ามเปิดหน้าต่างห้องใต้หลังคาเพื่อส่องไฟหรือตะโกนท้าทายทหารฝ่ายใต้',
      'Never open the historic garret sniper windows or mock the Confederate sentries.',
      'https://i.ytimg.com/vi/p-L0WIQsi5o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/p-L0WIQsi5o/hqdefault.jpg","title":"คฤหาสน์ฟาร์นสเวิร์ธ (รังซุ่มยิงสไนเปอร์แห่งสมรภูมิเกตตีสเบิร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=p-L0WIQsi5o","title":"The Gettysburg Ghosts of Farnsworth House Inn","thumbnail":"https://i.ytimg.com/vi/p-L0WIQsi5o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-titanic-shipyard-harland-wolff',
      'อู่ต่อเรือฮาร์แลนด์แอนด์วูลฟฟ์ (วิญญาณคนงานเรือไททานิคแห่งเบลฟาสต์)',
      'Harland & Wolff Shipyard & Titanic''s Phantom Workers',
      'ghost',
      'เบลฟาสต์',
      'Belfast',
      'เบลฟาสต์',
      'Belfast',
      54.6078,
      -5.9103,
      'water_spirit',
      'อู่ต่อเรือระดับตำนานในกรุงเบลฟาสต์ ประเทศไอร์แลนด์เหนือ สถานที่ก่อสร้างเรืออาร์เอ็มเอส ไททานิค ในระหว่างการสร้างเรือยักษ์ระหว่างปี 1909-1911 มีคนงานเรือเสียชีวิตจากอุบัติเหตุตกจากนั่งร้าน แผ่นเหล็กทับ และไฟไหม้ถึง 8 คน มีเรื่องเล่าขานว่าคนงานคนหนึ่งถูกแผ่นเหล็กตัวเรือเชื่อมทับร่างปิดตายทั้งเป็นอยู่ภายในช่องท้องเรือ ผู้คนที่ทำงานในอู่ต่อเรือและนักท่องเที่ยวในพิพิธภัณฑ์ไททานิกมักได้ยินเสียงค้อนตอกหมุดโลหะดังกึกก้องในความว่างเปล่า และเสียงเคาะขอความช่วยเหลือจากก้นบ่อแห้งทอมป์สัน',
      'At Queen''s Island in Belfast stands the historic dry dock of Harland & Wolff where RMS Titanic was built. Eight shipbuilders died during the construction of the Olympic-class liners. A persistent shipyard urban legend claims a riveter was accidentally trapped and sealed alive between the double hull plates. Long after the ship set sail, engineers in Thompson Graving Dock report hearing rhythmic phantom hammerings upon iron bulkheads and desperate taps echoing from empty steel chambers.',
      'ปัจจุบันพื้นที่รอบอู่ต่อเรือได้รับการฟื้นฟูเป็นเขตไททานิกควอเตอร์ (Titanic Quarter) และเป็นที่ตั้งของพิพิธภัณฑ์ Titanic Belfast ซึ่งได้รับรางวัลแหล่งท่องเที่ยวยอดเยี่ยมของโลก',
      'The dry dock and pump house remain intact as monumental relics of early 20th-century marine engineering, surrounded by centuries of Belfast dockland folklore.',
      'ห้ามเดินลงไปในก้นบ่ออู่แห้งทอมป์สัน (Thompson Dry Dock) ในเวลาค่ำคืน',
      'Never explore the damp floor of Thompson Graving Dock alone after dark.',
      'https://i.ytimg.com/vi/W_ybW4_A9zs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/W_ybW4_A9zs/hqdefault.jpg","title":"อู่ต่อเรือฮาร์แลนด์แอนด์วูลฟฟ์ (วิญญาณคนงานเรือไททานิคแห่งเบลฟาสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=W_ybW4_A9zs","title":"Titanic Flotation Dock, Harland & Wolff Shipyard, Belfast, 30/8/09","thumbnail":"https://i.ytimg.com/vi/W_ybW4_A9zs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-edinburgh-castle-lone-piper',
      'ปราสาทเอดินบะระและนักเป่าปี่สก็อตที่หายสาบสูญ',
      'Edinburgh Castle & The Lost Lone Piper of the Dungeons',
      'ghost',
      'เอดินบะระ',
      'City of Edinburgh',
      'เอดินบะระ',
      'Edinburgh',
      55.9486,
      -3.1999,
      'creepy_wind',
      'ปราสาทหินป้อมปราการบนยอดภูเขาไฟโบราณใจกลางเมืองหลวงสกอตแลนด์ เมื่อหลายร้อยปีก่อน มีการค้นพบอุโมงค์ลับใต้ดินที่ทอดยาวจากปราสาทไปยังรอยัลไมล์ ทางการได้ส่งเด็กชายนักเป่าปี่สก็อตเดินลงไปสำรวจ โดยให้เป่าปี่ตลอดเวลาเพื่อให้คนบนผิวดินตามเสียงได้ ทว่าเมื่อมาถึงบริเวณหน้าคฤหาสน์ทรอนเคิร์ก เสียงปี่กลับหยุดชะงักลงอย่างกะทันหัน ทีมกู้ภัยลงไปค้นหาแต่ไม่พบร่องรอยของเด็กชายเลย นับแต่นั้นในยามค่ำคืน ผู้คนมักได้ยินเสียงปี่สก็อตเพลงเศร้าดังแว่วขึ้นมาจากใต้ผืนหินปูถนน',
      'Dominating the Scottish capital from an extinct volcanic plug, Edinburgh Castle is riddled with ancient tunnels. Centuries ago, when a secret subterranean passage to Holyroodhouse was discovered, a young piper boy was sent down, instructed to play continuously so guards above could trace his progress. Halfway down the Royal Mile, the music abruptly ceased. Rescuers found the tunnel collapsed and the boy vanished forever. To this day, his sorrowful bagpipe melody echoes from beneath the cobblestones.',
      'ในปี 2001 ดร. ริชาร์ด ไวส์แมน นักจิตวิทยาแห่งมหาวิทยาลัยฮาร์ตฟอร์ดเชียร์ ได้นำทีมนักวิทยาศาสตร์และอาสาสมัครกว่า 200 คนมาทดลองสัมผัสวิญญาณในปราสาทเอดินบะระ ซึ่งผลลัพธ์พบปรากฏการณ์จุดเย็นยะเยือกและเสียงแปลกปลอมอย่างมีนัยสำคัญ',
      'Edinburgh Castle''s 2001 extensive scientific paranormal survey remains one of the largest academic ghost studies ever conducted, confirming consistent psychological and thermal anomalies.',
      'ห้ามเป่าปี่สก็อตเลียนแบบทำนองเพลงโบราณในอุโมงค์ใต้ปราสาท',
      'Never play mock bagpipe tunes while walking through the castle vaults.',
      'https://i.ytimg.com/vi/GiFsqiGldPQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/GiFsqiGldPQ/hqdefault.jpg","title":"ปราสาทเอดินบะระและนักเป่าปี่สก็อตที่หายสาบสูญ"},{"type":"youtube","url":"https://www.youtube.com/watch?v=GiFsqiGldPQ","title":"The Dark Truth Behind Edinburgh Castle’s Lost Piper","thumbnail":"https://i.ytimg.com/vi/GiFsqiGldPQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-glamis-castle-secret-monster',
      'ปราสาทกลามิส (อสูรกายห้องลับและสตรีสีเทาแห่งสก็อตแลนด์)',
      'Glamis Castle & The Secret Monster of Strathmore',
      'ghost',
      'แองกัส',
      'Angus',
      'กลามิส',
      'Glamis',
      56.6203,
      -3.0025,
      'whisper',
      'ปราสาทในศตวรรษที่ 14 ที่งดงามและลึกลับที่สุดในสก็อตแลนด์ เป็นบ้านในวัยเด็กของสมเด็จพระราชินีเอลิซาเบธ พระราชชนนี มีตำนานเล่าถึง ''อสูรกายแห่งกลามิส'' ทารกที่เกิดมามีรูปร่างพิการอัปลักษณ์ผิดมนุษย์ในตระกูลเอิร์ลแห่งสตราธมอร์ จึงถูกขังไว้ในห้องลับที่ไม่มีหน้าต่างตลอดชีวิต นอกจากนี้ยังมีวิญญาณของ ''สตรีสีเทา'' (เจเน็ต ดักลาส เลดี้แห่งกลามิส) ผู้ถูกพระเจ้าเจมส์ที่ 5 สั่งเผาทั้งเป็นในข้อหาเป็นแม่มด มักปรากฏตัวคุกเข่าสวดมนต์ในโบสถ์น้อยของปราสาท',
      'Glamis Castle, ancestral seat of the Earls of Strathmore and childhood home of Queen Elizabeth The Queen Mother, is renowned for the ''Monster of Glamis''—a deformed heir born in 1821 who was supposedly walled up alive in a secret chamber hidden within the massive stone walls. The castle is also haunted by Lady Janet Douglas, burned at the stake for witchcraft on Castle Hill in 1537; her glowing ''Grey Lady'' specter kneels in silent prayer in the family chapel.',
      'แขกในศตวรรษที่ 19 เคยพยายามหาห้องลับด้วยการนำผ้าเช็ดหน้าสีขาวไปผูกไว้ที่หน้าต่างทุกบานของปราสาท ทว่าเมื่อมองจากภายนอก กลับพบว่ามีหน้าต่างบานหนึ่งที่ไม่มีผ้าเช็ดหน้าผูก ยืนยันว่ามีห้องลับซ่อนอยู่จริง',
      'Shakespeare set his tragedy Macbeth at Glamis. The legend of the hidden chamber and the Countess of Strathmore is preserved as an iconic staple of British aristocratic folklore.',
      'ห้ามนั่งลงบนเก้าอี้ส่วนพระองค์ของสตรีสีเทาในโบสถ์น้อยของปราสาท',
      'Never sit in the designated empty chair reserved for the Grey Lady in the chapel.',
      'https://i.ytimg.com/vi/sHbK7YsTVEw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/sHbK7YsTVEw/hqdefault.jpg","title":"ปราสาทกลามิส (อสูรกายห้องลับและสตรีสีเทาแห่งสก็อตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sHbK7YsTVEw","title":"Ghostly Tales of Glamis Castle - The Grey Lady","thumbnail":"https://i.ytimg.com/vi/sHbK7YsTVEw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-inveraray-castle-harpist',
      'ปราสาทอินเวอราเรย์ (วิญญาณนักเล่นพิณฮาร์ปแห่งตระกูลแคมป์เบลล์)',
      'Inveraray Castle & The Phantom Harpist of Argyll',
      'ghost',
      'อาร์ไกล์และบิวต์',
      'Argyll and Bute',
      'อินเวอราเรย์',
      'Inveraray',
      56.2375,
      -5.0736,
      'water_spirit',
      'ปราสาทสไตล์โกธิกฟื้นฟูอันสง่างามริมชายฝั่งทะเลสาบไฟน์ ที่พำนักของดยุกแห่งอาร์ไกล์ หัวหน้าตระกูลแคมป์เบลล์ ในปี 1644 กองทัพของดยุกแห่งมอนโทรสได้บุกเข้าทำลายปราสาท นักเล่นพิณฮาร์ปประจำตระกูลถูกทหารฝ่ายศัตรูสังหารอย่างทารุณบนเตียงนอน วิญญาณของเขายังคงผูกพันกับปราสาทแห่งนี้ ในยามค่ำคืน แขกผู้มาเยือนห้องสมุดมักได้ยินเสียงดนตรีพิณฮาร์ปโบราณบรรเลงทำนองเศร้าสร้อยลอยมาตามสายลม โดยเฉพาะในคราวที่ดยุกแห่งอาร์ไกล์คนใดกำลังจะถึงแก่อสัญกรรม',
      'Nestled along the shores of Loch Fyne, Inveraray Castle is the ancestral seat of the Duke of Argyll, chief of Clan Campbell. In 1644, during the Wars of the Three Kingdoms, the castle was stormed by the Marquess of Montrose''s men, who murdered the Duke''s court harpist in his bed. The young musician''s ghost lingers in the MacArthur Room; ethereal, melancholy harp melodies resonate through empty corridors, traditionally serving as a supernatural death omen for the Campbell family.',
      'ปราสาทอินเวอราเรย์ปรากฏในซีรีส์ชื่อดัง Downton Abbey ในตอนพิเศษวันคริสต์มาสปี 2012 ในฐานะ ''ปราสาทดูนีเกิล'' (Duneagle Castle)',
      'Inveraray Castle combines baronial grandeur with centuries of Highland folklore, maintaining an extensive armory hall displaying antique Campbell swords and muskets.',
      'ห้ามแตะต้องเตียงแกะสลักโบราณในห้องมาคาร์เธอร์ที่นักเล่นพิณถูกสังหาร',
      'Never touch or disturb the carved bedstead in the MacArthur Room.',
      'https://i.ytimg.com/vi/LBi-LQt4q50/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/LBi-LQt4q50/hqdefault.jpg","title":"ปราสาทอินเวอราเรย์ (วิญญาณนักเล่นพิณฮาร์ปแห่งตระกูลแคมป์เบลล์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LBi-LQt4q50","title":"The haunting of Inveraray: Argyll''s paranormal hotspot","thumbnail":"https://i.ytimg.com/vi/LBi-LQt4q50/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-berry-pomeroy-castle-white-lady',
      'ปราสาทเบอร์รีโปเมรอย (สตรีชุดขาวและสตรีสีฟ้าแห่งเดวอน)',
      'Berry Pomeroy Castle & The White Lady of St. Margaret''s Tower',
      'ghost',
      'เดวอน',
      'Devon',
      'ทอตเนส',
      'Totnes',
      50.4503,
      -3.6358,
      'creepy_wind',
      'ซากปราสาททิวดอร์อันโรแมนติกที่ซ่อนตัวอยู่ในป่าลึกของแคว้นเดวอน ได้รับการขนานนามว่าเป็นหนึ่งในปราสาทที่มีผีดุที่สุดในอังกฤษ วิญญาณที่น่ากลัวที่สุดคือ ''สตรีชุดขาว'' (เลดี้มาร์กาเร็ต โปเมรอย) ผู้ถูกพี่สาวขี้อิจฉาขังไว้ในคุกใต้ดินลึกใต้หอคอยเซนต์มาร์กาเร็ตจนอดอาหารตาย เธอมักปรากฏตัวเป็นร่างโปร่งแสงสีขาวโบกมือมาจากยอดหอคอยเพื่อหลอกล่อให้ผู้มาเยือนก้าวตกลงไปตาย นอกจากนี้ยังมี ''สตรีสีฟ้า'' ที่ล่อลวงผู้ชายให้หลงทางในป่า',
      'Tucked inside an isolated wooded ravine in Devon, the romantic ruins of Berry Pomeroy Castle conceal dark family betrayals. Lady Margaret Pomeroy was imprisoned in the dark subterranean dungeons beneath St. Margaret''s Tower by her jealous sister, starving to death over months. Margaret''s ghost, known as the White Lady, rises from the dungeon steps at twilight, beckoning visitors toward fatal falls. The menacing ''Blue Lady'' also haunts the courtyard, mourning a child she murdered.',
      'ปราสาทถูกทิ้งร้างมาตั้งแต่ศตวรรษที่ 17 ปัจจุบันอยู่ภายใต้การดูแลของ English Heritage และได้รับการบันทึกเรื่องเล่าเหนือธรรมชาติไว้ในหนังสือประวัติศาสตร์ท้องถิ่นมากมาย',
      'Documented by English Heritage and paranormal investigators, visitors regularly report feelings of intense cold dread, disembodied infant wails, and camera battery drains.',
      'ห้ามเดินตามร่างหญิงสาวชุดขาวที่กวักมือเรียกบนบันไดคุกใต้ดิน',
      'Never follow the beckoning White Lady down into the dungeon steps.',
      'https://i.ytimg.com/vi/OYui9e7V6pc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/OYui9e7V6pc/hqdefault.jpg","title":"ปราสาทเบอร์รีโปเมรอย (สตรีชุดขาวและสตรีสีฟ้าแห่งเดวอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=OYui9e7V6pc","title":"Paranormal investigation and History of Berry Pomeroy Castle","thumbnail":"https://i.ytimg.com/vi/OYui9e7V6pc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-woodchester-mansion-unconsecrated',
      'คฤหาสน์วูดเชสเตอร์ (คฤหาสน์โกธิกสร้างไม่เสร็จและอาถรรพ์มนต์ดำ)',
      'Woodchester Mansion: The Unfinished Gothic Enigma',
      'ghost',
      'กลอสเตอร์เชียร์',
      'Gloucestershire',
      'สเตราด์',
      'Stroud',
      51.7136,
      -2.2858,
      'creepy_wind',
      'คฤหาสน์หินสไตล์วิกตอเรียนโกธิกขนาดยักษ์ที่ซ่อนตัวอยู่ในหุบเขาลึก เริ่มสร้างในปี 1858 โดย วิลเลียม ลีห์ มหาเศรษฐีผู้เคร่งศาสนา ทว่าในปี 1873 คนงานก่อสร้างทั้งหมดกลับทิ้งเครื่องมือและวิ่งหนีเตลิดออกจากบ้านโดยไม่เคยกลับมาอีกเลย ปล่อยให้บ้านสร้างค้างไว้โดยไม่มีเพดานและพื้นชั้นบนจนถึงปัจจุบัน ในช่วงสงครามโลกครั้งที่ 2 กองทหารพันธมิตรใช้ที่นี่เป็นค่ายฝึกและเกิดอุบัติเหตุทหารจมน้ำตายในทะเลสาบ วิญญาณของทหารม้า ชายหัวขาดในห้องเก็บศพ และเงาปีศาจแพะยังคงสิงสู่อยู่ในซากอาคารร้าง',
      'Constructed deep in a secluded Cotswolds valley, Woodchester Mansion is a masterwork of Victorian Gothic architecture that was abruptly abandoned mid-construction in 1873. Stonemasons dropped their tools and fled, never to return. During WWII, Allied troops used the estate for secret tank training, with several drowned in the park lakes. The roofless stone shell is plagued by paranormal manifestations: a floating horseman, a headless phantom in the chapel, and an aggressive elemental beast in the cellar.',
      'คฤหาสน์วูดเชสเตอร์ได้รับการดูแลโดยกองทุน Woodchester Mansion Trust เป็นตัวอย่างสถาปัตยกรรมหินสกัดที่ไม่เหมือนใครในโลก เพราะสามารถมองเห็นโครงสร้างภายในของเทคนิคการก่อสร้างยุควิกตอเรียนได้อย่างทะลุปรุโปร่ง',
      'Regarded as a prime laboratory for paranormal researchers including Most Haunted, the mansion''s isolated acoustic environment amplifies disembodied footsteps and cold anomalies.',
      'ห้ามสัมผัสแท่นหินแกะสลักในโบสถ์น้อยที่ยังไม่เคยได้รับการทำพิธีเสก',
      'Never hold unholy rituals or deface the unfinished altar in the unconsecrated chapel.',
      'https://i.ytimg.com/vi/3GLQfCCM6rI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3GLQfCCM6rI/hqdefault.jpg","title":"คฤหาสน์วูดเชสเตอร์ (คฤหาสน์โกธิกสร้างไม่เสร็จและอาถรรพ์มนต์ดำ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3GLQfCCM6rI","title":"M.H - Woodchester Mansion Part 1","thumbnail":"https://i.ytimg.com/vi/3GLQfCCM6rI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-dragsholm-castle-white-lady',
      'ปราสาทดรักส์โฮล์ม (สตรีชุดขาวในซอกกำแพงแห่งเดนมาร์ก)',
      'Dragsholm Castle & The White Lady Entombed in the Wall',
      'ghost',
      'ซีแลนด์',
      'Zealand',
      'ออดส์แฮร์เรด',
      'Odsherred',
      55.7711,
      11.3917,
      'whisper',
      'ปราสาทที่เก่าแก่ที่สุดแห่งหนึ่งในเดนมาร์ก สร้างขึ้นในปี 1215 มีประวัติศาสตร์เป็นทั้งพระราชวัง ป้อมปราการ และคุกคุมขังขุนนาง ในช่วงต้นศตวรรษที่ 20 คนงานบูรณะปราสาทได้ทุบกำแพงโบราณและต้องตกตะลึงเมื่อพบโครงกระดูกของหญิงสาวสวมชุดสีขาวถูกโบกปูนฝังทั้งเป็นอยู่ภายในผนังหินหนาทึบ เธอคือ ซีลีน โบแบล เธอแอบรักกับคนงานสามัญชน บิดาของเธอผู้เป็นเจ้าของปราสาทจึงลงโทษด้วยการโบกปูนขังเธอไว้ในกำแพงจนตาย วิญญาณของเธอยังคงเดินลอยผ่านโถงทางเดินในยามค่ำคืนเพื่อตามหาคนรัก',
      'Dating back to 1215, Dragsholm Castle is one of Denmark''s oldest fortresses. During renovations in the 1930s, plumbers breaking through thick masonry made a horrifying discovery: a skeleton clad in a white dress entombed upright inside the wall cavity. She was identified as Celina Bovle, a nobleman''s daughter who fell in love with a commoner; her enraged father had her bricked up alive as punishment. Her mournful specter, the ''White Lady'', walks the castle corridors at night.',
      'ปราสาทดรักส์โฮล์มยังเป็นสถานที่คุมขังและเสียชีวิตของ เจมส์ เฮปเบิร์น เอิร์ลที่ 4 แห่งบอธเวลล์ สวามีองค์ที่สามของสมเด็จพระราชินีแมรีแห่งสก็อตแลนด์ โดยวิญญาณของเขายังคงขี่ม้าวนเวียนในลานปราสาท',
      'Now a luxury hotel and Michelin-starred restaurant, Dragsholm Castle is celebrated as one of Scandinavia''s most active and historically authenticated haunted sites.',
      'ห้ามเคาะผนังหินบริเวณจุดที่เคยขุดพบโครงกระดูกของซีลีน โบแบล',
      'Never knock or pick at the restored masonry wall where Celina''s skeleton was found.',
      'https://i.ytimg.com/vi/fIWmbSxYzes/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fIWmbSxYzes/hqdefault.jpg","title":"ปราสาทดรักส์โฮล์ม (สตรีชุดขาวในซอกกำแพงแห่งเดนมาร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fIWmbSxYzes","title":"Dragsholm Castle — The Skeleton Found Inside the Wall (True Ghost Legend)","thumbnail":"https://i.ytimg.com/vi/fIWmbSxYzes/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-akershus-fortress-malcanisen',
      'ป้อมปราการอาเคอร์ชูส (มัลคานิเซน สุนัขปีศาจแห่งออสโล)',
      'Akershus Fortress & Malcanisen the Phantom Guard Dog',
      'ghost',
      'ออสโล',
      'Oslo',
      'ออสโล',
      'Oslo',
      59.9075,
      10.7369,
      'creepy_wind',
      'ป้อมปราการยุคกลางริมอ่าวออสโล สร้างขึ้นในทศวรรษที่ 1290 เคยถูกกองทัพสวีเดนปิดล้อมหลายครั้งและใช้เป็นคุกขังนักโทษแรงงานหนักที่ถูกล่ามโซ่ตรวน ทหารยามของป้อมมักเล่าขานถึง ''มัลคานิเซน'' (Malcanisen) สุนัขสีดำตัวใหญ่ดวงตาเพลิงที่ถูกฝังทั้งเป็นไว้ใต้ประตูป้อมในสมัยโบราณเพื่อให้เป็นวิญญาณพิทักษ์ หากทหารยามคนใดเห็นมัลคานิเซนเดินเข้ามาทักทาย ทหารผู้นั้นจะเสียชีวิตด้วยอุบัติเหตุหรือโรคร้ายภายในเวลาไม่กี่เดือน นอกจากนี้ยังมีวิญญาณหญิงไร้หน้าในชุดคลุมยาวสีเข้มเดินวนเวียนตามบันไดหิน',
      'Guarding Oslo Harbor since the 1290s, Akershus Fortress was a military stronghold and notorious prison where convicts performed grueling hard labor in chains. Sentry lore speaks of ''Malcanisen'' (the Vicious Dog), a black hellhound sacrificed and buried alive beneath the main gatehouse to serve as an eternal spectral watchdog. Any soldier who encounters the phantom dog is doomed to die a painful death within months. The faceless ''Mantelgeisten'' woman also stalks the royal chambers.',
      'ในสงครามโลกครั้งที่ 2 กองทัพนาซีเยอรมันได้ยึดป้อมอาเคอร์ชูสเป็นศูนย์บัญชาการเกสตาโปและใช้เป็นลานประหารชีวิตสมาชิกขบวนการต่อต้านชาวนอร์เวย์',
      'A national historical monument and military museum, Akershus Fortress remains an integral part of Norwegian folklore, featured on Nordic ghost walks.',
      'หากได้ยินเสียงสุนัขคำรามในเงามืดของประตูป้อม ห้ามหันกลับไปมองเด็ดขาด',
      'If you hear low growls near the fortress gatehouse at night, do not look behind you.',
      'https://i.ytimg.com/vi/M8vW2nGi264/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/M8vW2nGi264/hqdefault.jpg","title":"ป้อมปราการอาเคอร์ชูส (มัลคานิเซน สุนัขปีศาจแห่งออสโล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=M8vW2nGi264","title":"Akershus Fortress – Oslo, Norway","thumbnail":"https://i.ytimg.com/vi/M8vW2nGi264/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-aizuwakamatsu-byakkotai',
      'ปราสาทสึรุกะและกองทัพพยัคฆ์ขาว (วิญญาณเบียกโกะไตแห่งไอสึ)',
      'Tsuruga Castle & The Phantom Byakkotai Warriors (Aizu)',
      'ghost',
      'ฟุกุชิมะ',
      'Fukushima',
      'ไอสึวากามัตสึ',
      'Aizuwakamatsu',
      37.4878,
      139.9297,
      'creepy_wind',
      'สมรภูมิรบสุดท้ายของระบอบซามูไรในสงครามโบชินปี 1868 กองกำลัง ''เบียกโกะไต'' (กองพันพยัคฆ์ขาว) ซึ่งเป็นซามูไรวัยรุ่นอายุเพียง 16-17 ปี จำนวน 20 นาย ได้ถอยร่นขึ้นไปบนเนินเขาอีโมริ เมื่อมองลงมาเห็นควันไฟพวยพุ่งเหนือปราสาทสึรุกะ พวกเขาเข้าใจผิดว่าปราสาทถูกตีแตกและเจ้านายเสียชีวิตแล้ว เพื่อรักษาเกียรติยศแห่งซามูไร ซามูไรหนุ่มทั้ง 19 นายจึงตัดสินใจทำพิธี ''เซ็ปปุกุ'' คว้านท้องตัวเองเสียชีวิตพร้อมกันบนยอดเขา วิญญาณของเหล่านักรบหนุ่มในชุดกิโมโนสีขาวเปื้อนเลือดยังคงปรากฏกายเฝ้าพิทักษ์ปราสาท',
      'During the 1868 Boshin War, the Aizu samurai made their heroic last stand at Tsuruga Castle against Imperial forces. Twenty teenage samurai of the Byakkotai (White Tiger Force) retreated to Mount Iimori; seeing smoke billowing from the town, they mistakenly believed the castle had fallen. To preserve their honor, 19 of the young warriors committed ritual seppuku on the hillside. Visitors report hearing samurai war cries on misty evenings and seeing spectral young warriors standing along the castle moats.',
      'สุสานของกองพันพยัคฆ์ขาวบนเนินเขาอีโมริยังคงได้รับการดูแลอย่างสมเกียรติ โดยมีอนุสาวรีย์หินและพิธีรำลึกด้วยการร่ายรำดาบซามูไรทุกฤดูใบไม้ผลิและฤดูใบไม้ร่วง',
      'The tragic sacrifice of the Byakkotai became an enduring legend of Japanese loyalty and Bushido ethics, celebrated across historical Japanese literature and cinema.',
      'ห้ามแสดงกิริยาล้อเลียนหรือส่งเสียงหัวเราะหน้าหลุมศพของซามูไรพยัคฆ์ขาวบนเขาอีโมริ',
      'Maintain deep silence and respect before the graves of the young Byakkotai warriors.',
      'https://i.ytimg.com/vi/ecU08OMp_tI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ecU08OMp_tI/hqdefault.jpg","title":"ปราสาทสึรุกะและกองทัพพยัคฆ์ขาว (วิญญาณเบียกโกะไตแห่งไอสึ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ecU08OMp_tI","title":"Byakkotai (白虎隊) [White Tiger Force/Cuerpo del Tigre Blanco]","thumbnail":"https://i.ytimg.com/vi/ecU08OMp_tI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-inunaki-howling-dog-tunnel',
      'อุโมงค์อินุนากิ (อุโมงค์สุนัขเห่าหอนและหมู่บ้านนอกกฎหมายญี่ปุ่น)',
      'The Old Inunaki Tunnel & The Howling Village (Fukuoka)',
      'ghost',
      'ฟุกุโอกะ',
      'Fukuoka',
      'มิยาวากะ',
      'Miyawaka',
      33.6881,
      130.5564,
      'creepy_wind',
      'อุโมงค์แคบเก่าแก่ที่สร้างขึ้นในปี 1949 ตัดผ่านเทือกเขาอินุนากิ มีชื่อเสียงว่าเป็น ''สถานที่ต้องห้ามที่มีผีดุที่สุดในญี่ปุ่น'' ในปี 1988 ชายหนุ่มคนหนึ่งถูกกลุ่มวัยรุ่นทรมานและเผาทั้งเป็นจนเสียชีวิตภายในอุโมงค์ นอกจากนี้ยังมีตำนานเมืองเล่าขานถึง ''หมู่บ้านอินุนากิ'' ที่ซ่อนตัวอยู่หลังอุโมงค์ ซึ่งมีป้ายปักเตือนไว้ว่า ''กฎหมายรัฐธรรมนูญญี่ปุ่นไม่ครอบคลุมพื้นที่นี้'' ผู้ใดที่บุกรุกเข้าไปจะไม่เคยได้กลับออกมา ปัจจุบันปากอุโมงค์ถูกทางการนำบล็อกคอนกรีตขนาดยักษ์มาวางปิดตายเพื่อความปลอดภัย',
      'The Old Inunaki Tunnel is Japan''s most notorious supernatural dead zone. In 1988, a factory worker was abducted, tortured, and burned alive with gasoline inside the abandoned tunnel by delinquent youths. The tunnel spawned the dark urban legend of Inunaki Village—an isolated, inbred mountain settlement living outside Japanese law, where intruders are hunted down with axes. Sealed with massive concrete slabs, trespassers report handprints appearing on car windows, disembodied screams, and malfunctioning electronics.',
      'ตำนานอุโมงค์อินุนากิสร้างแรงบันดาลใจให้กับภาพยนตร์สยองขวัญชื่อดังของ ทาคาชิ ชิมิสุ เรื่อง ''Howling Village'' (2020) และมังงะสยองขวัญมากมาย',
      'Investigated by Japanese paranormal broadcasters, the concrete barrier bears police warning signs. The site remains strictly monitored by Fukuoka prefecture authorities.',
      'ห้ามปีนข้ามบล็อกคอนกรีตเข้าไปในอุโมงค์เก่าอินุนากิโดยเด็ดขาด',
      'Never attempt to scale the concrete barrier blocking the Old Inunaki Tunnel entrance.',
      'https://i.ytimg.com/vi/1wJQPzb8oGk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/1wJQPzb8oGk/hqdefault.jpg","title":"อุโมงค์อินุนากิ (อุโมงค์สุนัขเห่าหอนและหมู่บ้านนอกกฎหมายญี่ปุ่น)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=1wJQPzb8oGk","title":"I went to the Inunaki Tunnel at the Lawless Howling Village in Japan....","thumbnail":"https://i.ytimg.com/vi/1wJQPzb8oGk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-oiwa-yotsuya-kaidan-tokyo',
      'วิญญาณแค้นโออิวะ (ตำนานผีสาวหน้าเบี้ยวแห่งโยตสึยะ ไคดัน)',
      'The Vengeful Spirit of Oiwa (Yotsuya Kaidan of Tokyo)',
      'ghost',
      'โตเกียว',
      'Tokyo',
      'ชินจูกุ',
      'Shinjuku',
      35.6883,
      139.7214,
      'whisper',
      'เรื่องเล่าผีญี่ปุ่นที่โด่งดังและน่ากลัวที่สุดตลอดกาล โออิวะ หญิงสาวผู้ซื่อสัตย์ถูกสามีของเธอ ซึ่งเป็นซามูไรไร้นาย วางยาพิษจนใบหน้าเสียโฉม ดวงตาข้างขวาปูดบวมปิดสนิท ผมร่วงเป็นหย่อม เพื่อที่เขาจะได้ไปแต่งงานใหม่กับหญิงสาวผู้ร่ำรวย โออิวะเสียชีวิตด้วยความตรอมใจและกลายเป็น ''อนเรียว'' (วิญญาณพยาบาท) หลอกหลอนจนสามีคลุ้มคลั่งสังหารภรรยาใหม่และครอบครัวจนตายหมดสิ้น จนถึงปัจจุบัน นักแสดงคาบูกิที่เล่นบทนี้ทุกคนต้องไปกราบไหว้ขอขมาที่ศาลเจ้าโออิวะอินาริมิฉะนั้นจะตาบอดหรือประสบอุบัติเหตุ',
      'Tamiya Oiwa is Japan''s ultimate vengeful ghost (onryō). In the Edo period, her dishonorable ronin husband Iemon poisoned her with a face-disfiguring toxin so he could marry a wealthy neighbor''s granddaughter. Horrified by her swollen, drooping eye and falling hair, Oiwa died in torment and returned as a wrathful specter, driving Iemon insane until he butchered his new bride and in-laws. Even today, Kabuki and film actors staging Yotsuya Kaidan must pray at Oiwa''s shrine in Tokyo to avoid horrific facial injuries.',
      'บทละครคาบูกิ ''โทไคโด โยตสึยะ ไคดัน'' ประพันธ์โดย ซึรุยะ นัมโบกุ ที่ 4 ในปี 1825 ถือเป็นรากฐานสำคัญของภาพยนตร์ผีญี่ปุ่นสมัยใหม่ เช่น The Ring (ซาดาโกะ) และ Ju-on',
      'The Oiwa Inari Tamiya Shrine in Shinjuku is actively maintained. Production companies universally hold purification ceremonies here before shooting horror films featuring deformed female ghosts.',
      'ห้ามแสดงหรือถ่ายทำละครโยตสึยะ ไคดัน โดยไม่ประกอบพิธีบวงสรวงที่ศาลเจ้าโออิวะ',
      'Never produce theatrical adaptations of Yotsuya Kaidan without offering prayers at Oiwa''s shrine.',
      'https://i.ytimg.com/vi/_JJk8lUYgdM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_JJk8lUYgdM/hqdefault.jpg","title":"วิญญาณแค้นโออิวะ (ตำนานผีสาวหน้าเบี้ยวแห่งโยตสึยะ ไคดัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_JJk8lUYgdM","title":"The Curse of Oiwa: Japan''s Most Terrifying Ghost Story (Yotsuya Kaidan Documentary)","thumbnail":"https://i.ytimg.com/vi/_JJk8lUYgdM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-okiku-nine-plates-himeji',
      'โอคิคุแห่งบ่อนับจาน (วิญญาณสาวใช้ปราสาทฮิเมจิ)',
      'The Ghost Well of Okiku (Bancho Sarayashiki of Himeji)',
      'ghost',
      'เฮียวโงะ',
      'Hyogo',
      'ฮิเมจิ',
      'Himeji',
      34.8394,
      134.6939,
      'water_spirit',
      'บ่อน้ำโบราณภายในปราสาทฮิเมจิ (ปราสาทนกกระสาขาว) ตำนานเล่าถึง โอคิคุ สาวใช้ผู้ซื่อสัตย์ที่ดูแลชุดจานดัตช์โบราณล้ำค่าสิบใบ ซามูไรผู้ชั่วร้ายต้องการบีบบังคับให้เธอยอมเป็นภรรยาน้อย จึงแอบขโมยจานใบที่สิบไปซ่อน เมื่อโอคิคุนับจานได้เพียงเก้าใบ เธอหวาดกลัวและร้องไห้นับจานซ้ำแล้วซ้ำเล่า ซามูไรจึงลงโทษเธอด้วยการทรมานและโยนร่างของเธอลงไปในบ่อน้ำลึกจนเสียชีวิต ทุกค่ำคืน จะมีเสียงอันโศกเศร้าลอยขึ้นมาจากก้นบ่อนับจานช้าๆ ว่า ''หนึ่งใบ... สองใบ... เก้าใบ...'' แล้วตามด้วยเสียงกรีดร้องโหยหวน',
      'Within the inner ward of Himeji Castle sits Okiku''s Well. Okiku was a loyal servant girl entrusted with ten valuable imported Dutch heirloom plates. When she refused the romantic advances of an evil samurai retainer, he stole one plate and framed her for the loss. Desperate, Okiku counted the plates nine times before being suspended over the stone well, beaten, and dropped to her death. Every midnight, her weeping phantom emerges from the depths, counting plates: ''One... two... nine...'' before sobbing uncontrollably.',
      'ตำนานบ้านนับจาน (Bancho Sarayashiki) เป็นหนึ่งในนิทานพื้นบ้านที่คลาสสิกที่สุดของญี่ปุ่น บ่อน้ำโอคิคุ (Okiku-ido) ยังคงตั้งตระหง่านอยู่ภายในปราสาทฮิเมจิ มรดกโลกยูเนสโก',
      'Preserved inside Japan''s most famous surviving feudal white castle, Okiku''s Well is viewed by millions of international visitors annually as an iconic site of Japanese spectral literature.',
      'ห้ามโยนเหรียญหรือสิ่งของลงไปในบ่อน้ำโอคิคุในปราสาทฮิเมจิ',
      'Never drop coins, garbage, or foreign objects into Okiku''s stone well.',
      'https://i.ytimg.com/vi/k3gJ0DqvzkQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/k3gJ0DqvzkQ/hqdefault.jpg","title":"โอคิคุแห่งบ่อนับจาน (วิญญาณสาวใช้ปราสาทฮิเมจิ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=k3gJ0DqvzkQ","title":"The True Horror Story That Inspired ''The Ring'': The Legend of Okiku’s Well","thumbnail":"https://i.ytimg.com/vi/k3gJ0DqvzkQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-old-changi-hospital-singapore',
      'โรงพยาบาลชางงีเก่า (โรงพยาบาลร้างและคุกเชลยศึกสิงคโปร์)',
      'Old Changi Hospital: The Dark Wartime Relic of Singapore',
      'ghost',
      'ชางงี',
      'Changi',
      'ชางงี',
      'Changi',
      1.3908,
      103.9781,
      'whisper',
      'โรงพยาบาลทหารของกองทัพอังกฤษที่สร้างขึ้นในปี 1935 บนเนินเขาชางงี ในช่วงสงครามโลกครั้งที่ 2 กองทัพจักรวรรดิญี่ปุ่นได้ยึดอาคารแห่งนี้เป็นค่ายกักกันเชลยศึกฝ่ายสัมพันธมิตรและเป็นศูนย์ทรมานของหน่วยตำรวจลับเคมเปไต มีการตัดแขนขา ดึงเล็บ และทรมานเชลยศึกจนเสียชีวิตนับพันคน หลังสงครามโรงพยาบาลกลับมาเปิดทำการจนกระทั่งถูกทิ้งร้างในปี 1997 ผู้บุกรุกมักได้ยินเสียงกรีดร้องโหยหวนจากห้องดับจิต เสียงโซ่ตรวนลากบนพื้น และเห็นวิญญาณทหารไร้หัวเดินทะลุกำแพง',
      'Constructed in 1935 as a British military hospital, Old Changi Hospital fell to Imperial Japanese forces in 1942, who converted it into a brutal POW internment camp and Kempeitai military police torture facility. Thousands of British, Australian, and local prisoners were tortured and executed within its subterranean chambers. Abandoned in 1997, it is recognized as Southeast Asia''s most haunted hospital, plagued by screaming apparitions, bloodstained walls, and phantom gurneys rolling down corridors.',
      'เรื่องราวความลี้ลับของโรงพยาบาลชางงีเก่าถูกนำไปสร้างเป็นภาพยนตร์แนว Mockumentary ชื่อดัง ''Haunted Changi'' ในปี 2010 ปัจจุบันพื้นที่ถูกล้อมรั้วรักษาความปลอดภัยอย่างเข้มงวด',
      'Subject of the 2010 found-footage horror film ''Haunted Changi'', the complex is protected under strict security patrols by the Singapore Land Authority.',
      'ห้ามตัดรั้วหรือบุกรุกเข้าไปในอาคารโรงพยาบาลชางงีเก่าโดยไม่ได้รับอนุญาต',
      'Never trespass into the condemned wards or basement mortuary of Old Changi Hospital.',
      'https://i.ytimg.com/vi/nsLRvFjc-EA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/nsLRvFjc-EA/hqdefault.jpg","title":"โรงพยาบาลชางงีเก่า (โรงพยาบาลร้างและคุกเชลยศึกสิงคโปร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=nsLRvFjc-EA","title":"What I Found At Old Changi Hospital During Hungry Ghost Festival | Hidden Hustles Ep 49","thumbnail":"https://i.ytimg.com/vi/nsLRvFjc-EA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-clark-air-base-hospital-pampanga',
      'โรงพยาบาลฐานทัพอากาศคลาร์ก (วิญญาณทหารบาดเจ็บแห่งสงครามเวียดนาม)',
      'Clark Air Base Hospital: The Ghost Wards of Pampanga',
      'ghost',
      'ปัมปังกา',
      'Pampanga',
      'อันเฮเลสซิตี',
      'Angeles City',
      15.1794,
      120.5311,
      'whisper',
      'อดีตโรงพยาบาลทหารของกองทัพอากาศสหรัฐฯ ในประเทศฟิลิปปินส์ ซึ่งทำหน้าที่เป็นศูนย์ส่งกลับสายการแพทย์หลักในช่วงสงครามเวียดนาม ทหารอเมริกันที่ได้รับบาดเจ็บสาหัสและเสียชีวิตนับพันนายถูกส่งตัวมารักษาที่นี่ โรงพยาบาลถูกทิ้งร้างในปี 1991 หลังการปะทุครั้งใหญ่ของภูเขาไฟปินาตูโบ ผู้มาเยือนมักพบเห็นวิญญาณของแพทย์และพยาบาลในเครื่องแบบผ่าตัดเดินไปมาในทางเดินมืดมิด เสียงร้องครวญครางขอความช่วยเหลือจากทหารที่เสียชีวิต และมีขวดน้ำเกลือลอยเคว้งกลางอากาศ',
      'Serving as the premier evacuation hospital for wounded and dying US military personnel during the Vietnam War, Clark Air Base Hospital witnessed immense human suffering and death. The massive hospital was permanently abandoned following the catastrophic 1991 eruption of Mount Pinatubo, which buried the region in volcanic ash. Ghost hunters encounter extreme poltergeist activity: floating IV bottles, disembodied screams of dying soldiers, and spectral nurses in bloodied scrubs pacing the ICU.',
      'รายการสารคดี I Wouldn''t Go In There ของช่อง National Geographic ยกให้โรงพยาบาลฐานทัพอากาศคลาร์กเป็นหนึ่งในสถานที่ที่มีผีดุที่สุดในทวีปเอเชีย',
      'Highlighted by National Geographic''s ''I Wouldn''t Go In There'', the ash-coated ruins in Clark Freeport Zone remain a premier research site for international paranormal groups.',
      'ห้ามโยนหินหรือทำลายอุปกรณ์ทางการแพทย์เก่าในห้องผ่าตัดร้าง',
      'Never throw stones or tamper with decaying medical gurneys in the operating rooms.',
      'https://i.ytimg.com/vi/l1iZBM83K0U/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/l1iZBM83K0U/hqdefault.jpg","title":"โรงพยาบาลฐานทัพอากาศคลาร์ก (วิญญาณทหารบาดเจ็บแห่งสงครามเวียดนาม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=l1iZBM83K0U","title":"Rated K: Haunted Clark Hospital","thumbnail":"https://i.ytimg.com/vi/l1iZBM83K0U/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-diplomat-hotel-baguio',
      'โรงแรมดิพโพลแมท (ซากโบสถ์โดมินิกันและวิญญาณไร้หัวแห่งบาเกียว)',
      'The Diplomat Hotel & The Headless Nuns of Dominican Hill',
      'ghost',
      'เบงเกต',
      'Benguet',
      'บาเกียว',
      'Baguio',
      16.4039,
      120.5794,
      'creepy_wind',
      'อาคารหินทรงยุโรปบนยอดเขาโดมินิกันฮิลล์ เดิมสร้างขึ้นในปี 1913 เพื่อเป็นสถานพักฟื้นและเซมินารีของนักบวชคณะโดมินิกัน ในช่วงสงครามโลกครั้งที่ 2 กองทัพญี่ปุ่นบุกยึดสถานที่แห่งนี้เป็นค่ายกักกันและได้สังหารหมู่พระสงฆ์ แม่ชี และผู้ลี้ภัยด้วยการตัดศีรษะอย่างเหี้ยมโหด ต่อมาถูกเปลี่ยนเป็นโรงแรมหรูแต่ต้องปิดตัวลงหลังการเสียชีวิตของผู้จัดการ ผู้มาเยือนมักได้ยินเสียงสวดภาวนาภาษาละตินที่น่าขนลุก เสียงกรีดร้องในยามดึก และเห็นวิญญาณแม่ชีไร้หัวเดินถือจานใส่ศีรษะของตนเอง',
      'Built in 1913 as a seminary and vacation house for the Dominican Order, this hilltop stone retreat became a sanctuary for refugees fleeing Imperial Japanese forces in 1945. Invading troops stormed the complex, bayoneting priests and decapitating nuns and infants in horrific massacres. Later renovated into the Diplomat Hotel, it shuttered in the 1980s. Today, visitors to Dominican Hill encounter headless apparitions of priests carrying their severed heads and hear agonized wails echoing through arched corridors.',
      'ปัจจุบันได้รับการบูรณะและขึ้นทะเบียนเป็นมรดกทางประวัติศาสตร์ของเมืองบาเกียว ในชื่อ ''Dominican Heritage Hill and Nature Park'' และเป็นจุดถ่ายภาพยอดนิยม',
      'Declared a National Historical Site, the ruined structure on Dominican Hill stands as a sobering monument to Baguio''s wartime suffering and enduring ghost lore.',
      'ห้ามจุดเทียนดำหรือประกอบพิธีเรียกวิญญาณในโถงอาคารด้านบน',
      'Never light black candles or conduct séances on the second-floor terrace.',
      'https://i.ytimg.com/vi/SR39Tc1Gd60/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SR39Tc1Gd60/hqdefault.jpg","title":"โรงแรมดิพโพลแมท (ซากโบสถ์โดมินิกันและวิญญาณไร้หัวแห่งบาเกียว)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SR39Tc1Gd60","title":"Kapuso Mo, Jessica Soho: Rember Gelera’s Diplomat Hotel | Gabi ng Lagim IV","thumbnail":"https://i.ytimg.com/vi/SR39Tc1Gd60/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-kellies-castle-perak',
      'ปราสาทเคลลี่ (คฤหาสน์หรูสร้างไม่เสร็จแห่งรัฐเปรัก มาเลเซีย)',
      'Kellie''s Castle & The Phantom Planter of Perak',
      'ghost',
      'เปรัก',
      'Perak',
      'บาตู กาจาห์',
      'Batu Gajah',
      4.4753,
      101.0872,
      'whisper',
      'ปราสาทสไตล์มัวริชผสมโกธิกที่สร้างโดย วิลเลียม เคลลี สมิธ เจ้าของไร่ยางพาราชาวสก็อต เพื่อมอบเป็นของขวัญแด่ภรรยาและเฉลิมฉลองการเกิดของบุตรชาย ในปี 1926 เคลลีเดินทางไปอังกฤษเพื่อซื้อลิฟต์ตัวแรกของมลายู ทว่าเขาป่วยเป็นโรคปอดบวมเสียชีวิตกะทันหันที่โปรตุเกส ทำให้ปราสาทถูกทิ้งร้างทันที คนงานเชื่อว่ามีอุโมงค์ลับใต้ดิน 4 สายเชื่อมต่อกับวัดฮินดู วิญญาณของเคลลียังคงสวมชุดสูทขาวเดินตรวจตราตามระเบียงทางเดินในยามค่ำคืน และมีร่างเงาของเด็กหญิงในชุดโบราณวิ่งเล่นในห้องนอนชั้นสอง',
      'Rising above a rubber estate in Batu Gajah, Kellie''s Castle is an extravagant Moorish-Revival mansion begun in 1915 by Scottish planter William Kellie-Smith as a monument of love for his wife. Construction ceased abruptly in 1926 when Kellie contracted fatal pneumonia in Lisbon while traveling to purchase a private elevator. Abandoned amidst secret underground tunnels, visitors regularly spot William''s white-suited apparition pacing the rooftop terrace, while spectral children play in the unfinished bedrooms.',
      'ปราสาทเคลลี่เป็นหนึ่งในสถานที่ท่องเที่ยวทางประวัติศาสตร์ที่โดดเด่นที่สุดของรัฐเปรัก โครงสร้างอิฐและปูนผสมไข่เป็ดโบราณยังคงอยู่ในสภาพสมบูรณ์และเปิดให้นักท่องเที่ยวเข้าชม',
      'A prime tourist landmark of Perak, the estate is famous for its intricate hidden wine cellars, secret escape tunnels, and romantic yet tragic colonial history.',
      'ห้ามก้าวเข้าไปในโพรงอุโมงค์ลับใต้ดินที่ไม่ได้เปิดไฟส่องสว่าง',
      'Never enter unlit subterranean passageways beneath the castle foundations.',
      'https://i.ytimg.com/vi/KI6Sp8njTSg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KI6Sp8njTSg/hqdefault.jpg","title":"ปราสาทเคลลี่ (คฤหาสน์หรูสร้างไม่เสร็จแห่งรัฐเปรัก มาเลเซีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KI6Sp8njTSg","title":"Kellie''s Castle (Documentary)","thumbnail":"https://i.ytimg.com/vi/KI6Sp8njTSg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-lawang-sewu-thousand-doors',
      'ลาวาง เซวู (อาคารพันประตูและคุกใต้ดินแห่งเซมารัง อินโดนีเซีย)',
      'Lawang Sewu: The Building of a Thousand Doors (Semarang)',
      'ghost',
      'ชวากลาง',
      'Central Java',
      'เซมารัง',
      'Semarang',
      -6.9839,
      110.4103,
      'water_spirit',
      'อาคารสำนักงานใหญ่การรถไฟอินเดียตะวันออกของเนเธอร์แลนด์ สร้างขึ้นในปี 1904 มีประตูและหน้าต่างโค้งนับพันบาน ในช่วงสงครามโลกครั้งที่ 2 กองทัพญี่ปุ่นได้ดัดแปลงห้องใต้ดินที่ระบายน้ำให้กลายเป็น ''คุกน้ำ'' ซึ่งนักโทษชาวดัตช์และชาวอินโดนีเซียจะถูกบังคับให้ยืนแช่น้ำครำลึกถึงคอจนตายอย่างทรมาน รวมถึงเป็นลานประหารชีวิตด้วยการตัดศีรษะ วิญญาณที่โด่งดังที่สุดคือ ''กุนตีลานัก'' (ผีสาวผมยาวชุดขาว) และวิญญาณสตรีชาวดัตช์ที่กระโดดตึกฆ่าตัวตาย ผู้มาเยือนมักเห็นรอยเลือดซึมออกมาจากพื้นห้องใต้ดิน',
      'Lawang Sewu, meaning ''Thousand Doors'' in Javanese, is a colonial landmark built in 1904 by the Dutch railway company. During World War II, Japanese occupying forces turned the subterranean basements into cramped water dungeons where hundreds of Dutch and Indonesian captives were submerged up to their necks in filth until they died or were beheaded. Considered Indonesia''s most terrifying haunted site, visitors report screaming headless Dutch prisoners and sightings of the predatory Kuntilanak specter.',
      'ลาวาง เซวู ได้รับการจัดอันดับจาก National Geographic ให้เป็นหนึ่งในสถานที่ที่มีผีดุที่สุดในเอเชีย ปัจจุบันได้รับการบูรณะเป็นพิพิธภัณฑ์ประวัติศาสตร์และการรถไฟของอินโดนีเซีย',
      'Carefully restored by PT Kereta Api Indonesia, Lawang Sewu attracts architectural enthusiasts and paranormal investigators from across Southeast Asia.',
      'ห้ามลงไปในชั้นใต้ดินที่เปียกชื้นคนเดียวในยามค่ำคืน',
      'Never explore the flooded subterranean water dungeon rooms alone after twilight.',
      'https://i.ytimg.com/vi/IaJ2-7kcFsA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IaJ2-7kcFsA/hqdefault.jpg","title":"ลาวาง เซวู (อาคารพันประตูและคุกใต้ดินแห่งเซมารัง อินโดนีเซีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IaJ2-7kcFsA","title":"LAWANG SEWU,  the Mystery of Thousand Doors","thumbnail":"https://i.ytimg.com/vi/IaJ2-7kcFsA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-tat-tak-school-hong-kong',
      'โรงเรียนตัตตัก (โรงเรียนร้างผีสาวชุดแดงแห่งฮ่องกง)',
      'Tat Tak School: The Red Maiden Hauntings of Yuen Long',
      'ghost',
      'ฮ่องกง',
      'Hong Kong',
      'หยวนหลง',
      'Yuen Long',
      22.4419,
      114.0086,
      'creepy_wind',
      'โรงเรียนประถมร้างที่ซ่อนตัวอยู่บนเนินเขาหมู่บ้านผิงซาน ล้อมรอบด้วยหลุมศพโบราณของตระกูลถัง ในปี 1898 พื้นที่แห่งนี้เคยเป็นสมรภูมิสังหารหมู่ชาวบ้านที่ต่อต้านการปกครองของอังกฤษ ตำนานเล่าว่าครูใหญ่หญิงของโรงเรียนได้กระทำอัตวินิบาตกรรมด้วยการผูกคอตายในห้องน้ำหญิงชั้นสองขณะสวมชุดกี่เพ้าสีแดงล้วน เพื่อกลายเป็น ''ผีชุดแดง'' พยาบาท หลังจากโรงเรียนปิดตัวลงในปี 1998 มีกลุ่มนักเรียนวัยรุ่นเข้าไปล่าท้าผีและเกิดอาการคุ้มคลั่ง พยายามบีบคอตัวเองจนต้องส่งโรงพยาบาลฉุกเฉิน',
      'Surrounded by ancient clan graves in Ping Shan, Tat Tak School closed its doors in 1998 and is notorious as Hong Kong''s most haunted school. Built near a mass burial site of villagers massacred by British forces during the 1898 Six-Day War, local lore recounts a school mistress who hanged herself in the girls'' restroom wearing a crimson cheongsam dress, transforming into a vengeful spirit. In 2011, a group of exploring teenagers experienced violent group hysteria, screaming and clawing at their own throats.',
      'นิตยสาร National Geographic ได้จัดอันดับให้โรงเรียนตัตตักเป็นหนึ่งในสถานที่ที่น่ากลัวที่สุดในเอเชีย ปัจจุบันพื้นที่ถูกปิดกั้นด้วยรั้วลวดหนามและมีเจ้าหน้าที่รักษาความปลอดภัยเฝ้า 24 ชั่วโมง',
      'Enclosed by barbed-wire fences and monitored by security guards, Tat Tak School remains the centerpiece of modern Hong Kong urban supernatural investigations.',
      'ห้ามสวมชุดสีแดงล้วนเข้าไปใกล้บริเวณห้องน้ำหญิงของโรงเรียนตัตตัก',
      'Never wear solid crimson red or attempt to enter the second-floor female restroom.',
      'https://i.ytimg.com/vi/EObojLIuxn0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/EObojLIuxn0/hqdefault.jpg","title":"โรงเรียนตัตตัก (โรงเรียนร้างผีสาวชุดแดงแห่งฮ่องกง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EObojLIuxn0","title":"They said this was the most haunted place in Hong Kong, so I visited it at midnight.","thumbnail":"https://i.ytimg.com/vi/EObojLIuxn0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-wat-phai-ngoen-ghost-fetuses',
      'วัดไผ่เงินโชตนาราม (อาถรรพ์วิญญาณทารก 2,002 ศพแห่งบางคอแหลม)',
      'Wat Phai Ngoen & The 2,002 Spectral Fetuses of Bangkok',
      'ghost',
      'กรุงเทพมหานคร',
      'Bangkok',
      'บางคอแหลม',
      'Bang Kho Laem',
      13.7028,
      100.5108,
      'whisper',
      'ในเดือนพฤศจิกายน พ.ศ. 2553 เกิดข่าวสะเทือนขวัญระดับชาติ เมื่อชาวบ้านได้กลิ่นเหม็นเน่ารุนแรงโชยออกมาจากโกดังเก็บศพหมายเลข 17 ของวัดไผ่เงิน เจ้าหน้าที่ตำรวจเข้าตรวจสอบและต้องตกตะลึงเมื่อพบซากทารกที่มาจากการทำแท้งเถื่อนถูกนำมาลักลอบซุกซ่อนไว้ในช่องเก็บศพถึง 2,002 ศพ หลังจากนั้น มีพยานพบเห็นเด็กตัวเล็กๆ นับสิบนับร้อยวิ่งเล่นอยู่รอบโบสถ์ในยามค่ำคืน เสียงเด็กร้องไห้กระจองอแง และเสียงเคาะประตูโกดังเก็บศพ จนทางวัดต้องจัดพิธีสวดพระอภิธรรมและฌาปนกิจครั้งใหญ่เพื่อส่งวิญญาณ',
      'In November 2010, residents near Wat Phai Ngoen in Bangkok reported an unbearable stench emanating from the temple mortuary vaults. Police raided the site and uncovered a horrific sight: 2,002 aborted fetuses from illegal clinics smuggled and stashed inside plastic bags within vault 17. Following the discovery, neighbors and monks reported witnessing crowds of spectral infants running around the temple courtyard at night, echoing infant cries, and phantom tugs on clothes until grand Buddhist funeral rites were performed.',
      'โศกนาฏกรรมวัดไผ่เงินนำไปสู่การกวาดล้างคลินิกทำแท้งเถื่อนทั่วประเทศไทย และเป็นแรงบันดาลใจในการสร้างภาพยนตร์ไทยเรื่อง ''ศพเด็ก 2002'' นำแสดงโดย สมชาย เข็มกลัด',
      'The national tragedy prompted nationwide legislative reviews on reproductive healthcare in Thailand and inspired the 2011 Thai horror film ''The Unborn Child'' (2002 Fetuses).',
      'ห้ามนำของเล่นชำรุดมาทิ้งไว้ หรือพูดจาลบหลู่ดวงวิญญาณทารกในวัด',
      'Never mock or leave broken toys around the historic temple mortuary vaults.',
      'https://i.ytimg.com/vi/_ZEoeaCTu_Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_ZEoeaCTu_Y/hqdefault.jpg","title":"วัดไผ่เงินโชตนาราม (อาถรรพ์วิญญาณทารก 2,002 ศพแห่งบางคอแหลม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_ZEoeaCTu_Y","title":"ย้อนรอย \"สุสานทารก 2002 ศพ\" วัดไผ่เงิน | เปิดแฟ้มคดีดัง | 27-10-64 | ไทยรัฐนิวส์โชว์","thumbnail":"https://i.ytimg.com/vi/_ZEoeaCTu_Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-bangkok-airplane-graveyard',
      'สุสานเครื่องบินรามคำแหง (ซากเครื่องบินมรณะและวิญญาณวัน-ทู-โก)',
      'Bangkok Airplane Graveyard (The Ramkhamhaeng Wreckage)',
      'ghost',
      'กรุงเทพมหานคร',
      'Bangkok',
      'บางกะปิ',
      'Bang Kapi',
      13.7667,
      100.6486,
      'creepy_wind',
      'ลานดินกว้างริมถนนรามคำแหงที่เป็นที่ตั้งของซากเครื่องบินโดยสารโบอิ้ง 747 และเอ็มดี-82 ที่ถูกชำแหละชิ้นส่วน หนึ่งในซากเครื่องบินเหล่านี้คือเครื่องบินของสายการบินวัน-ทู-โก เที่ยวบิน 269 ที่ประสบอุบัติเหตุไถลออกนอกรันเวย์และเกิดเพลิงไหม้ที่ภูเก็ตในปี 2550 คร่าชีวิตผู้โดยสาร 90 คน ครอบครัวคนเก็บของเก่าที่อาศัยอยู่ในซากเครื่องบินเล่าว่า ในยามค่ำคืนมักได้ยินเสียงเคาะกระจกหน้าต่างห้องโดยสาร เสียงเปิดปิดช่องเก็บสัมภาระ และเสียงกรีดร้องขอความช่วยเหลือจากวิญญาณผู้โดยสารที่ติดอยู่ในซากเหล็ก',
      'Located in eastern Bangkok lies the Airplane Graveyard, a derelict field holding dismantled fuselages of a Boeing 747 and two McDonnell Douglas MD-82 aircraft. One wreckage was reportedly from One-Two-GO Airlines Flight 269, which crashed and burned in Phuket in 2007, claiming 90 lives. Scavenger families living inside the hulls report phantom footsteps in the aisles, overhead bins slamming shut spontaneously, and spectral passengers trapped in cabin seats during torrential thunderstorms.',
      'สุสานเครื่องบินแห่งนี้เคยเป็นจุดถ่ายภาพสไตล์ Urban Exploration (Urbex) ที่มีชื่อเสียงระดับโลกในหมู่นักท่องเที่ยวต่างชาติ ก่อนที่จะถูกทยอยรื้อถอนและปิดกั้นพื้นที่เพื่อความปลอดภัย',
      'A world-famous urban exploration destination featured in international travel vlogs, the site preserves the somber remnants of Southeast Asian aviation history.',
      'ห้ามเข้าไปรบกวนครอบครัวผู้พักอาศัย หรือขโมยชิ้นส่วนโลหะของเครื่องบิน',
      'Never trespass inside private aircraft cabin dwellings or take scrap metal relics.',
      'https://i.ytimg.com/vi/vk8-FxbH7KQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/vk8-FxbH7KQ/hqdefault.jpg","title":"สุสานเครื่องบินรามคำแหง (ซากเครื่องบินมรณะและวิญญาณวัน-ทู-โก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=vk8-FxbH7KQ","title":"The Mystery of Bangkok''s Airplane Graveyard","thumbnail":"https://i.ytimg.com/vi/vk8-FxbH7KQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-rong-khun-white-temple',
      'วัดร่องขุ่น (สวรรค์บนดินและสะพานข้ามวัฏสงสาร อ.เฉลิมชัย)',
      'Wat Rong Khun: The White Temple of Chiang Rai',
      'sacred',
      'เชียงราย',
      'Chiang Rai',
      'เมืองเชียงราย',
      'Mueang Chiang Rai',
      19.8242,
      99.7633,
      'temple_bell',
      'พุทธศิลป์ร่วมสมัยระดับโลกที่สร้างสรรค์โดยอาจารย์เฉลิมชัย โฆษิตพิพัฒน์ ศิลปินแห่งชาติ พระอุโบสถสีขาวบริสุทธิ์ประดับกระจกเงินแวววาว สื่อถึงพระบริสุทธิคุณและพระปัญญาธิคุณของพระพุทธเจ้า ผู้แสวงบุญต้องเดินข้าม ''สะพานข้ามวัฏสงสาร'' ซึ่งเบื้องล่างมีมือมนุษย์นับร้อยนับพันยื่นขึ้นมาจากขุมนรกเพื่อไขว่คว้าหลุดพ้นจากกิเลส ก่อนจะก้าวผ่านซุ้มพญามารเข้าสู่แดนสวรรค์และพระอุโบสถ ภายในมีจิตรกรรมฝาผนังร่วมสมัยที่แฝงปริศนาธรรมการหลุดพ้นจากวัฏสงสาร',
      'Wat Rong Khun, renowned globally as the White Temple, is the visionary masterpiece of National Artist Chalermchai Kositpipat. The dazzling white structure, encrusted with thousands of mirrored glass tiles, symbolizes Buddha''s supreme purity. Visitors cross the Bridge of the Cycle of Rebirth, suspended over a sea of hundreds of reaching hands representing hellish desires, before passing through celestial gates into the sanctuary containing profound allegorical frescoes.',
      'เริ่มก่อสร้างตั้งแต่ปี พ.ศ. 2540 และได้รับความเสียหายจากแผ่นดินไหวขนาด 6.3 ในปี 2557 ก่อนจะได้รับการบูรณะอย่างงดงามตระการตา เป็นหนึ่งในหมุดหมายปลายทางที่ดึงดูดนักท่องเที่ยวทั่วโลกมากที่สุดของไทย',
      'Surviving the major 2014 Mae Lao earthquake, Wat Rong Khun is an internationally celebrated cultural marvel blending traditional northern Buddhist art with surrealist modern motifs.',
      'ห้ามเดินถอยหลังบนสะพานข้ามวัฏสงสาร (เชื่อว่าเป็นการถอยหลังกลับสู่นรก)',
      'Never walk backward across the Bridge of the Cycle of Rebirth; you must only move forward.',
      'https://i.ytimg.com/vi/gHd9ly1teAY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/gHd9ly1teAY/hqdefault.jpg","title":"วัดร่องขุ่น (สวรรค์บนดินและสะพานข้ามวัฏสงสาร อ.เฉลิมชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=gHd9ly1teAY","title":"\"เที่ยววัดร่องขุ่น\" เชียงราย : อ.เฉลิมชัย โฆษิตพิพัฒน์ The white temple of Thailand","thumbnail":"https://i.ytimg.com/vi/gHd9ly1teAY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-rong-suea-ten-blue-temple',
      'วัดร่องเสือเต้น (วิหารสีน้ำเงินทองแห่งพุทธศิลป์ล้านนาร่วมสมัย)',
      'Wat Rong Suea Ten: The Radiant Blue Temple of Chiang Rai',
      'sacred',
      'เชียงราย',
      'Chiang Rai',
      'เมืองเชียงราย',
      'Mueang Chiang Rai',
      19.9234,
      99.8419,
      'temple_bell',
      'วิหารสีน้ำเงินครามเข้มตัดกับสีทองอร่ามอันวิจิตรตระการตา ออกแบบโดย พุทธา กาบแก้ว (สล่านก) ศิลปินท้องถิ่นชาวเชียงรายผู้เป็นศิษย์ของอาจารย์เฉลิมชัย สีน้ำเงินครามสื่อถึงพระธรรมคำสอนของพระพุทธองค์ที่แผ่ไพศาลไปทั่วโลกดั่งท้องฟ้า ภายในวิหารประดิษฐาน ''พระพุทธรัชมงคลบดีตรีโลกนาถ'' พระพุทธรูปสีขาวมุกบริสุทธิ์ขนาดหน้าตัก 5 เมตร สูง 6.5 เมตร ท่ามกลางจิตรกรรมฝาผนังลวดลายกนกพลิ้วไหวโทนสีน้ำเงินม่วงอันน่าอัศจรรย์ใจ',
      'Wat Rong Suea Ten, the Blue Temple, was designed by local artist Putha Khabkaew (Nok), a disciple of Chalermchai Kositpipat. The temple is cloaked in rich sapphire blue hues accented with radiant gold leaf, representing the boundless wisdom of Buddhist dharma spanning the celestial skies. Inside the sanctuary sits a colossal pearl-white Buddha statue surrounded by breathtaking fluid Naga carvings and mystical violet-indigo wall murals.',
      'เดิมเป็นวัดร้างโบราณที่เล่ากันว่าเคยมีเสือกระโดดข้ามร่องน้ำในอดีต จึงได้ชื่อว่า ''ร่องเสือเต้น'' ต่อมาชาวบ้านได้ร่วมใจกันบูรณะสร้างวิหารหลังใหม่ในปี 2548 จนกลายเป็นพุทธศิลป์ที่มีชื่อเสียงระดับโลก',
      'Completed in 2016 upon ancient ruined temple grounds where tigers once leaped across the creek, the Blue Temple is celebrated for its ethereal, modern take on traditional Lanna architecture.',
      'ห้ามยืนบังพระพักตร์พระประธานขณะถ่ายรูป หรือส่งเสียงดังภายในวิหาร',
      'Maintain respectful quiet and never stand blocking the sightline of the white Buddha statue.',
      'https://i.ytimg.com/vi/8ljAI03OXp4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8ljAI03OXp4/hqdefault.jpg","title":"วัดร่องเสือเต้น (วิหารสีน้ำเงินทองแห่งพุทธศิลป์ล้านนาร่วมสมัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8ljAI03OXp4","title":"ประวัติวัดร่องเสือเต้น  จ.เชียงราย Blue Temple Chiang Rai | 4K","thumbnail":"https://i.ytimg.com/vi/8ljAI03OXp4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-sanctuary-of-truth-pattaya',
      'ปราสาทสัจธรรม (มหาปราสาทไม้แกะสลักใหญ่ที่สุดในโลกแห่งพัทยา)',
      'Sanctuary of Truth: The World''s Largest Wooden Palace',
      'sacred',
      'ชลบุรี',
      'Chonburi',
      'บางละมุง',
      'Bang Lamung',
      12.9728,
      100.8892,
      'temple_bell',
      'มหาปราสาทไม้ทรงไทยจัตุรมุขขนาดยักษ์ริมแหลมราชเวช อ่าวพัทยา สูงกว่า 105 เมตร สร้างจากไม้เนื้อแข็งทั้งหลัง เช่น ไม้สัก ไม้ประดู่ และไม้ตะเคียน โดยใช้เทคนิคการเข้าเดือยไม้โบราณโดยไม่ใช้ตะปูแม้แต่ตัวเดียว ทุกตารางนิ้วของปราสาทเต็มไปด้วยงานประติมากรรมไม้แกะสลักอันวิจิตร ถ่ายทอดปรัชญาและจักรวาลทัศน์ทางพุทธ ฮินดู และเอเชียตะวันออก เพื่อสะท้อนความจริงสูงสุดของชีวิตว่า มนุษย์เกิดมาเพื่อสร้างคุณงามความดีและคืนสู่ธรรมชาติ',
      'Perched dramatically on the shoreline of Cape Ratchawet in Pattaya, the Sanctuary of Truth is the largest all-wood hand-carved castle in the world, soaring over 105 meters into the sky. Built using ancient joinery techniques without a single metal nail, the structure is crafted from teak, ironwood, and redwood. Every surface is adorned with thousands of intricate mythological sculptures reflecting Thai, Khmer, Indian, and Chinese spiritual philosophies on human existence.',
      'ริเริ่มสร้างขึ้นในปี พ.ศ. 2524 โดย คุณเล็ก วิริยะพันธุ์ ผู้ก่อตั้งเมืองโบราณและพิพิธภัณฑ์ช้างเอราวัณ เพื่อเป็นอนุสรณ์สถานแห่งสันติภาพและภูมิปัญญาทางจิตวิญญาณของมนุษยชาติ',
      'Conceived by eccentric patron Lek Viriyaphant in 1981, this living temple museum employs master craftsmen continuously restoring woodwork against coastal salt-air erosion.',
      'ผู้เข้าชมต้องสวมหมวกนิรภัยตลอดเวลา และห้ามแกะหรือหักชิ้นส่วนไม้แกะสลัก',
      'Safety helmets are mandatory inside; never touch or break fragile wooden carving details.',
      'https://i.ytimg.com/vi/TiYaydwc_74/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TiYaydwc_74/hqdefault.jpg","title":"ปราสาทสัจธรรม (มหาปราสาทไม้แกะสลักใหญ่ที่สุดในโลกแห่งพัทยา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TiYaydwc_74","title":"Sanctuary of Truth Pattaya Largest Wooden Temple in the World 🇹🇭 Thailand","thumbnail":"https://i.ytimg.com/vi/TiYaydwc_74/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-million-bottle-temple-sisaket',
      'วัดป่ามหาเจดีย์แก้ว (วัดล้านขวดแห่งขุนหาญ ศรีสะเกษ)',
      'Wat Pa Maha Chedi Kaew (The Million Bottle Temple)',
      'sacred',
      'ศรีสะเกษ',
      'Sisaket',
      'ขุนหาญ',
      'Khun Han',
      14.6186,
      104.4258,
      'temple_bell',
      'วัดพุทธที่สร้างขึ้นจากขวดแก้วรีไซเคิลกว่า 1.5 ล้านขวด ทั้งขวดเบียร์สีเขียวและขวดเครื่องดื่มชูกำลังสีชา พระครูวิเวกธรรมาจารย์ได้นำขวดแก้วที่ชาวบ้านรวบรวมมาสร้างเป็นพระอุโบสถ เจดีย์ ศาลา กุฏิสงฆ์ ห้องน้ำ และแนวกำแพงวัด แม้กระทั่งภาพพุทธประวัติบนผนังก็สร้างจากฝาจีบขวดเบียร์นับแสนฝา แสงแดดที่ส่องผ่านผนังขวดแก้วก่อให้เกิดประกายสีเขียวทองอร่ามอันเป็นเอกลักษณ์ และสะท้อนปรัชญาธรรมเรื่องการนำของไร้ค่ามาแปรเปลี่ยนเป็นสิ่งศักดิ์สิทธิ์',
      'Wat Pa Maha Chedi Kaew, famously known as the Million Bottle Temple, is constructed from over 1.5 million recycled glass bottles. Begun in 1984 by Buddhist monks who encouraged villagers to donate discarded beverage containers, the complex features a grand main temple, crematorium, water towers, and sleeping quarters built entirely of green Heineken and brown Chang/energy drink bottles set in concrete, with bottle caps used to create vibrant Buddha mosaics.',
      'นอกจากจะเป็นสถานที่ปฏิบัติธรรมอันเงียบสงบแล้ว วัดล้านขวดยังได้รับการยกย่องจากสถาปนิกทั่วโลกในฐานะตัวอย่างแรกเริ่มของการรีไซเคิลวัสดุเพื่อการอนุรักษ์สิ่งแวดล้อมในเชิงพุทธศาสนา',
      'Celebrated in international architecture and sustainability journals, the temple demonstrates innovative eco-friendly construction that has endured tropical storms for decades.',
      'ห้ามขว้างปาหิน หรือกระแทกสิ่งของแข็งใส่ผนังขวดแก้วของวัด',
      'Never strike, tap, or throw objects against the fragile recycled glass bottle walls.',
      'https://i.ytimg.com/vi/PkscBngUYdc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/PkscBngUYdc/hqdefault.jpg","title":"วัดป่ามหาเจดีย์แก้ว (วัดล้านขวดแห่งขุนหาญ ศรีสะเกษ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=PkscBngUYdc","title":"วัดป่ามหาเจดีย์แก้ว (วัดล้านขวด) ศรีสะเกษ สิ่งศักดิ์สิทธิ์ของไทย | Eager of Know","thumbnail":"https://i.ytimg.com/vi/PkscBngUYdc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-samphran-dragon-temple',
      'วัดสามพราน (หอคอยมังกรทองตะกายฟ้า 17 ชั้น นครปฐม)',
      'Wat Samphran: The 17-Story Giant Dragon Tower',
      'sacred',
      'นครปฐม',
      'Nakhon Pathom',
      'สามพราน',
      'Sam Phran',
      13.735,
      100.2158,
      'temple_bell',
      'หอคอยทรงกระบอกสีชมพูสูง 17 ชั้น (ประมาณ 80 เมตร สื่อถึงพระชนมายุของพระพุทธเจ้าเมื่อปรินิพพาน) โดดเด่นด้วยประติมากรรมมังกรยักษ์สีเขียวทองเลื้อยพันโอบล้อมรอบตัวอาคารจากฐานล่างขึ้นสู่ยอดฟ้า ลำตัวของมังกรมีลักษณะกลวงเป็นอุโมงค์ทางเดินบันไดวนที่ผู้แสวงบุญสามารถเดินก้าวขึ้นไปสู่ยอดหอคอย บนดาดฟ้าประดิษฐานพระพุทธรูปปางประทานพรสีทอง และเป็นจุดสักการะเคราและกรงเล็บของพญามังกรเพื่อขอพรความเจริญรุ่งเรือง',
      'Wat Samphran is famous for its 80-meter-tall cylinder tower clad in pink, representing the 80 years of Gautama Buddha''s earthly life. Wrapping around the entire tower is a colossal green and gold dragon sculpture, whose hollow scaled belly forms an ascending spiral tunnel for pilgrims walking to the top. At the summit roof terrace, visitors can touch the dragon''s bearded chin and claws while praying before a golden Buddha statue overlooking the Nakhon Pathom plains.',
      'สร้างขึ้นจากนิมิตสมาธิของเจ้าอาวาสในปี พ.ศ. 2528 ถือเป็นหนึ่งในงานสถาปัตยกรรมทางศาสนาที่แปลกตาและเปี่ยมไปด้วยจินตนาการที่สุดแห่งหนึ่งของประเทศไทย',
      'Rising above lush palm groves, the dragon tower has captured global attention on travel channels as one of Southeast Asia''s most visually striking architectural temples.',
      'ห้ามปีนป่ายออกนอกลำตัวมังกรบนยอดดาดฟ้าอาคาร',
      'Never climb outside safety barriers onto the dragon''s outer scales on the rooftop.',
      'https://i.ytimg.com/vi/oNtzIg5mo-o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/oNtzIg5mo-o/hqdefault.jpg","title":"วัดสามพราน (หอคอยมังกรทองตะกายฟ้า 17 ชั้น นครปฐม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=oNtzIg5mo-o","title":"Unseen นครปฐม! บุก \"วัดสามพราน\" เดินลัดเลาะท้องมังกรยักษ์พันกูฏิสีชมพู 80 เมตร | guyuptome","thumbnail":"https://i.ytimg.com/vi/oNtzIg5mo-o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-pha-sorn-kaew-khao-kho',
      'วัดพระธาตุผาซ่อนแก้ว (วิหารพระพุทธเจ้า 5 พระองค์กลางทะเลหมอก)',
      'Wat Pha Sorn Kaew: Temple on a High Glass Cliff (Khao Kho)',
      'sacred',
      'เพชรบูรณ์',
      'Phetchabun',
      'เขาค้อ',
      'Khao Kho',
      16.7897,
      101.0519,
      'temple_bell',
      'วัดพุทธศาสนาบนยอดเขาสูงท่ามกลางขุนเขาเขาค้อ โดดเด่นด้วยพระพุทธรูปสีขาวซ้อนกัน 5 องค์ เรียงจากองค์เล็กไปหาองค์ใหญ่ สื่อถึงพระพุทธเจ้า 5 พระองค์ในภัทรกัป เจดีย์พระธาตุผาซ่อนแก้วประดับตกแต่งด้วยกระเบื้องเบญจรงค์ อัญมณี หินสี เครื่องเบญจรงค์โบราณ และถ้วยชามศิลาดลกว่า 5 ล้านชิ้น ส่องประกายระยิบระยับล้อแสงตะวัน ตำนานเล่าว่าชาวบ้านเคยเห็นลูกแก้วสารพัดนึกเปล่งประกายลอยลงมาจากฟากฟ้าและหายเข้าไปในถ้ำบนหน้าผาแห่งนี้',
      'Perched on a breathtaking misty peak in Khao Kho, Wat Pha Sorn Kaew features five magnificent nested white Buddha statues sitting in meditation, gazing serenely across green mountain ridges. The sanctuary chedi is decorated with a mosaic of over five million vibrant ceramic tiles, pottery fragments, and precious gemstones. The site takes its name from local lore of a luminous crystal sphere that floated down from the heavens into a cliffside cave.',
      'ก่อตั้งขึ้นในปี พ.ศ. 2547 เพื่อเป็นสถานที่ปฏิบัติธรรมวิปัสสนากรรมฐานท่ามกลางธรรมชาติอันสงบ ปัจจุบันเป็นหนึ่งในแลนด์มาร์กทางจิตวิญญาณที่งดงามที่สุดของไทย',
      'Founded as a Dhamma hermitage by Phra Ajahn Aumnart Jattano, the temple''s mosaic craftsmanship and mountain acoustics draw pilgrims from around the Buddhist world.',
      'ห้ามเหยียบย่ำบนกระเบื้องโมเสกสีลวดลายดอกบัวด้วยรองเท้า',
      'Remove all footwear and walk gently upon the sacred mosaic tiled terraces.',
      'https://i.ytimg.com/vi/jdXD8jemIRg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jdXD8jemIRg/hqdefault.jpg","title":"วัดพระธาตุผาซ่อนแก้ว (วิหารพระพุทธเจ้า 5 พระองค์กลางทะเลหมอก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jdXD8jemIRg","title":"วัดพระธาตุผาซ่อนแก้ว เขาค้อ อัพเดทวัดพระธาตุผาซ่อนแก้ว รีวิวเส้นทางขึ้นวัดพระธาตุผาซ่อนแก้ว 2024","thumbnail":"https://i.ytimg.com/vi/jdXD8jemIRg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-muang-giant-sitting-buddha',
      'วัดม่วง (หลวงพ่อใหญ่ พระพุทธรูปนั่งสูงที่สุดในประเทศไทย อ่างทอง)',
      'Wat Muang & The Great Buddha of Thailand (Ang Thong)',
      'sacred',
      'อ่างทอง',
      'Ang Thong',
      'วิเศษชัยชาญ',
      'Wiset Chai Chan',
      14.5936,
      100.3808,
      'temple_bell',
      'ที่ประดิษฐาน ''พระพุทธมหานวมินทร์ศากยมุนีศรีวิเศษชัยชาญ'' หรือหลวงพ่อใหญ่ พระพุทธรูปปางมารวิชัยสีทองอร่ามที่สูงที่สุดในประเทศไทยและสูงเป็นอันดับต้นๆ ของโลก ด้วยความสูงถึง 92 เมตร (เทียบเท่าตึก 32 ชั้น) หน้าตักกว้าง 63 เมตร สร้างจากคอนกรีตเสริมเหล็กทาสีทองคำ ผู้แสวงบุญจะเข้าแถวเพื่อเอื้อมมือสัมผัสปลายนิ้วพระหัตถ์ขวาขององค์พระใหญ่ เพื่อขอพรให้ขจัดอุปสรรคและความทุกข์ยากในชีวิต บริเวณวัดยังมีสวนประติมากรรมแดนนรกและสวรรค์จำลอง',
      'Wat Muang houses the Great Buddha of Thailand (Luangpho Yai), the tallest statue in Thailand and the third-tallest seated Buddha in the world. Soaring 92 meters (300 feet) high with a lap width of 63 meters, the gold-painted concrete giant took 16 years to complete. Pilgrims gather on a raised platform beneath the statue''s right hand, reaching up to touch the colossal fingertips while whispering prayers for blessings and spiritual redemption.',
      'ริเริ่มสร้างโดยหลวงพ่อเกษม อาจารสุโภ ในปี พ.ศ. 2534 เพื่อถวายเป็นพระราชกุศลแด่พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร',
      'A magnificent example of modern Thai monumental devotional engineering, Wat Muang also features extensive folk art dioramas depicting karmic Buddhist hell realms.',
      'ห้ามปีนป่ายขึ้นไปบนฐานบัวรองรับพระหัตถ์ขององค์พระใหญ่',
      'Never attempt to climb onto the lotus base pedestals beneath the Buddha''s hands.',
      'https://i.ytimg.com/vi/GtOPmLo89bw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/GtOPmLo89bw/hqdefault.jpg","title":"วัดม่วง (หลวงพ่อใหญ่ พระพุทธรูปนั่งสูงที่สุดในประเทศไทย อ่างทอง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=GtOPmLo89bw","title":"น้อยคนจะได้เห็นสิ่งนี้ ศรัทธาสูงเสียดฟ้า ผู้ใหญ่นะ  ไต่องค์พระ สูงเท่าตึก 30 ชั้น l SUPER100","thumbnail":"https://i.ytimg.com/vi/GtOPmLo89bw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-tham-suea-krabi',
      'วัดถ้ำเสือ (พุทธสถานบันได 1,237 ขั้นสู่ยอดผาศักดิ์สิทธิ์กระบี่)',
      'Wat Tham Suea: The Tiger Cave Temple of Krabi',
      'sacred',
      'กระบี่',
      'Krabi',
      'เมืองกระบี่',
      'Mueang Krabi',
      8.1242,
      98.9247,
      'temple_bell',
      'วัดป่าวิปัสสนาอันเลื่องชื่อที่ตั้งอยู่ท่ามกลางหุบเขาและป่าดงดิบโบราณ มีถ้ำธรรมชาติที่มีรอยอุ้งเท้าเสือปรากฏบนหิน ซึ่งตำนานเล่าว่าในอดีตเคยมีเสือโคร่งขนาดยักษ์อาศัยอยู่ ไฮไลต์ศักดิ์สิทธิ์สูงสุดคือการเดินเท้าพิชิตบันไดหินชัน 1,237 ขั้น ขึ้นสู่ยอดเขาสูง 278 เมตร บนยอดเขาประดิษฐานพระเจดีย์ระฆังทองคำและรอยพระพุทธบาทจำลอง พร้อมทิวทัศน์ 360 องศาของเทือกเขาหินปูนและทะเลอันดามัน',
      'Wat Tham Suea (Tiger Cave Temple) is a revered meditation sanctuary tucked within a karst forest valley. The cave features natural limestone formations resembling tiger paws, where tigers historically roamed and sheltered. The crowning pilgrimage challenge is ascending 1,237 steep, dizzying stone steps up a sheer limestone pinnacle to reach the summit terrace, crowned by a majestic golden seated Buddha, a golden chedi, and panoramic views over Krabi''s peaks.',
      'ก่อตั้งขึ้นโดย พระอาจารย์จำเนียร สีลเสฏโฐ ในปี พ.ศ. 2518 เป็นศูนย์กลางการฝึกปฏิบัติธรรมวิปัสสนาที่ได้รับความเคารพนับถือจากทั้งชาวไทยและชาวต่างชาติ',
      'Known for its troops of wild macaques along the staircase and sacred relic vaults, Wat Tham Suea offers an arduous physical and spiritual climb rewarding visitors with breathtaking sunrises.',
      'ห้ามให้อาหารลิงป่าบนบันได และห้ามสวมกางเกงขาสั้นขึ้นสู่ลานพระธาตุยอดเขา',
      'Never feed wild monkeys along the ascent; modest clothing covering knees is required.',
      'https://i.ytimg.com/vi/VLDbmdDoqQ0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/VLDbmdDoqQ0/hqdefault.jpg","title":"วัดถ้ำเสือ (พุทธสถานบันได 1,237 ขั้นสู่ยอดผาศักดิ์สิทธิ์กระบี่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=VLDbmdDoqQ0","title":"เด็ก 7 ขวบ  ซ่าท้าบันไดที่วัดถ้ำเสือ 1,237 ขั้น จะรอดมั้ยเนี่ย !","thumbnail":"https://i.ytimg.com/vi/VLDbmdDoqQ0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-phra-that-pha-ngao-chiang-saen',
      'วัดพระธาตุผาเงา (พระพุทธรูปใต้ดินและสกายวอล์กสามแผ่นดิน เชียงแสน)',
      'Wat Phra That Pha Ngao (The Shadow Rock Relic of Chiang Saen)',
      'sacred',
      'เชียงราย',
      'Chiang Rai',
      'เชียงแสน',
      'Chiang Saen',
      20.2472,
      100.1258,
      'temple_bell',
      'วัดโบราณริมแม่น้ำโขงในเมืองประวัติศาสตร์เชียงแสน ตั้งอยู่บนเนินเขาที่มีก้อนหินผาขนาดยักษ์ทอดร่มเงาลงมา จึงได้ชื่อว่า ''ผาเงา'' ในปี 2519 มีการขุดค้นพบพระพุทธรูปหินทรายโบราณศิลปะเชียงแสนอายุกว่า 700 ปี ซ่อนอยู่ใต้ฐานพระประธานดินเผา ซึ่งมีชื่อว่า ''หลวงพ่อผาเงา'' บนยอดเขายังมีเจดีย์เจ็ดยอดโบราณและสกายวอล์กกระจกใสที่สามารถชมทิวทัศน์แม่น้ำโขงบรรจบสามประเทศ (ไทย ลาว เมียนมา) ได้อย่างงดงาม',
      'Overlooking the Mekong River in historic Chiang Saen, Wat Phra That Pha Ngao is named after a massive overhanging boulder (''Pha Ngao'' meaning Shadow Rock). In 1976, excavations beneath a brick altar revealed ''Luang Pho Pha Ngao''—a pristine 700-year-old carved sandstone Chiang Saen Buddha statue buried to protect it from historical invasions. The mountain peak features the Phra Borommathat Phutthaniwi Chedi and a glass skywalk gazing across Thailand, Laos, and Myanmar.',
      'เชียงแสนเป็นเมืองหลวงเก่าแก่แห่งแรกของอาณาจักรล้านนา วัดพระธาตุผาเงาได้รับการบูรณะให้เป็นศูนย์กลางแห่งความสงบและการฟื้นฟูพระพุทธศาสนาในลุ่มน้ำโขง',
      'Encompassing ancient stupa ruins dating to the Yonok Chiang Saen kingdom, the site combines archaeological heritage with modern spiritual pilgrimage.',
      'ห้ามสวมรองเท้าเดินบนพื้นกระจกสกายวอล์ก ต้องสวมถุงผ้าหุ้มรองเท้าที่จัดไว้',
      'Always wear designated fabric shoe covers before stepping onto the glass skywalk platform.',
      'https://i.ytimg.com/vi/WNWlNuII3vE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/WNWlNuII3vE/hqdefault.jpg","title":"วัดพระธาตุผาเงา (พระพุทธรูปใต้ดินและสกายวอล์กสามแผ่นดิน เชียงแสน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=WNWlNuII3vE","title":"สกายวอล์ค วัดพระธาตุผาเงา  อ.เชียงแสน จ.เชียงราย","thumbnail":"https://i.ytimg.com/vi/WNWlNuII3vE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-chedi-luang-chiang-mai',
      'วัดเจดีย์หลวงวรวิหาร (มหาเจดีย์ล้านนาและเสาอินทขีลเมืองเชียงใหม่)',
      'Wat Chedi Luang: The Grand Stupa & City Pillar of Chiang Mai',
      'sacred',
      'เชียงใหม่',
      'Chiang Mai',
      'เมืองเชียงใหม่',
      'Mueang Chiang Mai',
      18.7872,
      98.9867,
      'temple_bell',
      'มหาเจดีย์โบราณขนาดมหึมาใจกลางเวียงเชียงใหม่ สร้างขึ้นในปี พ.ศ. 1934 ในรัชสมัยพญากือนา ในอดีตเคยสูงถึง 82 เมตร และกว้าง 54 เมตร เคยเป็นที่ประดิษฐาน ''พระแก้วมรกต'' นานกว่า 80 ปี ก่อนที่ส่วนยอดเจดีย์จะพังทลายลงจากแผ่นดินไหวครั้งใหญ่ในปี 2088 ฐานช้างค้ำแกะสลักหินปูนรอบเจดีย์ยังคงแสดงความเกรียงไกร ภายในบริเวณวัดยังเป็นที่ประดิษฐาน ''เสาอินทขีล'' หรือเสาหลักเมืองเชียงใหม่ ซึ่งมีประเพณีบูชาเสาอินทขีลใส่ขันดอกทุกปีเพื่อความร่มเย็นของบ้านเมือง',
      'Built in 1391 by King Saen Muang Ma, Wat Chedi Luang was once the grandest monument in northern Thailand, soaring 82 meters high with a base width of 54 meters. For 80 years, its eastern niche enshrined the sacred Emerald Buddha before it was relocated. A catastrophic earthquake in 1545 brought down its summit, leaving the magnificent brick pyramid standing 60 meters tall, guarded by monumental stone elephants. The grounds also enshrine the Inthakhin (City Pillar).',
      'กรมศิลปากรได้ดำเนินการบูรณะเจดีย์หลวงในปี 2533-2535 โดยคงรูปทรงยอดหักไว้ตามหลักวิชาการอนุรักษ์โบราณสถาน เพื่อสะท้อนประวัติศาสตร์อันแท้จริง',
      'Restored in the 1990s with UNESCO and Japanese support, the ruined brick monolith remains the iconic beating spiritual heart of Chiang Mai''s walled old city.',
      'สตรีห้ามก้าวเข้าไปภายในวิหารเสาอินทขีล (เสาหลักเมือง) ตามจารีตโบราณล้านนา',
      'Women are strictly prohibited from entering the inner City Pillar (Inthakhin) shrine under ancient Lanna custom.',
      'https://i.ytimg.com/vi/0OJ8BUNf88E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0OJ8BUNf88E/hqdefault.jpg","title":"วัดเจดีย์หลวงวรวิหาร (มหาเจดีย์ล้านนาและเสาอินทขีลเมืองเชียงใหม่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0OJ8BUNf88E","title":"ตำนาน สองพญายักษ์เฝ้าเสาหลักเมืองเชียงใหม่ วัดเจดีย์หลวง I แปลกเหนือแปลก","thumbnail":"https://i.ytimg.com/vi/0OJ8BUNf88E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-phra-that-doi-suthep',
      'วัดพระธาตุดอยสุเทพ (พระบรมธาตุคู่บ้านคู่เมืองเชียงใหม่)',
      'Wat Phra That Doi Suthep: The Sacred Mountain Crown of Lanna',
      'sacred',
      'เชียงใหม่',
      'Chiang Mai',
      'เมืองเชียงใหม่',
      'Mueang Chiang Mai',
      18.805,
      98.9217,
      'temple_bell',
      'พระธาตุศักดิ์สิทธิ์บนยอดดอยสุเทพ สูง 1,053 เมตรเหนือระดับน้ำทะเล สร้างขึ้นในปี พ.ศ. 1927 ตามตำนานเล่าว่า พระสุมนเถระได้อัญเชิญพระบรมสารีริกธาตุมาจากสุโขทัย พระเจ้ากือนาทรงให้อัญเชิญพระธาตุประดิษฐานบนหลังช้างมงคล ช้างได้เดินขึ้นดอยสุเทพ เมื่อถึงยอดเขาได้ส่งเสียงร้องสามครั้ง คุกเข่าลงและสิ้นใจ พระองค์จึงสั่งให้สร้างเจดีย์สีทองอร่ามครอบพระธาตุไว้ บันไดนาค 306 ขั้นทอดนำสู่พระเจดีย์ทรงระฆังคว่ำศิลปะล้านนาอันเป็นศูนย์รวมศรัทธา',
      'Founded in 1383 by King Keu Naone, Wat Phra That Doi Suthep reigns high above Chiang Mai. According to Buddhist chronicles, a sacred relic was placed upon the back of a white royal elephant released into the forest. The elephant climbed Doi Suthep, trumpeted three times, circled the summit, knelt, and peacefully died—marking the spot chosen by destiny for the golden chedi. Devotees climb 306 Naga-flanked stairs to walk three times around the golden spire.',
      'ถนนขึ้นดอยสุเทพสร้างขึ้นด้วยแรงศรัทธาของชาวเหนือ นำโดยครูบาศรีวิชัย ในปี พ.ศ. 2477 โดยใช้เวลาสร้างเพียง 5 เดือน 22 วัน โดยไม่ใช้งบประมาณของรัฐแม้แต่บาทเดียว',
      'The historic road was hand-carved in 1935 through the devotion of monk Kruba Srivichai and thousands of volunteers, solidifying Doi Suthep as northern Thailand''s spiritual apex.',
      'ต้องถอดรองเท้าและแต่งกายสุภาพเรียบร้อยก่อนก้าวเข้าสู่ลานพระธาตุทองคำ',
      'Remove all footwear and wear modest attire before stepping onto the sacred golden stupa courtyard.',
      'https://i.ytimg.com/vi/D83YNuFAxvU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/D83YNuFAxvU/hqdefault.jpg","title":"วัดพระธาตุดอยสุเทพ (พระบรมธาตุคู่บ้านคู่เมืองเชียงใหม่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D83YNuFAxvU","title":"แต้อี้ แต้กะ EP.1 | \"ครูบาศรีวิชัย\" ไม่ได้สร้างทางขึ้นวัดพระธาตุดอยสุเทพ ?","thumbnail":"https://i.ytimg.com/vi/D83YNuFAxvU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-mahathat-ayutthaya-tree-roots',
      'เศียรพระพุทธรูปในรากไม้แห่งวัดมหาธาตุ (อยุธยา)',
      'Buddha Head in Tree Roots at Wat Mahathat (Ayutthaya)',
      'sacred',
      'พระนครศรีอยุธยา',
      'Phra Nakhon Si Ayutthaya',
      'พระนครศรีอยุธยา',
      'Phra Nakhon Si Ayutthaya',
      14.3569,
      100.5678,
      'temple_bell',
      'วัดมหาธาตุเป็นศูนย์กลางจิตวิญญาณและพระอารามหลวงใจกลางกรุงศรีอยุธยา สร้างขึ้นตั้งแต่สมัยสมเด็จพระบรมราชาธิราชที่ 1 หลังการเสียกรุงในปี พ.ศ. 2310 วัดถูกเผาทำลายจนเศียรพระพุทธรูปหินทรายกลิ้งตกลงมาที่โคนต้นโพธิ์ กาลเวลาผ่านไปหลายร้อยปี รากของต้นโพธิ์ใหญ่ได้เติบโตโอบอุ้มเศียรพระพุทธรูปไว้อย่างสงบนิ่ง โดยไม่ทำลายเนื้อหิน เกิดเป็นภาพมหัศจรรย์ของพระพักตร์อันเปี่ยมเมตตาที่แย้มสรวลท่ามกลางรวงรากไม้ สื่อถึงสัจธรรมแห่งการอยู่ร่วมกันระหว่างธรรมชาติและพระธรรม',
      'Wat Mahathat was the royal religious epicenter of the Ayutthaya Kingdom, housing sacred relics. Following the destruction of the capital in 1767, the temple was sacked and statues decapitated. One sandstone Buddha head fell beneath a sacred Bodhi tree; over two centuries, the living roots gently embraced and elevated the stone visage within its trunk without damaging it. The serene, smiling Buddha head nestled in ancient roots is one of the world''s most poetic symbols of spiritual endurance.',
      'อุทยานประวัติศาสตร์พระนครศรีอยุธยาได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโกในปี พ.ศ. 2534 ภาพเศียรพระในรากไม้กลายเป็นสัญลักษณ์ระดับโลกของการท่องเที่ยวไทย',
      'Part of the UNESCO World Heritage City of Ayutthaya, this site is reverently protected. Signs require tourists to crouch so their heads remain lower than the sacred Buddha face when taking photographs.',
      'ห้ามยืนค้ำหัวหรือยืนสูงกว่าเศียรพระพุทธรูปขณะถ่ายภาพ ต้องนั่งลงในระดับที่ต่ำกว่า',
      'Always squat or kneel when taking photographs so your head remains lower than the sacred Buddha head.',
      'https://i.ytimg.com/vi/TPS6E4vkJOE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/TPS6E4vkJOE/hqdefault.jpg","title":"เศียรพระพุทธรูปในรากไม้แห่งวัดมหาธาตุ (อยุธยา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TPS6E4vkJOE","title":"ระดับโลก!ไขปริศนาเศียรพระในรากโพธิ์ วัดมหาธาตุอยุธยา 700ปีแห่งความอัศจรรย์และประวัติศาสตร์ที่ถูกซ่อน","thumbnail":"https://i.ytimg.com/vi/TPS6E4vkJOE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-konark-sun-temple-chariot',
      'วิหารสุริยเทพแห่งโคนาร์ค (มหาราชรถหินแกะสลักแห่งโอริสสา)',
      'Konark Sun Temple: The Colossal Stone Chariot of Surya',
      'sacred',
      'โอริสสา',
      'Odisha',
      'ปูริ',
      'Puri',
      19.8876,
      86.0945,
      'temple_bell',
      'วิหารฮินดูในศตวรรษที่ 13 ริมชายฝั่งอ่าวเบงกอล ออกแบบสร้างเป็นรูป ''มหาราชรถ'' ของสุริยเทพ (พระอาทิตย์) ลากด้วยม้าหินแกะสลัก 7 ตัว (สื่อถึงวันทั้ง 7 ในสัปดาห์) และมีล้อหินยักษ์ 24 วง (สื่อถึง 24 ปักษ์ในหนึ่งปี) ล้อหินแต่ละวงสลักลวดลายวิจิตรและทำหน้าที่เป็น ''นาฬิกาแดด'' ที่สามารถบอกเวลาได้อย่างแม่นยำตามเงาของแกนล้อ กองหินแกรนิตและหินคลอไรต์ขนาดมหึมาถูกประกอบขึ้นด้วยหมุดเหล็กและแม่เหล็กมหาศาล ซึ่งในอดีตเคยมีตำนานว่ายอดวิหารมีหินแม่เหล็กที่ดูดเข็มทิศเรือเดินสมุทร',
      'Built in 1250 AD by King Narasimhadeva I, the Konark Sun Temple is designed as a colossal architectural chariot for the sun god Surya. Pulled by seven rearing stone horses across the sky, the chariot features 24 exquisitely carved stone wheels nearly ten feet in diameter. Each wheel functions as a precision sundial, casting shadows from its spokes to indicate exact hours and minutes. Rabindranath Tagore wrote: ''Here the language of stone surpasses the language of human.''',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1984 กลาสีเรือชาวยุโรปในอดีตเรียกวิหารนี้ว่า ''เจดีย์สีดำ'' (Black Pagoda) เนื่องจากหินมีสีเข้มเมื่อมองจากทะเล',
      'A UNESCO World Heritage Site, Konark is famous for its intricate Kalinga architectural carvings depicting celestial dancers, musicians, and erotic mithuna sculptures.',
      'ห้ามปีนป่ายขึ้นไปบนล้อหินนาฬิกาแดด หรือขูดขีดเนื้อหินแกะสลัก',
      'Never climb upon the carved sundial chariot wheels or touch the delicate stone reliefs.',
      'https://i.ytimg.com/vi/XSwBzLyxEDM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XSwBzLyxEDM/hqdefault.jpg","title":"วิหารสุริยเทพแห่งโคนาร์ค (มหาราชรถหินแกะสลักแห่งโอริสสา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XSwBzLyxEDM","title":"Konark Sun Temple Mystery | The Story of Odisha’s Black Pagoda","thumbnail":"https://i.ytimg.com/vi/XSwBzLyxEDM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-khajuraho-chandela-sculptures',
      'หมู่เทวาลัยคาจูราโฮ (วิหารหินทรายแห่งความรักและจิตวิญญาณ)',
      'Khajuraho Group of Monuments & The Kandariya Mahadeva',
      'sacred',
      'มัธยประเทศ',
      'Madhya Pradesh',
      'ฉัตตาร์ปูร์',
      'Chhatarpur',
      24.8318,
      79.9199,
      'temple_bell',
      'กลุ่มวิหารฮินดูและเชนในศตวรรษที่ 10 สร้างขึ้นโดยราชวงศ์จันเดลา ท่ามกลางหุบเขาป่าทึบ วิหารกันดาริยา มหาเทวะ สูงตระหง่านกว่า 31 เมตร เลียนแบบยอดเขาพระศิวะ ทุกตารางนิ้วของผนังหินทรายสีทองสลักรูปปั้นนูนสูงกว่าหลายหมื่นชิ้นอย่างประณีต แสดงภาพวิถีชีวิต กองทัพ ดนตรี นางอัปสร และภาพศิลปะกามสูตร (Mithuna) อันโด่งดัง ซึ่งในปรัชญาฮินดูถือว่า ความรักและการหลอมรวมเป็นหนึ่งเดียวกันของชายหญิงเป็นบันไดขั้นหนึ่งของการเข้าถึงจิตวิญญาณสูงสุดและหลุดพ้นจากสังสารวัฏ',
      'Erected between 950 and 1050 AD by the Chandela Dynasty, Khajuraho''s sandstone temples are celebrated for architectural balance and exquisite sculptures. The towering Kandariya Mahadeva temple features over 800 statues carved into its spires. While globally famous for explicit erotic carvings (representing Kama, one of the four purusharthas or legitimate goals of human life), 90% of the reliefs depict everyday medieval life, farmers, musicians, and cosmic deities.',
      'วิหารรอดพ้นจากการถูกทำลายในยุคกลางเนื่องจากซ่อนตัวอยู่ใต้ป่าดงดิบหนาทึบ ก่อนจะถูกค้นพบใหม่โดยวิศวกรกองทัพอังกฤษ ที.เอส. เบิร์ท ในปี 1838',
      'Inscribed on the UNESCO World Heritage list in 1986, Khajuraho represents the pinnacle of northern Indian Nagara-style temple architecture.',
      'ห้ามสัมผัสหรือทำลายรูปสลักหินทรายโบราณรอบผนังเทวาลัย',
      'Never touch or climb upon the intricate sandstone carvings adorning the outer plinths.',
      'https://i.ytimg.com/vi/IuYcjtjc0ec/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IuYcjtjc0ec/hqdefault.jpg","title":"หมู่เทวาลัยคาจูราโฮ (วิหารหินทรายแห่งความรักและจิตวิญญาณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IuYcjtjc0ec","title":"Khajuraho - Group of Temples | UNESCO WORLD HERITAGE SITE | Travelclix","thumbnail":"https://i.ytimg.com/vi/IuYcjtjc0ec/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-ajanta-caves-frescoes',
      'ถ้ำอชันตา (มหากาพย์พุทธศิลป์ภาพจิตรกรรมฝาผนัง 2,000 ปี)',
      'The Ajanta Caves: Masterpieces of Ancient Buddhist Rock Art',
      'sacred',
      'มหาราษฏระ',
      'Maharashtra',
      'เอารังคาบัด',
      'Chhatrapati Sambhajinagar',
      20.5519,
      75.7033,
      'temple_bell',
      'กลุ่มถ้ำพุทธศาสนา 30 ถ้ำที่สลักเจาะเข้าไปในหน้าผาหินบะซอลต์ทรงเกือกม้าเหนือแม่น้ำวากูระ สร้างขึ้นตั้งแต่ช่วงศตวรรษที่ 2 ก่อนคริสตกาล ภายในถ้ำเก็บรักษาภาพจิตรกรรมฝาผนังสีธรรมชาติ (Frescoes) ที่สมบูรณ์และงดงามที่สุดในประวัติศาสตร์พุทธศิลป์ ถ่ายทอดเรื่องราวชาดกและพุทธประวัติด้วยเส้นสายที่อ่อนช้อยและแววตาเปี่ยมเมตตา โดยเฉพาะภาพ ''พระโพธิสัตว์ปัทมปาณี'' ผู้ถือดอกบัวสีน้ำเงิน ถ้ำเหล่านี้ถูกทิ้งร้างและกลืนหายไปในป่าทึบนานนับพันปี จนกระทั่งนายทหารอังกฤษ จอห์น สมิธ บังเอิญพบเข้าขณะล่าเสือในปี 1819',
      'Carved into a horseshoe-shaped granite cliff overlooking the Waghora River, the 30 Ajanta Caves represent the golden age of ancient Indian Buddhist art, dating from the 2nd century BC to 480 AD. The rock-cut viharas and chaityas are famous for their luminous tempera wall murals illustrating Jataka tales. The iconic painting of Bodhisattva Padmapani holding a blue lotus displays divine compassion and artistic grace that influenced Buddhist iconography across Asia.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกรุ่นแรกในปี 1983 สีของภาพวาดสกัดจากแร่ธาตุธรรมชาติ ดินเหนียว และหินสี เช่น ลาพิส ลาซูลี ทำให้สียังคงสดใสผ่านกาลเวลากว่าสองพันปี',
      'Accidentally rediscovered by British officer John Smith in 1819, Ajanta remains a cornerstone of Asian art history and Buddhist monastic archaeology.',
      'ห้ามใช้แฟลชถ่ายภาพจิตรกรรมฝาผนังโบราณเด็ดขาด เพื่อป้องกันแสงทำลายเม็ดสี',
      'Flash photography is strictly banned to protect the 2,000-year-old natural mineral pigments.',
      'https://i.ytimg.com/vi/-hhEqU9FiJI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-hhEqU9FiJI/hqdefault.jpg","title":"ถ้ำอชันตา (มหากาพย์พุทธศิลป์ภาพจิตรกรรมฝาผนัง 2,000 ปี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-hhEqU9FiJI","title":"Ajanta  the history & mystery","thumbnail":"https://i.ytimg.com/vi/-hhEqU9FiJI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-todai-ji-great-daibutsu-nara',
      'วัดโทไดจิ (มหาวิหารไม้ใหญ่ที่สุดในโลกและพระใหญ่ไดบุตสึแห่งนารา)',
      'Todai-ji & The Great Bronze Daibutsu of Nara',
      'sacred',
      'นารา',
      'Nara',
      'นารา',
      'Nara',
      34.69,
      135.8398,
      'temple_bell',
      'วิหารหลวงไดบุตสึเด็งแห่งวัดโทไดจิ เป็นอาคารไม้ที่ใหญ่ที่สุดในโลก สร้างขึ้นในศตวรรษที่ 8 โดยจักรพรรดิโชมุ เพื่อรวมใจคนทั้งชาติให้พ้นจากโรคระบาดและภัยธรรมชาติ ภายในประดิษฐาน ''พระไวโรจนะพุทธเจ้า'' (ไดบุตสึแห่งนารา) พระพุทธรูปทองสัมฤทธิ์ขนาดมหึมาสูงเกือบ 15 เมตร หนักกว่า 500 ตัน เสาไม้ต้นหนึ่งด้านหลังมีช่องเจาะรูขนาดเท่ารูจมูกของพระใหญ่ มีความเชื่อว่าใครที่สามารถคลานลอดผ่านเสานี้ได้จะพบกับความโชคดีและบรรลุธรรม',
      'Todai-ji (Eastern Great Temple) in Nara houses the Daibutsu-den, the largest historic wooden building in the world. Commissioned in 743 AD by Emperor Shomu to protect Japan from smallpox epidemics, the hall houses the colossal bronze Vairocana Buddha (Daibutsu) standing nearly 15 meters tall and weighing 500 tons. Behind the statue stands a massive wooden pillar with a hollow opening at its base; legend says whoever squeezes through will achieve enlightenment and good health.',
      'การหล่อพระใหญ่ไดบุตสึในสมัยนาราใช้ทองแดงและดีบุกมหาศาลจนเกือบทำให้เศรษฐกิจของญี่ปุ่นล้มละลาย ปัจจุบันเป็นมรดกโลกยูเนสโกและสัญลักษณ์จิตวิญญาณของนารา',
      'Serving as the head temple of the Kegon sect of Buddhism, Todai-ji is surrounded by the sacred sika deer of Nara Park, revered as messengers of the Shinto gods.',
      'ห้ามให้อาหารแปลกปลอมแก่กวางศักดิ์สิทธิ์รอบวัด ให้ใช้เฉพาะ ''เซมเบ้กวาง'' เท่านั้น',
      'Feed only approved shika-senbei crackers to the sacred deer roaming temple grounds.',
      'https://i.ytimg.com/vi/8AocXQQK5Ls/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8AocXQQK5Ls/hqdefault.jpg","title":"วัดโทไดจิ (มหาวิหารไม้ใหญ่ที่สุดในโลกและพระใหญ่ไดบุตสึแห่งนารา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8AocXQQK5Ls","title":"The Giant Buddha of Todaiji temple praying for the end of the pandemic","thumbnail":"https://i.ytimg.com/vi/8AocXQQK5Ls/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-kinkaku-ji-golden-pavilion',
      'วัดคินคะคุจิ (ศาลาทองคำประกายกระจกเงาแห่งเกียวโต)',
      'Kinkaku-ji: The Golden Pavilion of Kyoto',
      'sacred',
      'เกียวโต',
      'Kyoto',
      'คิตะ',
      'Kita Ward',
      35.0394,
      135.7292,
      'temple_bell',
      'ศาลาไม้สามชั้นที่หุ้มด้วยทองคำเปลวแท้ทั้งสองชั้นบน ตั้งตระหง่านสะท้อนผืนน้ำสงบนิ่งของสระเคียวโคจิ (สระกระจกเงา) สร้างขึ้นในศตวรรษที่ 14 โดยโชกุน อาชิคางะ โยชิมิตสึ เพื่อเป็นคฤหาสน์พักผ่อนก่อนเปลี่ยนเป็นวัดเซนนิกายรินไซ ยอดหลังคาประดับรูปนกฟีนิกซ์ทองคำ สถาปัตยกรรมผสมผสานสามรูปแบบ: ชั้นล่างเป็นสไตล์วังขุนนาง ชั้นสองเป็นสไตล์ซามูไร และชั้นบนสุดเป็นสไตล์วิหารเซน ในปี 1950 ศาลาเคยถูกเผาทำลายโดยพระบวชใหม่ที่คลั่งไคล้ในความงาม ก่อนจะได้รับการสร้างขึ้นใหม่ให้งดงามดั่งเดิม',
      'Officially named Rokuon-ji, the Golden Pavilion (Kinkaku-ji) is a Zen Buddhist temple whose top two floors are completely covered in pure gold leaf. Overlooking the mirror-still Kyoko-chi pond, the pavilion was built in 1397 by Shogun Ashikaga Yoshimitsu. Its three tiers incorporate three distinct architectural styles: palace, samurai, and Zen temple, crowned by a golden bronze phoenix. In 1950, the pavilion was burned to the ground by an obsessed novice monk, inspiring Yukio Mishima''s novel ''The Temple of the Golden Pavilion''.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1994 เป็นหนึ่งในภาพจำทางวัฒนธรรมที่โด่งดังที่สุดของประเทศญี่ปุ่นและสะท้อนปรัชญาความงามยุคคิตายามะ',
      'Rebuilt meticulously in 1955 with thicker gold leaf coating, Kinkaku-ji exemplifies Muromachi period garden design where paradise and earthly architecture harmonize.',
      'ห้ามข้ามรั้วกั้นเพื่อลงไปริมน้ำ หรือโยนเหรียญลงในสระกระจกเงา',
      'Never cross viewing fences or toss coins into the reflective mirror pond.',
      'https://i.ytimg.com/vi/Bjr79RUATl4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Bjr79RUATl4/hqdefault.jpg","title":"วัดคินคะคุจิ (ศาลาทองคำประกายกระจกเงาแห่งเกียวโต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Bjr79RUATl4","title":"A Shogun’s Golden Pavilion, Kinkaku-ji in Kyoto, Japan","thumbnail":"https://i.ytimg.com/vi/Bjr79RUATl4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-kiyomizu-dera-otowa-waterfall',
      'วัดคิโยมิสึเดระ (เวทีไม้วัดน้ำใสและน้ำตกโอโตวะแห่งเกียวโต)',
      'Kiyomizu-dera: The Wooden Stage & Otowa Waterfall',
      'sacred',
      'เกียวโต',
      'Kyoto',
      'ฮิกาชิยามะ',
      'Higashiyama',
      34.9949,
      135.785,
      'water_spirit',
      'วัดเก่าแก่กว่า 1,200 ปีที่สร้างขึ้นบนไหล่เขาโอโตวะ โดดเด่นด้วย ''เวทีคิโยมิสึ'' สูง 13 เมตร ที่สร้างยื่นออกไปเหนือหุบเขาเมเปิล โดยใช้เสาไม้เซลโควาขนาดมหึมาต่อเข้าด้วยกันด้วยลิ่มไม้โบราณโดยไม่ใช้ตะปูแม้แต่ตัวเดียว ที่เชิงผาด้านล่างมี ''น้ำตกโอโตวะ'' ซึ่งน้ำใสบริสุทธิ์ไหลแยกออกเป็นสามสาย ผู้แสวงบุญจะใช้กระบวยด้ามยาวรองดื่มน้ำเพียงสายเดียว: สายที่หนึ่งเพื่อสุขภาพ สายที่สองเพื่อการเรียนการงาน และสายที่สามเพื่อความรัก (หากโลภดื่มทั้งสามสาย พรจะไม่เป็นจริง)',
      'Founded in 778 AD, Kiyomizu-dera (Pure Water Temple) clings to the slopes of Mount Otowa. Its main hall features a legendary wooden veranda built 13 meters above the hillside on colossal keyaki pillars without a single nail. Beneath the main hall flows the Otowa Waterfall, channeling three streams of pure mountain spring water into stone basins. Pilgrims drink from long-poled ladles choosing one stream: longevity, academic success, or romantic fortune; drinking from all three negates the blessing through greed.',
      'สำนวนญี่ปุ่นโบราณกล่าวว่า ''กระโดดจากเวทีคิโยมิสึ'' มีความหมายเทียบเท่ากับการตัดสินใจทำสิ่งที่เด็ดเดี่ยวและกล้าหาญ ปัจจุบันเป็นมรดกโลกยูเนสโกที่มีผู้มาเยือนมากที่สุดในเกียวโต',
      'A UNESCO World Heritage Site, Kiyomizu-dera underwent comprehensive structural restorations completed in 2020, replacing its traditional cypress bark roof shingles.',
      'ห้ามดื่มน้ำตกโอโตวะครบทั้งสามสาย เพราะความโลภจะทำให้คำอธิษฐานล้มเหลว',
      'Never drink from all three streams at Otowa Waterfall; greed voids the sacred blessing.',
      'https://i.ytimg.com/vi/kQmHwWhCXMU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/kQmHwWhCXMU/hqdefault.jpg","title":"วัดคิโยมิสึเดระ (เวทีไม้วัดน้ำใสและน้ำตกโอโตวะแห่งเกียวโต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=kQmHwWhCXMU","title":"Kyoto’s Iconic Pure Water Temple: Inside Kiyomizu-dera | 清水寺 ","thumbnail":"https://i.ytimg.com/vi/kQmHwWhCXMU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-koyasan-okunoin-cemetery',
      'สุสานโอคุโนอินแห่งเขาโคยะ (ที่สถิตของโคโบ ไดชิ ท่ามกลางสนพันปี)',
      'Okunoin Cemetery of Mount Koya: Sanctuary of Kobo Daishi',
      'sacred',
      'วากายามะ',
      'Wakayama',
      'โคยะ',
      'Koya',
      34.2236,
      135.6067,
      'whisper',
      'ศูนย์กลางจิตวิญญาณของพุทธศาสนานิกายชินกอน (วัชรยานญี่ปุ่น) บนยอดเขาโคยะที่ปกคลุมด้วยหมอกหนาทึบ สุสานโอคุโนอินเป็นสุสานที่ใหญ่ที่สุดในญี่ปุ่น มีอนุสาวรีย์หินและสุสานมอสส์โบราณกว่า 200,000 แห่งเรียงรายใต้ร่มเงาของต้นสนซีดาร์ยักษ์อายุกว่า 500 ปี ณ สุสานหลวงด้านในสุด เชื่อกันว่า ''โคโบ ไดชิ'' (คุไก) ไม่ได้มรณภาพ แต่กำลังนั่งสมาธิเข้าฌานลึก (เนียวโจ) รอการมาจุติของพระศรีอริยเมตไตรย พระสงฆ์ยังคงประกอบพิธีถวายภัตตาหารสองมื้อแด่ท่านทุกวันอย่างต่อเนื่องมากว่า 1,200 ปี',
      'Spanning two kilometers through towering ancient cedar groves on Mount Koya, Okunoin is Japan''s largest and most sacred cemetery, holding over 200,000 moss-covered stupas and memorials. At its heart lies the mausoleum of Kobo Daishi (Kukai), founder of Shingon esoteric Buddhism. Believed not to have died in 835 AD but rather entered eternal meditative samadhi (Nyūjō) awaiting the future Buddha Maitreya, temple monks ritually prepare and present two hot ceremonial meals to him every single morning.',
      'ขุนศึกซามูไรชื่อดังในประวัติศาสตร์ญี่ปุ่น เช่น โอดะ โนบุนางะ, โทโยโทมิ ฮิเดโยชิ และทาเคดะ ชินเก็น ล้วนสร้างสุสานหินไว้ในโอคุโนอินเพื่อหวังจะได้อยู่ใกล้ชิดกับโคโบ ไดชิ',
      'Part of the UNESCO World Heritage Sacred Sites and Pilgrimage Routes in the Kii Mountain Range, the lantern-lit pathways evoke profound spiritual transcendence.',
      'ห้ามถ่ายภาพ รับประทานอาหาร หรือส่งเสียงดังข้ามสะพานโกเบียวบาชิเข้าสู่สุสานหลวง',
      'Photography, eating, and drinking are strictly forbidden once crossing the Gobyo-bashi bridge.',
      'https://i.ytimg.com/vi/Y2ZLbz8-tLA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Y2ZLbz8-tLA/hqdefault.jpg","title":"สุสานโอคุโนอินแห่งเขาโคยะ (ที่สถิตของโคโบ ไดชิ ท่ามกลางสนพันปี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Y2ZLbz8-tLA","title":"Japan Travel: Roots of Buddhism, Kobo Daishi''s Feet at the Okunoin Temple in Wakayama 19","thumbnail":"https://i.ytimg.com/vi/Y2ZLbz8-tLA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-haeinsa-tripitaka-koreana',
      'วัดแฮอินซา (หอเก็บพระไตรปิฎกฉบับแผ่นไม้ 80,000 แผ่นแห่งเกาหลี)',
      'Haeinsa Temple & The 80,000 Woodblocks of Tripitaka Koreana',
      'sacred',
      'คย็องซังใต้',
      'South Gyeongsang',
      'ฮับช็อน',
      'Hapcheon',
      35.8014,
      128.0983,
      'temple_bell',
      'วัดพุทธโบราณที่สร้างขึ้นในปี 802 บนเทือกเขากายาซาน เป็นที่เก็บรักษา ''พัลมัน แทจังคย็อง'' หรือพระไตรปิฎกฉบับแผ่นไม้ที่สมบูรณ์และถูกต้องที่สุดในโลก จำนวน 81,258 แผ่น สลักด้วยอักษรจีนโบราณกว่า 52 ล้านตัวอักษรอย่างประณีตโดยไม่มีคำผิดแม้แต่ตัวเดียว สร้างขึ้นในศตวรรษที่ 13 เพื่อขอพุทธานุภาพคุ้มครองเกาหลีจากการรุกรานของกองทัพมองโกล หอเก็บจังกย็องพันจอนสร้างขึ้นด้วยระบบการระบายอากาศและควบคุมความชื้นตามธรรมชาติอันชาญฉลาด ทำให้แผ่นไม้ไม่เคยผุกร่อนหรือถูกปลวกแมลงกัดกินมานานกว่า 700 ปี',
      'Tucked inside Mount Gayasan National Park, Haeinsa is one of Korea''s Three Jewel Temples, representing the Buddha''s Dharma. It houses the Tripitaka Koreana, the world''s most comprehensive and oldest intact canon of Buddhist scriptures carved onto 81,258 birchwood printing blocks between 1236 and 1251 to invoke divine protection against Mongol invaders. The 15th-century Janggyeong Panjeon storage depositories utilize ingenious natural ventilation grilles and clay-charcoal subflooring that preserved the woodblocks without warping.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1995 และแผ่นไม้พระไตรปิฎกได้รับการขึ้นทะเบียนเป็นมรดกความทรงจำแห่งโลก (Memory of the World)',
      'A UNESCO World Heritage Site, Haeinsa remains an active center of Seon (Zen) monastic practice, celebrated as a triumph of medieval scientific preservation.',
      'ห้ามสัมผัสหรือส่องไฟฉายความร้อนสูงใส่แผ่นไม้พระไตรปิฎกโบราณ',
      'Never attempt to reach through the wooden window grilles or touch the printing blocks.',
      'https://i.ytimg.com/vi/V3cXFdaxdb4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/V3cXFdaxdb4/hqdefault.jpg","title":"วัดแฮอินซา (หอเก็บพระไตรปิฎกฉบับแผ่นไม้ 80,000 แผ่นแห่งเกาหลี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=V3cXFdaxdb4","title":"Haeinsa Temple Janggyeong Panjeon, the Depositories for  ... (UNESCO/NHK)","thumbnail":"https://i.ytimg.com/vi/V3cXFdaxdb4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-temple-of-heaven-beijing',
      'หอสวดมนต์เพื่อความอุดมสมบูรณ์ เทียนถาน (แท่นบูชาฟ้าแห่งปักกิ่ง)',
      'The Temple of Heaven: Imperial Sacrificial Altar of Beijing',
      'sacred',
      'ปักกิ่ง',
      'Beijing',
      'ตงเฉิง',
      'Dongcheng',
      39.8822,
      116.4074,
      'temple_bell',
      'หมู่อาคารบูชาฟ้าดินของจักรพรรดิราชวงศ์หมิงและชิง สร้างขึ้นในปี 1420 โดดเด่นด้วย ''หอสวดมนต์เพื่อความอุดมสมบูรณ์'' (ฉีเหนียนเตี้ยน) อาคารไม้ทรงกลมสามชั้นหลังคามุงกระเบื้องเคลือบสีน้ำเงินเข้ม สื่อถึงสวรรค์ สร้างขึ้นโดยไม่ใช้ตะปูแม้แต่ตัวเดียว จักรพรรดิในฐานะ ''โอรสแห่งสวรรค์'' จะเสด็จมาประกอบพิธีบวงสรวงในวันเหมายันทุกปี ลานหินกลมหยวนซิวถันมีแผ่นหินศูนย์กลางสวรรค์ที่เมื่อยืนตะโกน เสียงสะท้อนจะดังก้องกลับมาเก้าเท่า และกำแพงสะท้อนเสียงที่สามารถส่งผ่านเสียงกระซิบข้ามฟากได้',
      'Constructed in 1420 during the reign of the Yongle Emperor, the Temple of Heaven (Tiantan) was the supreme ritual complex where the Ming and Qing Emperors—revered as the Sons of Heaven—fasted and offered sacrifices for good harvests on the winter solstice. The magnificent Hall of Prayer for Good Harvests is a three-tiered circular building with deep cobalt blue glazed tiles, representing heaven, built without nails. The Circular Mound Altar features the Heart of Heaven stone, amplifying whispers into ninefold acoustic echoes.',
      'เทียนถานได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1998 ในฐานะผลงานชิ้นเอกของสถาปัตยกรรมและการวางผังภูมิทัศน์ที่สะท้อนปรัชญาจักรวาลวิทยาจีนโบราณอย่างสมบูรณ์แบบ',
      'Spanning 2.7 square kilometers (larger than the Forbidden City), the Temple of Heaven grounds blend sacred imperial geomancy with verdant ancient cypress parks.',
      'ห้ามปีนป่ายขึ้นไปบนระเบียงหินอ่อนชั้นบนสุดของหอฉีเหนียนเตี้ยน',
      'Never climb over decorative marble railings around the Hall of Prayer.',
      'https://i.ytimg.com/vi/wBsxCNuwurs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/wBsxCNuwurs/hqdefault.jpg","title":"หอสวดมนต์เพื่อความอุดมสมบูรณ์ เทียนถาน (แท่นบูชาฟ้าแห่งปักกิ่ง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=wBsxCNuwurs","title":"Temple of Heaven | Timeless Ancient Structures | CGTN Documentary","thumbnail":"https://i.ytimg.com/vi/wBsxCNuwurs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-potala-palace-lhasa-tibet',
      'พระราชวังโปตาลา (พระราชวังฤดูหนาวบนหลังคาโลกแห่งลาซา)',
      'The Potala Palace: Winter Residence of the Dalai Lamas (Lhasa)',
      'sacred',
      'ทิเบต',
      'Tibet Autonomous Region',
      'ลาซา',
      'Lhasa',
      29.6556,
      91.1172,
      'temple_bell',
      'พระราชวังป้อมปราการบนยอดเขาแดง (มาโปรี) สูงกว่า 3,700 เมตรเหนือระดับน้ำทะเล สร้างขึ้นในศตวรรษที่ 17 โดยดาไลลามะองค์ที่ 5 ตัวอาคารแบ่งออกเป็นสองส่วน: ''วังขาว'' ซึ่งเป็นศูนย์กลางการปกครองและกุฏิที่ประทับ และ ''วังแดง'' ซึ่งเป็นศูนย์กลางศาสนาและที่ประดิษฐานสถูปทองคำบรรจุพระศพของอดีตดาไลลามะแปดพระองค์ สถูปของดาไลลามะองค์ที่ 5 หุ้มด้วยทองคำแท้หนักกว่า 3.7 ตัน ประดับด้วยเพชร พลอย และไข่มุกนับหมื่นเม็ด ถือเป็นมงกุฎแห่งจิตวิญญาณของชาวทิเบต',
      'Perched dramatically upon Moburi (Red Mountain) at 3,700 meters above sea level, the Potala Palace was the winter palace of the Dalai Lamas from 1649 until 1959. Soaring 13 stories with over 1,000 rooms, its massive stone walls taper upwards toward the clouds. The White Palace housed administrative halls and papal quarters, while the central Red Palace contains sacred Buddhist shrines and the stupa tombs of eight Dalai Lamas, encrusted with over 3.7 tons of pure gold, turquoise, coral, and diamonds.',
      'พระราชวังโปตาลาได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1994 และถือเป็นหนึ่งในสิ่งมหัศจรรย์ทางสถาปัตยกรรมภูเขาที่ยิ่งใหญ่ที่สุดของมนุษยชาติ',
      'Surviving the turbulent 20th century, the Potala Palace is revered as the terrestrial palace of Avalokiteshvara, drawing pilgrims who circumambulate its perimeter daily.',
      'ห้ามถ่ายภาพภายในพระวิหารศักดิ์สิทธิ์และห้องบรรจุพระสถูปทองคำเด็ดขาด',
      'Photography is strictly forbidden inside all inner chapels and golden tomb stupa halls.',
      'https://i.ytimg.com/vi/baK3X5Oozh4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/baK3X5Oozh4/hqdefault.jpg","title":"พระราชวังโปตาลา (พระราชวังฤดูหนาวบนหลังคาโลกแห่งลาซา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=baK3X5Oozh4","title":"See Potala Palace, the Iconic Heart of Tibetan Buddhism | National Geographic","thumbnail":"https://i.ytimg.com/vi/baK3X5Oozh4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-jokhang-temple-barkhor-lhasa',
      'วัดโจคัง (วิหารพระพุทธรูปโจโวรินโปเชและถนนบาร์กอร์แห่งลาซา)',
      'Jokhang Temple: The Sacred Spiritual Heart of Tibet (Lhasa)',
      'sacred',
      'ทิเบต',
      'Tibet Autonomous Region',
      'ลาซา',
      'Lhasa',
      29.6531,
      91.1314,
      'temple_bell',
      'วิหารพุทธศาสนาที่ศักดิ์สิทธิ์และเก่าแก่ที่สุดในทิเบต สร้างขึ้นในปี ค.ศ. 647 โดยกษัตริย์ซงเซน กัมโป เพื่อประดิษฐาน ''โจโว ศากยมุนี'' (โจโวรินโปเช) พระพุทธรูปทองคำแท้ขนาดเท่าพระองค์จริงเมื่อมีพระชนมายุ 12 พรรษา ซึ่งเจ้าหญิงเหวินเฉิงอัญเชิญมาจากราชวงศ์ถัง ผู้แสวงบุญชาวทิเบตจากทั่วทุกสารทิศจะเดินทางเท้าหลายพันกิโลเมตรเพื่อมากราบอัษฎางคประดิษฐ์ซ้ำแล้วซ้ำเล่าจนพื้นหินหน้าวัดสึกกร่อนเป็นรอยลึก ล้อมรอบด้วยถนนบาร์กอร์ที่มีผู้คนเดินประทักษิณหมุนกงล้อมนตราตลอดเวลา',
      'Founded in 647 AD by King Songtsen Gampo, the Jokhang Temple is considered the supreme spiritual heart of Tibet. It enshrines the Jowo Shakyamuni, a revered life-sized statue of the 12-year-old Buddha blessed by the Buddha himself and brought to Tibet by Chinese Princess Wencheng. The flagstones before the main entrance are worn smooth and polished by the bodies of hundreds of thousands of pilgrims performing whole-body prostrations in prayer beneath clouds of burning juniper.',
      'วัดโจคังและถนนบาร์กอร์ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 2000 ในฐานะส่วนต่อขยายของหมู่โบราณสถานพระราชวังโปตาลา',
      'Surrounded by the bustling Barkhor kora circumambulation circuit, Jokhang represents the living pulse of Tibetan Buddhism, filled with the aroma of yak-butter lamps.',
      'ต้องเดินเวียนขวารอบวิหารและถนนบาร์กอร์ตามทิศเข็มนาฬิกาเท่านั้น',
      'Always walk clockwise when circumambulating inside the temple and along the Barkhor circuit.',
      'https://i.ytimg.com/vi/-ccSBwCUcmo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-ccSBwCUcmo/hqdefault.jpg","title":"วัดโจคัง (วิหารพระพุทธรูปโจโวรินโปเชและถนนบาร์กอร์แห่งลาซา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-ccSBwCUcmo","title":"#184. Jowo Rinpoche, enshrined in the Jokhang Temple (AP Art History)","thumbnail":"https://i.ytimg.com/vi/-ccSBwCUcmo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-prambanan-trimurti-temple',
      'ปรัมบานัน (มหาเทวาลัยตรีมูรติและตำนานความรักลอร่าจงกรังแห่งชวา)',
      'Prambanan Temple: The Grand Trimurti Shrines of Java',
      'sacred',
      'ยอกยาการ์ตา',
      'Special Region of Yogyakarta',
      'สเลมัน',
      'Sleman',
      -7.752,
      110.4914,
      'temple_bell',
      'หมู่อาคารเทวาลัยฮินดูที่ใหญ่ที่สุดในอินโดนีเซีย สร้างขึ้นในศตวรรษที่ 9 โดยราชวงศ์สันชยะ โดดเด่นด้วยวิหารทรงศิขระยอดแหลมสูงเสียดฟ้า 47 เมตร ถวายแด่พระศิวะ พระวิษณุ และพระพรหม (ตรีมูรติ) ผนังหินแกะสลักเรื่องรามเกียรติ์อย่างวิจิตร ตามตำนานพื้นบ้านเล่าถึง เจ้าหญิงลอร่า จงกรัง ผู้ขอให้เจ้าชายสร้างวิหารพันหลังในคืนเดียวเพื่อแลกกับการแต่งงาน ทว่าเจ้าหญิงแกล้งตำข้าวให้ไก่ขันก่อนเวลา เจ้าชายโกรธจัดจึงสาปให้นางกลายเป็นหินเป็นเทวรูปองค์ที่หนึ่งพันในวิหาร',
      'Constructed in 850 AD by the Sanjaya Dynasty, Prambanan is the largest Hindu temple compound in Indonesia, characterized by its towering, pointed Hindu architecture. The central spire of the Shiva temple soars 47 meters above the Yogyakarta plains, adorned with intricate narrative bas-reliefs illustrating the Ramayana epic. Javanese folklore links the ruins to the myth of Roro Jonggrang: tricked by the princess while attempting to build a thousand temples overnight, Prince Bandung cursed her into stone as the final statue.',
      'ปรัมบานันได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1991 รอดพ้นจากแผ่นดินไหวใหญ่ในชวาปี 2006 และยังคงใช้เป็นสถานที่จัดการแสดงนาฏศิลป์รามายณะกลางแจ้ง',
      'A masterpiece of Hindu art, Prambanan stands as a magnificent testament to ancient Java''s religious tolerance alongside nearby Buddhist Borobudur.',
      'ห้ามปีนป่ายขึ้นไปบนซากปรักหักพังของวิหารเปร์วาราที่กำลังรอการบูรณะ',
      'Never climb on un-restored stone blocks of the outer perwara temples.',
      'https://i.ytimg.com/vi/XAn6jZQhzic/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XAn6jZQhzic/hqdefault.jpg","title":"ปรัมบานัน (มหาเทวาลัยตรีมูรติและตำนานความรักลอร่าจงกรังแห่งชวา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XAn6jZQhzic","title":"THE SECRET OF PRAMBANAN TEMPLE #acrossindonesia #indonesia #indonesiaculture #indonesiaheritage","thumbnail":"https://i.ytimg.com/vi/XAn6jZQhzic/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-nemrut-hierotheseion',
      'ภูเขาเนมรุต (สุสานศีรษะเทพเจ้าหินยักษ์แห่งกษัตริย์อันทิโอคัส)',
      'Mount Nemrut: The Colossal Stone Heads of the Gods (Turkey)',
      'sacred',
      'อาดียามัน',
      'Adiyaman',
      'คาห์ตา',
      'Kahta',
      37.9808,
      38.7408,
      'creepy_wind',
      'สุสานหลวงและอนุสรณ์สถานบนยอดเขาเนมรุต สูง 2,134 เมตรเหนือระดับน้ำทะเล สร้างขึ้นในศตวรรษที่ 1 ก่อนคริสตกาล โดยกษัตริย์อันทิโอคัสที่ 1 แห่งอาณาจักรคอมมาเกเน บนลานหินทิศตะวันออกและทิศตะวันตก มีรูปปั้นหินขนาดยักษ์สูง 8-9 เมตรของกษัตริย์อันทิโอคัสประทับเคียงข้างเหล่าทวยเทพผสมผสานกรีก-เปอร์เซีย เช่น ซูส-โอฮูร์มัซด์ อพอลโล-มิธรา และเฮอร์คิวลิส-วาฮาห์น ทว่าแผ่นดินไหวในอดีตทำให้เศียรหินขนาดยักษ์หลุดตกลงมาตั้งเรียงรายอยู่บนพื้นดินอย่างน่าเกรงขาม',
      'Crowning a 2,134-meter peak in southeastern Turkey, Mount Nemrut is the monumental hierotheseion (sanctuary-tomb) of King Antiochus I Theos of Commagene (69–34 BC). Flanking a 50-meter artificial gravel tumulus are terraces of colossal seated statues depicting Antiochus seated alongside syncretic Greek-Persian deities—Zeus-Oromasdes, Apollo-Mithras, and Heracles-Artagnes. Centuries of earthquakes toppled the massive stone heads, leaving them resting mysteriously on the alpine plateau.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1987 เป็นที่รู้จักในฐานะจุดชมพระอาทิตย์ขึ้นและพระอาทิตย์ตกที่งดงามและเปี่ยมมนต์ขลังที่สุดแห่งหนึ่งของโลก',
      'Described as the ''Throne of the Gods'', Mount Nemrut represents a fascinating cultural bridge between Hellenistic and Persian astrological religions.',
      'ห้ามปีนป่ายขึ้นไปบนกองหินสุสานทูมูลัส หรือสัมผัสศีรษะหินโบราณ',
      'Never attempt to walk on the gravel burial tumulus or touch the fallen monumental stone heads.',
      'https://i.ytimg.com/vi/YPfU9iuzZeU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/YPfU9iuzZeU/hqdefault.jpg","title":"ภูเขาเนมรุต (สุสานศีรษะเทพเจ้าหินยักษ์แห่งกษัตริย์อันทิโอคัส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=YPfU9iuzZeU","title":"The King Who Built a Mountain to Become a God | Mount Nemrut, Turkey","thumbnail":"https://i.ytimg.com/vi/YPfU9iuzZeU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-lake-guatavita-el-dorado-gold',
      'ทะเลสาบกัวตาวิตาและต้นกำเนิดเอลโดราโด (นครทองคำแห่งโคลอมเบีย)',
      'Lake Guatavita & The Gilded Chieftain of El Dorado',
      'legend',
      'กุนดินามาร์กา',
      'Cundinamarca',
      'กัวตาวิตา',
      'Guatavita',
      4.9781,
      -73.7744,
      'water_spirit',
      'ทะเลสาบปล่องภูเขาไฟทรงกลมเกลี้ยงบนเทือกเขาแอนดีส ประเทศโคลอมเบีย ต้นกำเนิดที่แท้จริงของมหากาพย์ ''เอล โดราโด'' (El Dorado หรือ มนุษย์ทองคำ) ชนเผ่ามุยสกาโบราณมีพิธีกรรมสถาปนากษัตริย์องค์ใหม่ โดยทาผิวกายของกษัตริย์ด้วยน้ำมันพืชและผงทองคำบริสุทธิ์จนเหลืองอร่ามทั้งตัว พระองค์จะทรงแพลอยออกไปกลางทะเลสาบและกระโดดลงไปชำระล้างผงทองคำออก พร้อมทั้งทิ้งทองคำ มรกต และรูปปั้นทองคำนับไม่ถ้วนลงสู่ก้นบึ้งเพื่อเป็นเครื่องบรรณาการแด่เทพธิดาแห่งสายน้ำ',
      'High in the Andes of Colombia lies the circular crater lake of Guatavita, the historical birthplace of the El Dorado legend. In ancient Muisca coronation rituals, the new zipa (chieftain) was coated head-to-toe in sticky balsam sap and dusted with glittering gold powder, transforming him into ''El Dorado'' (The Gilded One). Floating on a ceremonial raft to the center of the sacred lake, he dove into the depths to wash away the gold, while priests cast hundreds of gold figurines and emeralds into the water.',
      'แพทองคำมุยสกา (Muisca Raft) อันวิจิตรตระการตาที่พบใกล้ทะเลสาบ ปัจจุบันจัดแสดงอยู่ที่พิพิธภัณฑ์ทองคำ (Museo del Oro) ในกรุงโบโกตา เป็นหลักฐานยืนยันพิธีกรรมโบราณนี้',
      'Centuries of Spanish conquistadors attempted to drain Lake Guatavita to loot its legendary gold hoard. The lake is now protected as a sacred ecological and indigenous sanctuary.',
      'ห้ามลงไปว่ายน้ำ ดำน้ำ หรือขุดค้นดินโคลนริมทะเลสาบกัวตาวิตา',
      'Swimming, diving, and treasure excavation are strictly prohibited in the sacred lake waters.',
      'https://i.ytimg.com/vi/YMRlNeY0rLs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/YMRlNeY0rLs/hqdefault.jpg","title":"ทะเลสาบกัวตาวิตาและต้นกำเนิดเอลโดราโด (นครทองคำแห่งโคลอมเบีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=YMRlNeY0rLs","title":"The Legend of El Dorado - Lake Guatavita Colombia","thumbnail":"https://i.ytimg.com/vi/YMRlNeY0rLs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-yonaguni-monument-submerged-ruins',
      'อนุสาวรีย์ใต้สมุทรโยนากูนิ (ซากนครแอตแลนติสแห่งญี่ปุ่น)',
      'The Yonaguni Submerged Megalithic Terraces (Okinawa)',
      'legend',
      'โอกินาวะ',
      'Okinawa',
      'โยนากูนิ',
      'Yonaguni',
      24.4331,
      123.0111,
      'water_spirit',
      'โครงสร้างหินขนาดยักษ์ใต้ท้องทะเลลึก 25 เมตร นอกชายฝั่งเกาะโยนากูนิ จุดใต้สุดของญี่ปุ่น ค้นพบโดยนักดำน้ำ คิฮาจิโร อาราตาเกะ ในปี 1986 มีลักษณะเป็นขั้นบันไดหินตัดตรง มุมฉาก 90 องศา เสาหินคู่ และลานกว้างคล้ายปิรามิดขั้นบันไดโบราณ หรือวิหารของทวีปมู (Mu) ที่จมหายไปในมหาสมุทรแปซิฟิกเมื่อสิ้นสุดยุคน้ำแข็งเมื่อกว่า 10,000 ปีก่อน นักธรณีวิทยาบางท่านเชื่อว่าเป็นปรากฏการณ์ธรรมชาติจากการแตกตัวของหินทราย แต่รอยเจาะและภาพสลักหินยังคงเป็นปริศนา',
      'Discovered in 1986 by dive tour operator Kihachiro Aratake off the southern coast of Yonaguni Island, this colossal submerged rock formation rests 25 meters underwater. Known as the Yonaguni Monument, it features massive step terraces, sheer right-angle flat faces, and carved gutters resembling an ancient step pyramid or lost Pacific civilization like Mu. While marine geologists debate whether tectonic fracturing created the terracing, researchers note tool marks and carving remnants.',
      'ศ. มาซาอากิ คิมูระ นักธรณีวิทยาทางทะเลแห่งมหาวิทยาลัยริวกิว ยืนยันว่าโครงสร้างนี้สร้างโดยฝีมือมนุษย์โบราณในยุคที่ระดับน้ำทะเลยังต่ำกว่าปัจจุบัน',
      'Featured in Graham Hancock''s documentaries, the Yonaguni submarine formation remains one of the world''s most polarizing and thrilling underwater archaeological enigmas.',
      'ห้ามดำน้ำคนเดียว หรือสัมผัสขูดขีดเนื้อหินใต้ทะเลโยนากูนิ',
      'Never dive without licensed local guides due to fierce Pacific currents around the monolith.',
      'https://i.ytimg.com/vi/jYBJnX9AHOg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jYBJnX9AHOg/hqdefault.jpg","title":"อนุสาวรีย์ใต้สมุทรโยนากูนิ (ซากนครแอตแลนติสแห่งญี่ปุ่น)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jYBJnX9AHOg","title":"Yonaguni Monument - Japan''s Lost Atlantis","thumbnail":"https://i.ytimg.com/vi/jYBJnX9AHOg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-crystal-skull-mitchell-hedges',
      'กะโหลกแก้วคริสตัลแห่งมิตเชลล์-เฮดเจส (โบราณวัตถุเหนือโลกแห่งเบลีซ)',
      'The Mitchell-Hedges Crystal Skull of Lubaantun (Belize)',
      'legend',
      'โตเลโด',
      'Toledo District',
      'ปุนตากอร์ดา',
      'Lubaantun',
      16.2828,
      -88.9567,
      'whisper',
      'กะโหลกมนุษย์ที่แกะสลักจากหินควอตซ์คริสตัลใสบริสุทธิ์ชิ้นเดียวอย่างประณีต มีขากรรไกรล่างที่สามารถขยับถอดได้ แอนนา มิตเชลล์-เฮดเจส อ้างว่าเธอค้นพบกะโหลกนี้ในปี 1924 ใต้แท่นบูชาของนครมายาโบราณลูบาอันตุน ประเทศเบลีซ ตามตำนานเล่าว่ามีกะโหลกคริสตัลโบราณ 13 หัวกระจัดกระจายอยู่ทั่วโลก และหากนำมารวมกันในวันสิ้นสุดปฏิทินมายา จะสามารถปลดล็อกความรู้ขั้นสูงของสิ่งมีชีวิตต่างดาวและจักรวาล ผู้ที่อยู่ใกล้กะโหลกมักอ้างว่าได้ยินเสียงดนตรีแว่วและเห็นภาพนิมิตในผลึกแก้ว',
      'Discovered allegedly in 1924 beneath a fallen altar at the Maya ruins of Lubaantun by adventurer F.A. Mitchell-Hedges'' daughter Anna, the ''Skull of Doom'' is sculpted from a single block of clear quartz crystal, featuring a detachable articulated lower jaw. Believed in New Age mythology to be one of thirteen ancient crystal skulls containing accumulated galactic knowledge from extraterrestrial civilizations, laboratory testing by Hewlett-Packard showed prisms and optical light tunnels cut against the natural quartz axis.',
      'แม้การตรวจสอบทางอิเล็กตรอนไมโครสโคปของสถาบันสมิธโซเนียนจะชี้ว่าอาจมีการใช้เครื่องมือขัดยุคศตวรรษที่ 19 แต่กะโหลกนี้ได้กลายเป็นแรงบันดาลใจหลักของภาพยนตร์ Indiana Jones and the Kingdom of the Crystal Skull',
      'The Mitchell-Hedges skull cemented itself into modern pop culture folklore, inspiring Hollywood adventures and ongoing esoteric crystal healing traditions.',
      'ห้ามขุดค้นหรือเคลื่อนย้ายก้อนหินโบราณในนครมายาลูบาอันตุน',
      'Never disturb unexcavated stone mounds at the Lubaantun archaeological reserve.',
      'https://i.ytimg.com/vi/CgczRKNTnOg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CgczRKNTnOg/hqdefault.jpg","title":"กะโหลกแก้วคริสตัลแห่งมิตเชลล์-เฮดเจส (โบราณวัตถุเหนือโลกแห่งเบลีซ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CgczRKNTnOg","title":"The Legend Of The Ancient Crystal Skulls | Myth Hunters","thumbnail":"https://i.ytimg.com/vi/CgczRKNTnOg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-lady-godiva-coventry-procession',
      'เลดี้โกไดวา (ตำนานสตรีเปลือยกายขี่ม้าเพื่อชาวเมืองโคเวนทรี)',
      'Lady Godiva''s Naked Ride of Compassion (Coventry)',
      'legend',
      'เวสต์มิดแลนดส์',
      'West Midlands',
      'โคเวนทรี',
      'Coventry',
      52.4081,
      -1.5106,
      'creepy_wind',
      'ตำนานอังกฤษในศตวรรษที่ 11 เลดี้โกไดวา สตรีขุนนางผู้เปี่ยมเมตตา ได้ขอร้องให้ ลีโอฟริก เอิร์ลแห่งเมอร์เซีย ผู้เป็นสามี ยกเลิกการเก็บภาษีขูดรีดที่กดขี่ชาวเมืองโคเวนทรีจนยากแค้น เอิร์ลลีโอฟริกจึงเอ่ยปากท้าทายว่า ''ข้าจะยกเลิกภาษีให้ หากเจ้ากล้าเปลือยกายขี่ม้าผ่านตลาดโคเวนทรี'' เลดี้โกไดวายอมเสียสละเกียรติยศ เธอสยายผมสีทองยาวสลวยเพื่อปกปิดร่างกาย และขี่ม้าผ่านเมืองที่ชาวบ้านพร้อมใจกันปิดประตูหน้าต่างไม่ยอมมองเพื่อแสดงความเคารพ',
      'According to 11th-century Anglo-Saxon legend, Lady Godiva pleaded with her husband, Leofric, Earl of Mercia, to relieve the citizens of Coventry of crushing, oppressive taxes. Exasperated, Leofric mockingly swore he would waive the taxes only if she rode naked through the public marketplace. Covered only by her long flowing golden hair, Godiva accepted the wager. Citizens stayed indoors with shuttered windows in grateful deference, save for tailor ''Peeping Tom'', who peeked and was struck blind.',
      'รูปปั้นบรอนซ์ของเลดี้โกไดวาขี่ม้าตั้งตระหง่านอยู่ใจกลางเมืองโคเวนทรี และเรื่องราวของช่างตัดเสื้อผู้แอบมองได้กลายเป็นที่มาของสำนวนภาษาอังกฤษคำว่า ''Peeping Tom''',
      'Chronicled by medieval monks like Roger of Wendover, Lady Godiva remains a beloved historic symbol of self-sacrifice, civic courage, and English regional folklore.',
      'ห้ามแอบมองผ่านช่องหน้าต่างขณะขบวนรำลึกเลดี้โกไดวาเคลื่อนผ่าน',
      'Never act as a ''Peeping Tom'' or disrespect the historic equestrian memorial in Broadgate.',
      'https://i.ytimg.com/vi/WHOhaK5gNYE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/WHOhaK5gNYE/hqdefault.jpg","title":"เลดี้โกไดวา (ตำนานสตรีเปลือยกายขี่ม้าเพื่อชาวเมืองโคเวนทรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=WHOhaK5gNYE","title":"Horrible Histories: Lady Godiva | Coventry UK City of Culture 2021","thumbnail":"https://i.ytimg.com/vi/WHOhaK5gNYE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-iron-pillar-of-delhi-rustless',
      'เสาเหล็กกล้าแห่งเดลี (โลหะวิทยาไร้สนิม 1,600 ปีแห่งอินเดีย)',
      'The Rustless Iron Pillar of Delhi (Qutb Complex)',
      'legend',
      'เดลี',
      'Delhi',
      'นิวเดลี',
      'New Delhi',
      28.5247,
      77.185,
      'temple_bell',
      'เสาเหล็กดัดโบราณสูง 7.2 เมตร หนักกว่า 6 ตัน ตั้งตระหง่านอยู่กลางลานมัสยิดกูววัต-อุล-อิสลาม ในหมู่อาคารกุตุบมินาร์ สร้างขึ้นในศตวรรษที่ 4 ในรัชสมัยพระเจ้าจันทรคุปต์ที่ 2 แห่งราชวงศ์คุปตะ สิ่งที่เป็นปริศนาทางวิทยาศาสตร์คือ แม้จะตั้งอยู่กลางแจ้งตากแดดตากฝนในสภาพอากาศร้อนชื้นของอินเดียมานานกว่า 1,600 ปี แต่เสาเหล็กนี้กลับ ''ไม่เคยขึ้นสนิม'' เลยแม้แต่น้อย นักโลหะวิทยาค้นพบว่าช่างอินเดียโบราณใช้เทคนิคฟอสฟอรัสสูงจนเกิดชั้นฟิล์มปกป้องผิวเหล็กอย่างน่าอัศจรรย์',
      'Standing 7.2 meters tall and weighing six tons inside the Qutb Minar complex, the Iron Pillar of Delhi was erected during the reign of Chandragupta II in the 4th century AD. The metallurgical marvel has withstood 1,600 years of extreme monsoon rain and scorching desert heat without suffering corrosion or rust. Modern scientists at IIT Kanpur discovered that ancient Indian blacksmiths created a protective passive layer of iron hydrogen phosphate hydrate (misawite) through high phosphorus content.',
      'มีความเชื่อดั้งเดิมว่า หากใครสามารถยืนหันหลังชนเสาและโอบแขนไปด้านหลังจนปลายนิ้วประสานกันรอบเสาได้ จะสมหวังในความปรารถนาและโชคดี (ปัจจุบันทางการได้สร้างรั้วล้อมเพื่อป้องกันเหงื่อกัดกร่อน)',
      'A UNESCO World Heritage Site, the Iron Pillar stands as undeniable physical evidence of advanced metallurgy in ancient Gupta India long before modern steel manufacturing.',
      'ห้ามปีนข้ามรั้วป้องกันเพื่อไปโอบกอดเสาเหล็กโบราณ',
      'Never climb over the protective security fence to wrap your arms around the iron pillar.',
      'https://i.ytimg.com/vi/QaEIemP-eA4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/QaEIemP-eA4/hqdefault.jpg","title":"เสาเหล็กกล้าแห่งเดลี (โลหะวิทยาไร้สนิม 1,600 ปีแห่งอินเดีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=QaEIemP-eA4","title":"The Iron Pillar of Delhi — India’s 1,600-Year-Old Mystery","thumbnail":"https://i.ytimg.com/vi/QaEIemP-eA4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-baghdad-battery-parthian-cell',
      'แบตเตอรี่แห่งแบกแดด (เซลล์ไฟฟ้ากัลวานิก 2,000 ปีแห่งเมโสโปเตเมีย)',
      'The Baghdad Battery: Ancient 2,000-Year-Old Galvanic Cells',
      'legend',
      'แบกแดด',
      'Baghdad Governorate',
      'แบกแดด',
      'Baghdad',
      33.3152,
      44.3661,
      'whisper',
      'ขวดโหลเครื่องปั้นดินเผาสีเหลืองสูง 14 เซนติเมตร ขุดพบที่เมืองคุจุต ราบู ใกล้กรุงแบกแดด ในปี 1936 มีอายุย้อนไปในยุคพาเธียนหรือซาสซาเนียน ภายในบรรจุท่อทองแดงม้วนทรงกระบอกและแกนเหล็กตรงกลาง ยึดด้วยยางมะตอย (บิทูเมน) นักโบราณคดีชาวเยอรมัน วิลเฮล์ม โคนิก เสนอทฤษฎีสะเทือนโลกว่า วัตถุนี้คือ ''แบตเตอรี่ไฟฟ้าโบราณ'' ที่เมื่อเติมน้ำส้มสายชูหรือน้ำองุ่นหมักลงไป จะสามารถผลิตกระแสไฟฟ้าได้ประมาณ 1.5 - 2 โวลต์ เพื่อใช้ในการชุบเคลือบโลหะทองคำหรือบำบัดความเจ็บปวด',
      'Discovered in 1936 at Khujut Rabu near Baghdad, this 5.5-inch terracotta jar contains a rolled sheet of copper housing an iron rod suspended in the center, sealed with asphalt bitumen. German archaeologist Wilhelm König recognized it as an ancient galvanic cell dating back to the Parthian or Sasanian Empire (circa 250 BC–225 AD). When filled with an acidic electrolyte like vinegar or wine, replicas successfully generate 1.1 to 2.0 volts of electric current, debated as tools for gold electroplating or religious temple shocks.',
      'การทดลองในรายการ MythBusters ยืนยันว่าขวดโหลเหล่านี้สามารถผลิตกระแสไฟฟ้าได้จริง โบราณวัตถุชิ้นเอกนี้เคยจัดแสดงที่พิพิธภัณฑ์แห่งชาติอิรักก่อนจะสูญหายไประหว่างสงครามอิรักปี 2003',
      'A cornerstone of out-of-place artifact (OOPArt) discussions, the Baghdad Battery continues to challenge historical timelines of technological and electrical discovery.',
      'ห้ามขโมยหรือค้าขายโบราณวัตถุที่ถูกปล้นสะดมจากแหล่งขุดค้นเมโสโปเตเมีย',
      'Never traffic in illicit antiquities plundered from ancient Mesopotamian sites.',
      'https://i.ytimg.com/vi/XcFOOfqfx3s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XcFOOfqfx3s/hqdefault.jpg","title":"แบตเตอรี่แห่งแบกแดด (เซลล์ไฟฟ้ากัลวานิก 2,000 ปีแห่งเมโสโปเตเมีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XcFOOfqfx3s","title":"Legend of BAGHDAD BATTERY, How Batteries Work","thumbnail":"https://i.ytimg.com/vi/XcFOOfqfx3s/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-voynich-manuscript-beinecke',
      'คัมภีร์วอยนิช (รหัสลับไร้คำแปลและพฤกษศาสตร์ต่างมิติ)',
      'The Voynich Manuscript: The World''s Most Mysterious Book',
      'legend',
      'คอนเนตทิคัต',
      'Connecticut',
      'นิวเฮเวน',
      'New Haven',
      41.3114,
      -72.9272,
      'whisper',
      'หนังสือเขียนด้วยลายมือโบราณบนแผ่นหนังลูกวัว (Vellum) จำนวน 240 หน้า คาร์บอนเดตติ้งระบุว่าสร้างขึ้นในช่วงต้นศตวรรษที่ 15 หนังสือทั้งเล่มเขียนด้วยระบบตัวอักษรและภาษาปริศนาที่ไม่ตรงกับภาษาใดในประวัติศาสตร์มนุษยชาติ พร้อมภาพวาดสีน้ำรูปพืชพรรณประหลาดที่ไม่มีอยู่จริงบนโลก แผนภูมิดาราศาสตร์จักรราศีที่ไม่ตรงกับท้องฟ้า และหญิงสาวเปลือยกายกำลังอาบน้ำในระบบท่อเขียวลึกลับ นักถอดรหัสของกองทัพและปัญญาประดิษฐ์ (AI) ชั้นนำทั่วโลกยังคงไม่สามารถถอดรหัสข้อความในเล่มนี้ได้แม้แต่ประโยคเดียว',
      'Housed in Yale University''s Beinecke Rare Book Library (MS 408), the Voynich Manuscript is an illustrated 240-page codex carbon-dated to between 1404 and 1438. Written in an entirely unknown alphabet and language (''Voynichese''), the book features bizarre botanical illustrations of non-existent terrestrial flora, astrological fold-out zodiac charts, and naked nymphs bathing in elaborate pipeworks. The world''s greatest cryptographers—including Alan Turing''s Bletchley Park peers and modern AI—have failed to decipher a single sentence.',
      'ซื้อมาจากวิทยาลัยเยซูอิตในอิตาลีโดยพ่อค้าหนังสือเก่า วิลฟริด วอยนิช ในปี 1912 ข้อสันนิษฐานมีตั้งแต่เป็นคัมภีร์เล่นแร่แปรธาตุลับ ตำรายาโบราณ ไปจนถึงงานเขียนของสิ่งมีชีวิตต่างดาว',
      'Yale digitized the complete codex for global open-access research. The Voynich Manuscript remains humanity''s ultimate unbroken cryptographic riddle.',
      'ห้ามสร้างเอกสารปลอมแปลงเพื่อหลอกลวงว่าถอดรหัสคัมภีร์วอยนิชได้สำเร็จ',
      'Never promote fraudulent hoaxes claiming complete translation without peer-reviewed verification.',
      'https://i.ytimg.com/vi/__CI6-fjbsU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/__CI6-fjbsU/hqdefault.jpg","title":"คัมภีร์วอยนิช (รหัสลับไร้คำแปลและพฤกษศาสตร์ต่างมิติ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=__CI6-fjbsU","title":"Voynich Manuscript Decoded | The Mysterious Book Finally Solved?","thumbnail":"https://i.ytimg.com/vi/__CI6-fjbsU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-shroud-of-turin-holy-relic',
      'ผ้าห่อพระศพแห่งตูริน (รอยประทับพระพักตร์พระคริสต์แห่งอิตาลี)',
      'The Shroud of Turin: The Holy Burial Cloth of Christ',
      'legend',
      'ตูริน',
      'Piedmont',
      'ตูริน',
      'Turin',
      45.0733,
      7.6853,
      'whisper',
      'ผืนผ้าลินินทอมือโบราณขนาดยาว 4.4 เมตร เก็บรักษาไว้ในอาสนวิหารเซนต์จอห์นเดอะแบปทิสต์ เมืองตูริน บนผืนผ้าปรากฏภาพรางๆ ทั้งด้านหน้าและด้านหลังของร่างบุรุษที่มีร่องรอยบาดแผลจากการถูกตรึงกางเขน รอยหนามทิ่มแทงบนศีรษะ และรอยหอกแทงที่สีข้าง ในปี 1898 เซคอนโด ปิอา ถ่ายภาพผืนผ้าและต้องตกตะลึงเมื่อพบว่า ''ฟิล์มเนกาทีฟ'' เผยให้เห็นภาพพระพักตร์ของพระเยซูคริสต์ที่มีมิติสมจริงอย่างน่าอัศจรรย์ ภาพบนผืนผ้าไม่ได้เกิดจากสี วานิช หรือความร้อน แต่เป็นปฏิกิริยาบนเส้นใยลินินระดับนาโนเมตรที่ยังหาคำอธิบายทางฟิสิกส์ไม่ได้',
      'Kept inside the Cathedral of Saint John the Baptist in Turin, the Shroud of Turin is a 14-foot herringbone linen cloth bearing the faint, negative image of a crucified man with puncture wounds on his wrists, scourging marks, and a punctured side. In 1898, photographer Secondo Pia discovered that the photographic negative of the cloth revealed a strikingly lifelike, three-dimensional portrait of Jesus Christ. Scientific examinations confirmed the image is not painted with pigments or dyes, residing only on the outermost nanometer-thin surface of the flax fibrils.',
      'แม้การตรวจคาร์บอน-14 ในปี 1988 จะระบุอายุผ้าอยู่ในช่วงยุคกลาง แต่นักวิจัยรุ่นหลังโต้แย้งเรื่องการปนเปื้อนของเนื้อผ้าซ่อมแซมและคราบควันไฟ ทำให้ผ้าห่อพระศพแห่งตูรินยังคงเป็นโบราณวัตถุที่ถูกศึกษาวิจัยทางวิทยาศาสตร์มากที่สุดในประวัติศาสตร์โลก',
      'Regarded with profound devotion by millions of Christians, the Holy Shroud is exhibited only during rare papal ostensions, guarded behind blast-proof, climate-controlled helium cases.',
      'ห้ามนำไฟหรือความร้อนเข้าใกล้ตู้กระจกนิรภัยเก็บรักษาผ้าห่อพระศพ',
      'Strict fire and environmental protocols are enforced around the sacred reliquary.',
      'https://i.ytimg.com/vi/Nj5IK_nU4hs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Nj5IK_nU4hs/hqdefault.jpg","title":"ผ้าห่อพระศพแห่งตูริน (รอยประทับพระพักตร์พระคริสต์แห่งอิตาลี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Nj5IK_nU4hs","title":"The Shroud of Turin: History’s Most Controversial Relic","thumbnail":"https://i.ytimg.com/vi/Nj5IK_nU4hs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-spear-of-destiny-longinus',
      'หอกแห่งโชคชะตา (หอกลองกินุสผู้ครอบครองชะตากรรมโลกแห่งเวียนนา)',
      'The Spear of Destiny: The Holy Lance of Longinus (Vienna)',
      'legend',
      'เวียนนา',
      'Vienna',
      'เวียนนา',
      'Vienna',
      48.2064,
      16.3656,
      'creepy_wind',
      'หอกเหล็กกล้าโบราณที่ประดับด้วยปลอกทองคำและมีตะปูตรึงกางเขนฝังอยู่ในคมหอก ตามตำนานพระคัมภีร์ หอกนี้เป็นของนายร้อยลองกินุส ทหารโรมันผู้ใช้แทงสีข้างของพระเยซูคริสต์ขณะถูกตรึงบนกางเขน ตำนานยุคกลางเล่าว่า ''ผู้ใดครอบครองหอกนี้และเข้าใจพลังของมัน จะกุมชะตากรรมของโลกไว้ในมือ แต่หากสูญเสียหอกไป ความตายจะมาเยือนทันที'' จักรพรรดิชาร์เลอมาญ, จักรพรรดิฟรีดริช บาร์บารอสซา และ อดอล์ฟ ฮิตเลอร์ ต่างคลั่งไคล้และแย่งชิงหอกนี้มาครอบครองเพื่อสร้างอาณาจักร',
      'Displayed in the Imperial Treasury (Schatzkammer) at the Hofburg Palace in Vienna, the Holy Lance (Spear of Destiny) is historically revered as the spear that Roman centurion Longinus thrust into Christ''s side at Golgotha. Embedded with a sacred crucifixion nail, medieval European lore claimed that whoever possessed the spear held the destiny of the world, never knowing defeat in battle. Charlemagne carried it through 47 victorious campaigns, while Adolf Hitler seized it from Vienna in 1938, stashing it in Nuremberg bunkers until recovered by Patton''s third army.',
      'ฮิตเลอร์ทำอัตวินิบาตกรรมในกรุงเบอร์ลินเพียงไม่กี่ชั่วโมงหลังจากกองทัพสหรัฐฯ ยึดหอกศักดิ์สิทธิ์นี้คืนมาได้ในวันที่ 30 เมษายน 1945 ซึ่งสอดคล้องกับคำสาปของหอกอย่างน่าขนลุก',
      'A prized centerpiece of the Habsburg Imperial Regalia, the Holy Lance represents millennia of chivalric mythology, European crusade history, and modern wartime lore.',
      'ห้ามสัมผัสหรือลบหลู่ตัวหอกลองกินุสในตู้จัดแสดงพระราชวังฮอฟบวร์ก',
      'Never attempt to strike or tap the acrylic vault housing the Holy Lance in the Hofburg.',
      'https://i.ytimg.com/vi/XKjS2s6XGsI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XKjS2s6XGsI/hqdefault.jpg","title":"หอกแห่งโชคชะตา (หอกลองกินุสผู้ครอบครองชะตากรรมโลกแห่งเวียนนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XKjS2s6XGsI","title":"The UnXplained: The Spear of Destiny Has Divine Powers (Season 5) | History","thumbnail":"https://i.ytimg.com/vi/XKjS2s6XGsI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-jantar-mantar-equinoctial-sundial',
      'จันตาร์ มันตาร์ (หอดูดาวหินยักษ์และนาฬิกาแดดใหญ่ที่สุดในโลก ไชปุระ)',
      'Jantar Mantar: The Vrihat Samrat Yantra of Jaipur',
      'legend',
      'ราชสถาน',
      'Rajasthan',
      'ไชปุระ',
      'Jaipur',
      26.9248,
      75.8246,
      'temple_bell',
      'หอดูดาวดาราศาสตร์กลางแจ้งขนาดยักษ์ที่สร้างขึ้นในปี 1734 โดยมหาราชาสวาอี ชัยสิงห์ที่ 2 ประกอบด้วยเครื่องมือวัดทางดาราศาสตร์ที่สร้างจากหินทรายและหินอ่อน 19 ชนิด ไฮไลต์คือ ''วริฮัต สัมรัต ยันตรา'' นาฬิกาแดดหินที่ใหญ่ที่สุดในโลก สูงตระหง่านถึง 27 เมตร เงาของเสาหินที่ทอดลงบนส่วนโค้งสามารถบอกเวลาท้องถิ่นได้อย่างแม่นยำภายในระดับ 2 วินาที และสามารถคำนวณการโคจรของดวงดาว สุริยุปราคา และระบุตำแหน่งราศีบนท้องฟ้าได้อย่างแม่นยำอย่างน่าอัศจรรย์ใจ',
      'Constructed in 1734 by astronomer-king Maharaja Sawai Jai Singh II, Jantar Mantar in Jaipur features nineteen architectural astronomical instruments sculpted from local stone and marble. Its crowning monument, the Vrihat Samrat Yantra, is the world''s largest stone sundial, rising 27 meters (90 feet) high. Its massive gnomon casts a shadow that moves at a visible rate of one millimeter per second, measuring local solar time to an astonishing precision of within two seconds.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 2010 ในฐานะการแสดงออกที่สมบูรณ์แบบที่สุดของการผสานดาราศาสตร์ สถาปัตยกรรม และศาสนาฮินดูในยุคเรืองปัญญาของอินเดีย',
      'A UNESCO World Heritage Site, Jantar Mantar stands as the zenith of pre-telescopic astronomical observation, still used by Vedic astrologers to forecast monsoon dates.',
      'ห้ามปีนป่ายขึ้นไปบนแนวมุมลาดเอียงของนาฬิกาแดดหินยักษ์',
      'Never walk or climb upon the delicate calibrated shadow scales of the stone instruments.',
      'https://i.ytimg.com/vi/JDiAzkNoLeY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JDiAzkNoLeY/hqdefault.jpg","title":"จันตาร์ มันตาร์ (หอดูดาวหินยักษ์และนาฬิกาแดดใหญ่ที่สุดในโลก ไชปุระ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JDiAzkNoLeY","title":"Jantar Mantar Jaipur | Largest Sundial in the World | 18th century Stone Astronomical Observatory","thumbnail":"https://i.ytimg.com/vi/JDiAzkNoLeY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-king-solomon-mines-timna',
      'เหมืองกษัตริย์โซโลมอนแห่งหุบเขาทิมนา (เสาศิลาและทองแดงโบราณ)',
      'King Solomon''s Mines of Timna Valley (The Copper Enigma)',
      'legend',
      'ใต้',
      'Southern District',
      'เอลัต',
      'Eilat',
      29.7894,
      34.9658,
      'creepy_wind',
      'หุบเขาหินทรายสีแดงรูปเกือกม้ากลางทะเลทรายเนเกฟ โดดเด่นด้วย ''เสาศิลาโซโลมอน'' (Solomon''s Pillars) เสาหินทรายธรรมชาติขนาดยักษ์สูงตระหง่าน ที่นี่เป็นแหล่งทำเหมืองทองแดงที่เก่าแก่ที่สุดในโลก มีร่องรอยการถลุงแร่มาตั้งแต่ 6,000 ปีก่อนคริสตกาล ในปี 2013 นักโบราณคดีมหาวิทยาลัยเทลอาวีฟได้ขุดพบหลักฐานการถลุงแร่ระดับอุตสาหกรรมในศตวรรษที่ 10 ก่อนคริสตกาล ซึ่งตรงกับรัชสมัยของกษัตริย์โซโลมอนในคัมภีร์ไบเบิลอย่างแม่นยำ ยืนยันว่านี่คือ ''เหมืองทองแดงของกษัตริย์โซโลมอน'' ที่เคยสร้างความมั่งคั่งให้แก่อาณาจักรอิสราเอลโบราณ',
      'Timna Valley in the Negev Desert is framed by dramatic red sandstone cliffs, dominated by the majestic natural geological buttresses known as Solomon''s Pillars. Excavations by Dr. Erez Ben-Yosef in 2013 at Slaves'' Hill revealed massive copper smelting works carbon-dated to the 10th century BC—the exact biblical era of King Solomon. Far from primitive nomads, evidence showed an advanced Edomite society operating sophisticated metallurgical furnaces that supplied Solomon with the metals to build the First Temple.',
      'ในหุบเขายังมีการค้นพบวิหารของเทพีฮาธอร์ (Hathor) เทพีแห่งเหมืองแร่ของอียิปต์โบราณ พร้อมภาพสลักหินของฟาโรห์ราเมสเสสที่ 3',
      'Featuring preserved ancient smelting camps, rock inscriptions, and chiseled mine shafts, Timna Park is celebrated as one of the world''s most vivid intersections of biblical archaeology and geology.',
      'ห้ามเก็บหรือหยิบฉวยเศษตะกรันแร่ทองแดงโบราณ (Slag) ออกจากเขตอุทยาน',
      'Never collect or remove ancient copper slag specimens from historical smelting mounds.',
      'https://i.ytimg.com/vi/yEL2Uju5900/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yEL2Uju5900/hqdefault.jpg","title":"เหมืองกษัตริย์โซโลมอนแห่งหุบเขาทิมนา (เสาศิลาและทองแดงโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yEL2Uju5900","title":"The Lost Gold of King Solomon’s Mines | Forbidden History | S7E8 | Full Episode","thumbnail":"https://i.ytimg.com/vi/yEL2Uju5900/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-ark-of-covenant-axum-zion',
      'หีบแห่งพันธสัญญาแห่งอักซุม (โบสถ์พระแม่มารีย์แห่งไซออน เอธิโอเปีย)',
      'The Ark of the Covenant at Church of Our Lady Mary of Zion (Axum)',
      'legend',
      'ทิเกรย์',
      'Tigray Region',
      'อักซุม',
      'Axum',
      14.13,
      38.7194,
      'temple_bell',
      'หีบทองคำศักดิ์สิทธิ์ที่บรรจุแผ่นศิลาจารึกบัญญัติ 10 ประการที่พระเจ้าประทานแก่โมเสสบนภูเขาไซนาย มหากาพย์เคบรา นากัสต์ (Kebra Nagast) ของเอธิโอเปียระบุว่า กษัตริย์เมเนลิกที่ 1 โอรสของกษัตริย์โซโลมอนและราชินีแห่งชีบา ได้อัญเชิญหีบแห่งพันธสัญญามาจากวิหารกรุงเยรูซาเลมมายังนครอักซุม ปัจจุบันหีบถูกเก็บรักษาไว้ในโบสถ์น้อยแห่งพระแม่มารีย์แห่งไซออน โดยมี ''พระผู้พิทักษ์หีบ'' เพียงรูปเดียวที่ได้รับอนุญาตให้เข้าไปเห็นและเฝ้าหีบตลอดชีวิตจนกว่าจะมรณภาพ',
      'According to the Ethiopian national epic, the Kebra Nagast, the biblical Ark of the Covenant was brought from Jerusalem to Ethiopia by King Menelik I, the son of King Solomon and the Queen of Sheba. Today, the sacred golden chest holding the stone tablets of the Ten Commandments is enshrined inside the Chapel of the Tablet at the Church of Our Lady Mary of Zion in Axum. A single virgin monk, chosen as the lifelong Guardian of the Ark, is the only human permitted to lay eyes on the relic until his death.',
      'นครโบราณอักซุมได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1980 เสาหินโอเบลิสก์ยักษ์แกะสลักและจารึกโบราณยืนยันถึงความยิ่งใหญ่ของอาณาจักรอักซุมโบราณ',
      'Centuries of international historians, including Graham Hancock in ''The Sign and the Seal'', investigated the claim, establishing Axum as the definitive spiritual sanctuary of the Ethiopian Orthodox Tewahedo Church.',
      'ห้ามผู้ใดก็ตาม ยกเว้นพระผู้พิทักษ์หีบ ก้าวล่วงเข้าสู่เขตโบสถ์น้อยแห่งศิลา',
      'No one—including the Ethiopian Patriarch—may enter the inner sanctum of the Guardian of the Ark.',
      'https://i.ytimg.com/vi/hdGXXyPS1Rg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hdGXXyPS1Rg/hqdefault.jpg","title":"หีบแห่งพันธสัญญาแห่งอักซุม (โบสถ์พระแม่มารีย์แห่งไซออน เอธิโอเปีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hdGXXyPS1Rg","title":"The Ark Of The Covenant''s Secret The Ethiopian Church Never Revealed","thumbnail":"https://i.ytimg.com/vi/hdGXXyPS1Rg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-rosslyn-chapel-apprentice-pillar',
      'โบสถ์น้อยรอสส์ลิน (เสาหลักศิษย์เอกและรหัสลับอัศวินเทมพลาร์ สก็อตแลนด์)',
      'Rosslyn Chapel & The Apprentice Pillar of the Knights Templar',
      'legend',
      'มิดโลเธียน',
      'Midlothian',
      'รอสลิน',
      'Roslin',
      55.8553,
      -3.16,
      'temple_bell',
      'โบสถ์หินในศตวรรษที่ 15 ที่เต็มไปด้วยภาพแกะสลักปริศนาอันลึกลับ สร้างขึ้นโดย เซอร์ วิลเลียม ซินแคลร์ ทุกตารางนิ้วของเพดานและเสาหินสลักสัญลักษณ์ของอัศวินเทมพลาร์ ลัทธิฟรีเมสัน โนสติก และพืชข้าวโพดอเมริกัน (ซึ่งสร้างก่อนโคลัมบัสค้นพบทวีปอเมริกา) ไฮไลต์คือ ''เสาหลักศิษย์เอก'' (Apprentice Pillar) ที่มีมังกรแปดตัวพ่นเถาวัลย์พันรอบเสาอย่างวิจิตร เล่ากันว่าหัวหน้าช่างหินอิจฉาในฝีมือของศิษย์เอกจึงใช้ค้อนทุบศีรษะศิษย์จนเสียชีวิต ใต้พื้นโบสถ์มีห้องใต้ดินที่ถูกปิดตาย ซึ่งเชื่อว่าเป็นที่ซ่อน ''จอกศักดิ์สิทธิ์'' หรือพระศพของพระเยซูคริสต์',
      'Founded in 1446 by Sir William St. Clair, Rosslyn Chapel is renowned for its bewildering density of Gothic stonework, weaving together Christian, Masonic, pagan Green Man, and Templar symbolism. The Apprentice Pillar features eight dragons wrapped around its base with tendrils climbing toward the vault; legend says the master mason murdered his young apprentice with a mallet in a jealous rage after the youth carved the exquisite pillar while the master was away in Rome. Beneath lies sealed vaults rumored to hide the Holy Grail.',
      'โบสถ์น้อยรอสส์ลินโด่งดังไปทั่วโลกจากการเป็นฉากไคลแม็กซ์สำคัญในนวนิยายและภาพยนตร์เรื่อง ''The Da Vinci Code'' ของ แดน บราวน์ นำพาผู้แสวงบุญนับล้านมาเยือน',
      'Carefully conserved by the Rosslyn Chapel Trust, the site blends medieval stonemasonry guilds, Scottish nobility lore, and international grail literature.',
      'ห้ามใช้ขาตั้งกล้องหรือถ่ายภาพภายในพระวิหารเพื่อรักษาความสงบ',
      'Indoor photography and video recording are strictly prohibited inside the chapel.',
      'https://i.ytimg.com/vi/g6Xpb-zanw0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/g6Xpb-zanw0/hqdefault.jpg","title":"โบสถ์น้อยรอสส์ลิน (เสาหลักศิษย์เอกและรหัสลับอัศวินเทมพลาร์ สก็อตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=g6Xpb-zanw0","title":"Guide Video - ''The Apprentice Pillar''","thumbnail":"https://i.ytimg.com/vi/g6Xpb-zanw0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-man-in-iron-mask-sainte-marguerite',
      'เกาะแซงต์-มาร์เกอริต (คุกขังบุรุษในหน้ากากเหล็กแห่งฝรั่งเศส)',
      'Fort Royal & The Man in the Iron Mask (Île Sainte-Marguerite)',
      'legend',
      'อาลป์-มารีตีม',
      'Alpes-Maritimes',
      'คานส์',
      'Cannes',
      43.5217,
      7.0458,
      'water_spirit',
      'ป้อมปราการฟอร์รอยัลบนเกาะแซงต์-มาร์เกอริต นอกชายฝั่งเมืองคานส์ ในศตวรรษที่ 17 ป้อมแห่งนี้ถูกใช้เป็นคุกคุมขัง ''นักโทษหมายเลข 64389000'' หรือบุรุษในหน้ากากเหล็ก ชายนิรนามผู้ถูกบังคับให้สวมหน้ากากกำมะหยี่สีดำขอบเหล็กปิดบังใบหน้าตลอด 24 ชั่วโมงจนวันตาย โดยมีทหารยามเฝ้าพร้อมคำสั่งสังหารทันทีหากเขาถอดหน้ากากหรือเอ่ยชื่อตนเอง วอลแตร์ และ อเล็กซองดร์ ดูมาส์ เสนอทฤษฎีว่าเขาคือ ''พี่ชายฝาแฝดของพระเจ้าหลุยส์ที่ 14'' ที่ถูกนำมาขังลืมเพื่อไม่ให้แย่งชิงราชบัลลังก์',
      'Built upon the rocky shores of Île Sainte-Marguerite off Cannes, Fort Royal was the seaside prison where the enigmatic ''Man in the Iron Mask'' was incarcerated for eleven years under King Louis XIV. Guarded by royal musketeer Bénigne Dauvergne de Saint-Mars, the prisoner was forced to wear a locked velvet and iron mask on pain of death if he revealed his identity. Voltaire and Alexandre Dumas popularized the theory that the prisoner was Louis XIV''s identical twin brother, hidden away to prevent succession crises.',
      'ห้องขังหินดั้งเดิมของบุรุษในหน้ากากเหล็กยังคงเปิดให้เข้าชมภายในพิพิธภัณฑ์ทางทะเล (Musée de la Mer) บนเกาะแซงต์-มาร์เกอริต เป็นหนึ่งในปริศนาทางประวัติศาสตร์ฝรั่งเศสที่น่าหลงใหลที่สุด',
      'Immortalized in Dumas'' classic novel and Hollywood films, the prison cell preserves original iron-barred windows looking out onto the Mediterranean.',
      'ห้ามขีดเขียนชื่อลงบนผนังห้องขังประวัติศาสตร์ของบุรุษในหน้ากากเหล็ก',
      'Never scratch graffiti or damage the stone walls of the Iron Mask''s prison cell.',
      'https://i.ytimg.com/vi/V04etDmSza4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/V04etDmSza4/hqdefault.jpg","title":"เกาะแซงต์-มาร์เกอริต (คุกขังบุรุษในหน้ากากเหล็กแห่งฝรั่งเศส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=V04etDmSza4","title":"The Man in the Iron Mask: France''s Greatest Secret Revealed | FD History","thumbnail":"https://i.ytimg.com/vi/V04etDmSza4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-klerksdorp-spheres-ottosdal',
      'ลูกทรงกลมเคลิร์กสดอร์ป (วัตถุโลหะกลึงอายุ 3,000 ล้านปีแห่งแอฟริกาใต้)',
      'The 3-Billion-Year-Old Klerksdorp Spheres of Ottosdal',
      'legend',
      'นอร์ทเวสต์',
      'North West',
      'ออตตอสดาล',
      'Ottosdal',
      -26.8111,
      26.0125,
      'whisper',
      'ลูกทรงกลมโลหะสีน้ำเงินเข้มปนแดงขนาดเส้นผ่านศูนย์กลาง 1-4 นิ้ว ขุดพบโดยคนงานเหมืองแร่ไพโรฟิลไลต์ใกล้เมืองออตตอสดาล ประเทศแอฟริกาใต้ หินชั้นที่ขุดพบมีอายุทางธรณีวิทยาย้อนหลังไปถึงมหายุคพรีแคมเบรียนกว่า 3,000 ล้านปี (ก่อนการกำเนิดของสัตว์หลายเซลล์) ทว่าลูกทรงกลมเหล่านี้กลับมีรูปทรงกลมเกลี้ยงและมี ''ร่องเส้นขนานสามเส้น'' สลักรอบกึ่งกลางลูกอย่างประณีตราวกับการกลึงด้วยเครื่องจักรกล นักธรณีวิทยาอธิบายว่าเป็นก้อนแร่คอนครีชัน (Concretion) แต่ผู้ชื่นชอบทฤษฎีอารยธรรมโบราณเชื่อว่าเป็นหลักฐานของมนุษย์ต่างดาวหรืออารยธรรมยุคก่อนประวัติศาสตร์',
      'Mined by quarrymen out of 3-billion-year-old Precambrian pyrophyllite deposits in Ottosdal, the Klerksdorp Spheres are disc-shaped mineral nodules measuring a few inches across. Several specimens feature three precisely parallel grooves cut around their equators, appearing machine-lathed. Proponents of ancient astronauts and Out-Of-Place Artifacts (OOPArts) claimed they were forged by intelligent beings billions of years before multicellular life existed. Geologists identify them as natural hematite and pyrite concretions formed by volcanic ash mineralization.',
      'ลูกทรงกลมเคลิร์กสดอร์ปจัดแสดงอยู่ที่พิพิธภัณฑ์ประวัติศาสตร์เคลิร์กสดอร์ป (Klerksdorp Museum) และได้รับการจัดอันดับให้เป็นหนึ่งในโบราณวัตถุพรีแคมเบรียนที่น่าตื่นเต้นที่สุด',
      'Examined by petrologists from the Council for Geoscience, these geological formations remain widely discussed in alternative archaeology and anomalous science forums.',
      'ห้ามทุบทำลายหรือพยายามผ่าครึ่งลูกทรงกลมแร่ออตตอสดาล',
      'Never attempt to crack or smash ancient pyrophyllite mineral spheroids.',
      'https://i.ytimg.com/vi/hpNboEJtS60/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hpNboEJtS60/hqdefault.jpg","title":"ลูกทรงกลมเคลิร์กสดอร์ป (วัตถุโลหะกลึงอายุ 3,000 ล้านปีแห่งแอฟริกาใต้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hpNboEJtS60","title":"South Africas Ancient Mystery The Truth Behind the Klerksdorp Spheres","thumbnail":"https://i.ytimg.com/vi/hpNboEJtS60/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-mogollon-monster-arizona-rim',
      'สัตว์ประหลาดโมโกยอน (อสูรขนดกแห่งแนวผาแอริโซนา)',
      'The Mogollon Monster (Hairy Beast of the Mogollon Rim)',
      'monster',
      'แอริโซนา',
      'Arizona',
      'แนวผาโมโกยอน โคโคนิโน',
      'Mogollon Rim, Coconino',
      34.3314,
      -111.0827,
      'creepy_wind',
      'สิ่งมีชีวิตลึกลับคล้ายบิ๊กฟุตแต่ดุร้ายกว่ามาก อาศัยอยู่ตามป่าสนทึบและแนวผาหินโมโกยอน (Mogollon Rim) ในรัฐแอริโซนา มีพยานพบเห็นสิ่งมีชีวิตร่างยักษ์สูงกว่า 8 ฟุต ร่างกายปกคลุมด้วยขนสีดำหรือน้ำตาลแดงหนาทึบ ดวงตาสีแดงก่ำเรืองแสงในความมืด มีกลิ่นสาบรุนแรงคล้ายซากสัตว์เน่าเปื่อย และส่งเสียงคำรามโหยหวนคล้ายเสียงผู้หญิงกรีดร้องผสมเสียงสัตว์ป่า มักมีรายงานการโจมตีแคมป์และขว้างปาก้อนหินใส่ผู้คนที่ตั้งเต็นท์ในป่าลึก',
      'The Mogollon Monster is a legendary bipedal ape-man cryptid reported along the Mogollon Rim in central Arizona. Described as standing around 8 feet tall with dark reddish-brown hair, piercing reflective eyes, and an overpowering stench of decaying rot, this creature is known for terrifying screams echoing off canyon walls and violently ransacking campsites.',
      'มีรายงานบันทึกการพบเห็นตั้งแต่ช่วงปี 1903 โดยนักขี่ม้าและลูกเสือที่ตั้งแคมป์ริมหน้าผา เล่าต่อกันว่าเป็นวิญญาณคนเถื่อนหรือสัตว์ดึกดำบรรพ์ที่รอดชีวิตในหุบเขาลึก',
      'First documented in print in 1903, folklore traces the monster back to Apache legends of wild mountain men and cryptozoological sightings by Boy Scout troops camping along the Mogollon Rim.',
      'ห้ามทิ้งเศษอาหารหรือเดินเดี่ยวในป่าสนยามค่ำคืน',
      'Never wander off trail alone at night or leave unsealed food around the rim campgrounds.',
      'https://i.ytimg.com/vi/drLTEe-YCUo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/drLTEe-YCUo/hqdefault.jpg","title":"สัตว์ประหลาดโมโกยอน (อสูรขนดกแห่งแนวผาแอริโซนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=drLTEe-YCUo","title":"The Mogollon Monster; Arizona''s bigfoot","thumbnail":"https://i.ytimg.com/vi/drLTEe-YCUo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-fouke-monster-boggy-creek',
      'สัตว์ประหลาดฟาวก์ (อสูรแห่งลำห้วยบ็อกกี้ครีก)',
      'The Fouke Monster (The Beast of Boggy Creek)',
      'monster',
      'อาร์คันซอ',
      'Arkansas',
      'เมืองฟาวก์ มิลเลอร์',
      'Fouke, Miller County',
      33.2612,
      -93.8863,
      'jungle_curse',
      'ตำนานสัตว์ประหลาดอันโด่งดังแห่งลุ่มน้ำซัลเฟอร์และลำห้วยบ็อกกี้ครีก เมืองฟาวก์ รัฐอาร์คันซอ ที่มีรายงานการพบเห็นมาตั้งแต่ช่วงทศวรรษ 1940 และเกิดเหตุการณ์ระทึกขวัญในปี 1971 เมื่อสิ่งมีชีวิตคล้ายลิงไร้หางขนาดมหึมา สูงกว่า 7 ฟุต ลำตัวกำยำ ขนดกยาว และมีฝ่าเท้า 3 นิ้วขนาดใหญ่ เข้าบุกโจมตีบ้านพักริมป่าพรุของครอบครัวฟอร์ดจนกลายเป็นข่าวดังไปทั่วโลกและถูกนำไปสร้างเป็นภาพยนตร์สยองขวัญคลาสสิก',
      'The Fouke Monster, also dubbed the Beast of Boggy Creek, is a terrifying hominid cryptid documented in Fouke, Arkansas since the 1940s. Gaining international notoriety after violently attacking a rural homestead in 1971, witnesses report a massive 7-foot tall, foul-smelling creature with three-toed tracks prowling the dense bottomland swamps.',
      'เหตุการณ์โจมตีบ้านครอบครัวฟอร์ดในปี 1971 ได้รับการตรวจสอบโดยเจ้าหน้าที่ตำรวจท้องถิ่น และนำไปสู่การสร้างภาพยนตร์ ''The Legend of Boggy Creek'' ในปี 1972',
      'The intense 1971 Ford family encounter sparked widespread news coverage and inspired the seminal 1972 docudrama horror movie ''The Legend of Boggy Creek''.',
      'ห้ามลุยป่าพรุตามลำพังยามพลบค่ำโดยไม่มีอาวุธป้องกันตัว',
      'Avoid traversing the dense cypress swamps of Boggy Creek after dusk.',
      'https://i.ytimg.com/vi/X7OzLqyFjVQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/X7OzLqyFjVQ/hqdefault.jpg","title":"สัตว์ประหลาดฟาวก์ (อสูรแห่งลำห้วยบ็อกกี้ครีก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=X7OzLqyFjVQ","title":"Boggy Creek Monster - (New Bigfoot Sasquatch Eyewitness Documentary)","thumbnail":"https://i.ytimg.com/vi/X7OzLqyFjVQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-sea-bishop-baltic-sea',
      'บิชอปแห่งท้องทะเล (ปีศาจปลาสมณศักดิ์แห่งทะเลบอลติก)',
      'The Sea Bishop (Bishop-fish of the Baltic Sea)',
      'monster',
      'ปอมเมอเรเนีย',
      'Pomerania',
      'ชายฝั่งทะเลบอลติก กดานสค์',
      'Baltic Coast, Gdansk',
      54.352,
      18.6466,
      'jungle_curse',
      'อสูรกายแห่งท้องทะเลในบันทึกประวัติศาสตร์ธรรมชาติยุคศตวรรษที่ 16 ระบุว่าถูกจับได้ในทะเลบอลติกนอกชายฝั่งโปแลนด์เมื่อปี ค.ศ. 1531 สิ่งมีชีวิตประหลาดนี้มีรูปร่างคล้ายปลาแต่ส่วนหัวมีเกล็ดและครีบแหลมสูงเรียงตัวประหนึ่งหมวกไมเตอร์ของบิชอปในศาสนจักร เมื่อถูกนำตัวขึ้นทูลเกล้าฯ ถวายกษัตริย์โปแลนด์ มันได้แสดงท่าทางกราบไหว้และชี้มือไปยังทะเลเพื่อขอความเมตตาจนบิชอปและกษัตริย์ยอมปล่อยมันกลับคืนสู่มหาสมุทร',
      'The Sea Bishop, or Bishop-fish, is an enigmatic marine monster recorded in 16th-century natural histories, allegedly captured in the Baltic Sea off Poland in 1531. Bearing scaly growths resembling a Catholic bishop''s miter and vestments, the sorrowful creature made signs of the cross and gestured towards the sea until the King granted its release back into the deep.',
      'ได้รับการบันทึกอย่างจริงจังในสารานุกรมธรรมชาติวิทยาของคอนราด เกสส์เนอร์ (Conrad Gessner) ในปี 1558 และกลายเป็นภาพวาดคลาสสิกของสัตว์ประหลาดใต้ทะเลในยุคกลาง',
      'Immortalized in Conrad Gessner''s landmark 1558 Historia Animalium, the creature remains one of the Renaissance''s most curious zoological mysteries.',
      'ห้ามกักขังหรือทำร้ายสิ่งมีชีวิตในทะเลที่มีลักษณะศักดิ์สิทธิ์',
      'Never harm or imprison marine entities bearing holy or sacred visages.',
      'https://i.ytimg.com/vi/6Ca_t3Kxh-s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6Ca_t3Kxh-s/hqdefault.jpg","title":"บิชอปแห่งท้องทะเล (ปีศาจปลาสมณศักดิ์แห่งทะเลบอลติก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6Ca_t3Kxh-s","title":"Sea Monks and Sea Bishops: The \"Clergy\" of the Sea","thumbnail":"https://i.ytimg.com/vi/6Ca_t3Kxh-s/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-beast-of-dean-gloucestershire',
      'อสูรแห่งดีน (มูสพิก อสูรกายยักษ์แห่งป่าโบราณ)',
      'The Beast of Dean (Moose-Pig of Gloucestershire Forest)',
      'monster',
      'กลอสเตอร์เชอร์',
      'Gloucestershire',
      'ป่าแห่งดีน',
      'Forest of Dean',
      51.8025,
      -2.5435,
      'creepy_wind',
      'ตำนานอสูรลึกลับแห่งป่าโบราณฟอเรสต์ออฟดีน ในมณฑลกลอสเตอร์เชอร์ ประเทศอังกฤษ ชาวบ้านเรียกมันว่า ''มูส-พิก'' (Moose-Pig) มีลักษณะคล้ายหมูป่ายักษ์แต่มีขนาดตัวมหึมาเท่ากวางมูส มีเขี้ยวแหลมยาวโค้ง ขนตามตัวหยาบหนาเป็นสีเทาเข้ม มักออกอาละวาดทำลายต้นไม้ ล่าแกะและสัตว์เลี้ยงของชาวบ้านอย่างโหดเหี้ยมในยามค่ำคืน มีการจัดตั้งกองกำลังติดอาวุธออกตามล่าในต้นศตวรรษที่ 19 แต่ไม่เคยมีใครสังหารมันได้',
      'The Beast of Dean, known locally as the Moose-Pig, is a monstrous cryptid said to haunt the ancient Forest of Dean in Gloucestershire. Described as a wild boar of colossal, moose-like proportions with razor tusks and an insatiable aggression, it terrorized farmers in the early 19th century, sparking armed hunting parties that searched the dense woods in vain.',
      'ชาวบ้านในแถบหมู่บ้านโคลฟอร์ดและซินเดอร์ฟอร์ดระดมพลพร้อมสุนัขล่าเนื้อในปี 1802 หลังสัตว์เลี้ยงถูกฉีกกระชากร่าง แต่ไม่สามารถจับตัวได้ ทิ้งไว้เพียงรอยเท้ากีบขนาดยักษ์',
      'In 1802, terrified villagers around Coleford formed armed posses to track the colossal boar through the ancient royal forest after gruesome livestock kills.',
      'ห้ามเดินตัดผ่านป่าลึกฟอเรสต์ออฟดีนในยามหมอกลงจัด',
      'Never venture off marked forestry tracks when heavy fog rolls into Dean.',
      'https://i.ytimg.com/vi/Jl-wR7KT3u8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Jl-wR7KT3u8/hqdefault.jpg","title":"อสูรแห่งดีน (มูสพิก อสูรกายยักษ์แห่งป่าโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Jl-wR7KT3u8","title":"The Beast of Dean: British Folklore''s Forgotten Monster","thumbnail":"https://i.ytimg.com/vi/Jl-wR7KT3u8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-selma-lake-serpent-seljord',
      'เซลมา (พญานาคโบราณแห่งทะเลสาบเซลยอร์ด)',
      'Selma (The Ancient Sea Serpent of Lake Seljord)',
      'monster',
      'เทเลมาร์ก',
      'Telemark',
      'ทะเลสาบเซลยอร์ด',
      'Lake Seljord',
      59.4842,
      8.6315,
      'jungle_curse',
      'สัตว์ประหลาดแห่งทะเลสาบน้ำจืดเซลยอร์ด ประเทศนอร์เวย์ มีประวัติการพบเห็นย้อนกลับไปตั้งแต่ศตวรรษที่ 18 มีลักษณะคล้ายอสรพิษทะเลยักษ์ ลำตัวยาวขดเป็นคลื่นโผล่พ้นผิวน้ำ มีหัวคล้ายม้าหรือกวางมูส และดวงตาสีดำสนิทขนาดใหญ่ ตำนานเล่าว่ามันอาศัยอยู่ในร่องน้ำลึกใต้ผืนทะเลสาบ และทีมนักสำรวจนานาชาติเคยบันทึกสัญญาณคลื่นเสียงใต้น้ำที่ไม่สามารถระบุชนิดได้หลายครั้งในทะเลสาบแห่งนี้',
      'Selma is Norway''s famous lake monster dwelling in the deep, cold waters of Lake Seljord in Telemark. Chronicled since the 18th century, sightings describe a serpentine creature over 30 feet long with multiple humps and an equine head, attracting scientific sonar expeditions that have detected mysterious, unidentifiable large moving bodies in the abyss.',
      'บันทึกครั้งแรกย้อนไปในปี 1750 เมื่อพยานพบเห็นงูยักษ์คว่ำเรือพาย ในยุคทศวรรษ 1990 และ 2000 มีโครงการสำรวจ ''Project Selma'' นำโดยนักวิจัยระดับนานาชาติพร้อมอุปกรณ์โซนาร์ขั้นสูง',
      'Written accounts date back to 1750 when an eyewitness reported a sea dragon capsizing a rowboat. The multi-year international ''Project Selma'' scientific expeditions mapped intriguing acoustic anomalies.',
      'ห้ามว่ายน้ำหรือล่องเรือข้ามร่องน้ำลึกกึ่งกลางทะเลสาบตอนพลบค่ำ',
      'Avoid rowing or swimming over the deepest trenches of Lake Seljord around sunset.',
      'https://i.ytimg.com/vi/IGcNK5JpWqY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IGcNK5JpWqY/hqdefault.jpg","title":"เซลมา (พญานาคโบราณแห่งทะเลสาบเซลยอร์ด)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IGcNK5JpWqY","title":"Selma Revealed in Full: Unraveling the Secrets of Norway''s Sea Serpent","thumbnail":"https://i.ytimg.com/vi/IGcNK5JpWqY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-storsjoodjuret-great-lake-sweden',
      'สตอร์ชูอูดยูเรต (อสูรทะเลสาบยักษ์แห่งแย็มต์ลันด์)',
      'Storsjoodjuret (The Great Lake Monster of Jamtland)',
      'monster',
      'แย็มต์ลันด์',
      'Jamtland',
      'ทะเลสาบสตอร์ชูน เอิสเตอร์ซุนด์',
      'Lake Storsjon, Ostersund',
      63.1792,
      14.6357,
      'jungle_curse',
      'สัตว์ประหลาดในตำนานพื้นบ้านสวีเดนที่อาศัยอยู่ในทะเลสาบสตอร์ชูน ทะเลสาบที่ลึกที่สุดแห่งหนึ่งในสวีเดน ตำนานระบุว่ามันถูกสร้างขึ้นจากเวทมนตร์ของโทรลล์สองตัวที่ต้มสารพัดพิษและงูลงในหม้อยักษ์ริมทะเลสาบ จนเกิดเป็นอสูรกายลำตัวยาวคล้ายพญานาคที่มีครีบหลังเหมือนใบเลื่อย ลำตัวสีเทาดำ และหัวคล้ายสุนัขหรือแมว ในปี 1986 รัฐบาลท้องถิ่นถึงกับเคยออกกฎหมายคุ้มครองมันเป็นสัตว์หายาก',
      'Storsjoodjuret is Sweden''s legendary lake serpent inhabiting the deep waters of Lake Storsjon in Jamtland. Originating from folklore involving trolls brewing a mystical kettle on the shore, the 20-foot aquatic beast is described as having undulating humps, large dark eyes, and canine ears, famously receiving royal and legal protection status in 1986.',
      'ตำนานถูกสลักไว้บนศิลาจารึกรูนฟราเซอ (Froso Runestone) บนเกาะฟราเซอกลางทะเลสาบ เล่าถึงการใช้เวทมนตร์สะกดสัตว์ร้ายตนนี้ไว้ใต้ก้นทะเลสาบ',
      'Folkloric roots tie into the ancient Froso Runestone on the lake''s central island, which traditional tales claimed bound the demonic creature to the lake bed.',
      'ห้ามท้าทายหรือโยนหินลงไปในจุดน้ำวนลึกของเกาะฟราเซอ',
      'Do not throw stones or taunt the murky whirlpools near Froso Island.',
      'https://i.ytimg.com/vi/ubFfmDwv7Bo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ubFfmDwv7Bo/hqdefault.jpg","title":"สตอร์ชูอูดยูเรต (อสูรทะเลสาบยักษ์แห่งแย็มต์ลันด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ubFfmDwv7Bo","title":"Sweden''s Great Lake Monster - Storsjöodjuret","thumbnail":"https://i.ytimg.com/vi/ubFfmDwv7Bo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-nahuelito-patagonia-huapi',
      'นาฮูเอลิโต (ไดโนเสาร์ทะเลสาบแห่งพาทาโกเนีย)',
      'Nahuelito (The Plesiosaur Cryptid of Lake Nahuel Huapi)',
      'monster',
      'ริโอเนโกร',
      'Rio Negro',
      'ทะเลสาบนาฮูเอล อัวปิ บาริโลเช',
      'Lake Nahuel Huapi, Bariloche',
      -41.05,
      -71.45,
      'jungle_curse',
      'อสูรใต้ผืนน้ำแห่งทะเลสาบน้ำแข็งนาฮูเอล อัวปิ ในภูมิภาคพาทาโกเนีย ประเทศอาร์เจนตินา ชนพื้นเมืองมาปูเชมีตำนานเล่าขานถึง ''กูเอรู'' (Cuero) หรืออสูรหนังวัวน้ำมาหลายร้อยปี ก่อนที่ในต้นศตวรรษที่ 20 จะมีพยานพบเห็นสิ่งมีชีวิตคอยาวคล้ายไดโนเสาร์เพลซิโอซอร์แหวกว่ายท่ามกลางระลอกคลื่นยักษ์ มีการจัดตั้งคณะสำรวจล่าสัตว์ประหลาดแห่งบัวโนสไอเรสในปี 1922 แต่ยังคงเป็นปริศนาจนถึงปัจจุบัน',
      'Nahuelito is the fabled aquatic cryptid believed to inhabit the glacial depths of Lake Nahuel Huapi in Argentine Patagonia. Rooted in indigenous Mapuche mythology, modern sightings of a long-necked serpentine beast with dorsal humps provoked an official scientific hunt by the Buenos Aires Zoo in 1922, cementing its status as the South American counterpart to Nessie.',
      'ชนพื้นเมืองมาปูเชเตือนว่ามีสัตว์ร้ายใต้น้ำที่ไร้กระดูกแต่มีหนามแหลมรอบตัว ต่อมานักสำรวจชาวอเมริกัน มาร์ติน เชฟฟิลด์ ได้ส่งจดหมายถึงผู้อำนวยการสวนสัตว์บัวโนสไอเรสจนนำไปสู่คณะสำรวจประวัติศาสตร์',
      'Originated in Mapuche mythology as the ''Cuero'', modern cryptozoology took off after American prospector Martin Sheffield reported viewing the behemoth in 1922.',
      'ห้ามแล่นเรือเล็กออกไปในเวิ้งน้ำเปิดยามมีพายุลมกรรโชกแรงแห่งเทือกเขาแอนดีส',
      'Do not navigate small boats into open deep waters when Andean storm winds blow.',
      'https://i.ytimg.com/vi/-74TBmAIyP4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-74TBmAIyP4/hqdefault.jpg","title":"นาฮูเอลิโต (ไดโนเสาร์ทะเลสาบแห่งพาทาโกเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-74TBmAIyP4","title":"Argentina”s Lake Monster","thumbnail":"https://i.ytimg.com/vi/-74TBmAIyP4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-memphre-lake-memphremagog',
      'เมมเฟร (พญานาคสองแผ่นดินแห่งทะเลสาบเมมเฟรมากอก)',
      'Memphre (The Border Serpent of Lake Memphremagog)',
      'monster',
      'ควิเบก',
      'Quebec',
      'ทะเลสาบเมมเฟรมากอก มากอก',
      'Lake Memphremagog, Magog',
      45.1667,
      -72.25,
      'jungle_curse',
      'สัตว์ประหลาดแห่งทะเลสาบเมมเฟรมากอก พรมแดนธรรมชาติระหว่างรัฐควิเบก ประเทศแคนาดา และรัฐเวอร์มอนต์ สหรัฐอเมริกา ตำนานชนเผ่าอาเบนากิ (Abenaki) เตือนไม่ให้ว่ายน้ำข้ามทะเลสาบเพราะมีงูยักษ์คอยลากคนลงสู่ก้นบึ้ง ในยุคใหม่มีพยานพบเห็นสิ่งมีชีวิตลำตัวยาวคล้ายงูทะเล ผิวมันวาวสีดำอมเขียว ยาวกว่า 30 ถึง 40 ฟุต เคลื่อนที่อย่างรวดเร็วและทิ้งคลื่นน้ำขนาดใหญ่ไว้เบื้องหลัง',
      'Memphre is a legendary lake reptile documented in Lake Memphremagog on the border between Quebec, Canada, and Vermont, USA. First revered by the indigenous Abenaki people who warned of a terrifying giant serpent, hundreds of modern witnesses have reported a dark, fast-swimming creature over 30 feet long with distinct serpentine coils.',
      'ตำนานอาเบนากิบอกเล่าต่อกันมาหลายชั่วอายุคน ต่อมาในปี 1816 มีบันทึกของชาวอาณานิคมยุคแรกเห็นสัตว์ประหลาดโผล่ขึ้นมา จนสภาเมืองมากอกยกย่องให้เมมเฟรเป็นสัญลักษณ์ประจำเมืองอย่างเป็นทางการ',
      'Revered in Abenaki lore and chronicled by European settlers since 1816, the municipality of Magog officially embraced Memphre as a protected cultural symbol.',
      'ห้ามลอยตัวเล่นน้ำเดี่ยวในจุดน้ำลึกสุดของทะเลสาบเมมเฟรมากอก',
      'Never drift alone in open deep waters across the international lake border.',
      'https://i.ytimg.com/vi/KkooylIipVw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KkooylIipVw/hqdefault.jpg","title":"เมมเฟร (พญานาคสองแผ่นดินแห่งทะเลสาบเมมเฟรมากอก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KkooylIipVw","title":"Thirty Foot Lake Monster of Lake Memphre: Loch Ness Encounters - FREE MOVIE","thumbnail":"https://i.ytimg.com/vi/KkooylIipVw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-brosno-dragon-tver-russia',
      'มังกรแห่งทะเลสาบบรอสโน (อสูรกลืนทัพแห่งตเวียร์)',
      'The Brosno Dragon (Brosnya, The Slavic Lake Beast)',
      'monster',
      'ตเวียร์',
      'Tver Oblast',
      'ทะเลสาบบรอสโน อันเดรียปอล',
      'Lake Brosno, Andreapol',
      56.8333,
      31.9333,
      'jungle_curse',
      'ตำนานสัตว์ประหลาดยุคโบราณแห่งทะเลสาบบรอสโนในแคว้นตเวียร์ ประเทศรัสเซีย ตำนานในศตวรรษที่ 13 เล่าว่าระหว่างที่กองทัพมองโกลของบาตูข่านกำลังเคลื่อนพลมายังนอฟโกรอด ทหารได้หยุดพักม้าที่ริมทะเลสาบ ทันใดนั้นมีมังกรยักษ์โผล่ขึ้นมาจากใต้น้ำกลืนกินทหารและม้าไปจำนวนมากจนกองทัพมองโกลต้องล่าถอย ในยุคปัจจุบันยังมีรายงานฟองก๊าซเดือดพล่านและเงาร่างของสิ่งมีชีวิตขนาดมหึมาใต้ผิวน้ำลึกกว่า 40 เมตร',
      'The Brosno Dragon, nicknamed Brosnya, is a fearsome aquatic cryptid of Lake Brosno in western Russia. Dating back to 13th-century chronicles when it reportedly emerged to devour advancing Mongol-Tatar forces under Batu Khan, modern expeditions continue to investigate mysterious sonar anomalies and massive bubble eruptions in the 140-foot deep lake.',
      'นอกจากศึกบาตูข่านแล้ว ในช่วงสงครามโลกครั้งที่สองยังมีเรื่องเล่าว่ามังกรแห่งบรอสโนได้ลากซากเครื่องบินรบเยอรมันที่ตกลงในทะเลสาบจมหายไปในพริบตา',
      'Chronicled from Batu Khan''s 1238 invasion to World War II accounts of an aircraft swallowed beneath the waves, Brosnya remains Russia''s most notorious freshwater cryptid.',
      'ห้ามทอดสมอเรือหรือจุดไฟเหนือแนวฟองก๊าซปริศนากลางทะเลสาบ',
      'Do not anchor boats or ignite flames directly over the mysterious bubbling vents.',
      'https://i.ytimg.com/vi/OsMoNd4lugM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/OsMoNd4lugM/hqdefault.jpg","title":"มังกรแห่งทะเลสาบบรอสโน (อสูรกลืนทัพแห่งตเวียร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=OsMoNd4lugM","title":"The Brosno Dragon Mystery: Exploring a Russian Cryptid","thumbnail":"https://i.ytimg.com/vi/OsMoNd4lugM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-issie-lake-ikeda-kagoshima',
      'อิซซี่ (สัตว์ประหลาดแห่งทะเลสาบปากปล่องภูเขาไฟอิเคดะ)',
      'Issie (The Crater Lake Monster of Lake Ikeda)',
      'monster',
      'คาโกชิมะ',
      'Kagoshima',
      'ทะเลสาบอิเคดะ อิบุสึกิ',
      'Lake Ikeda, Ibusuki',
      31.2333,
      130.55,
      'jungle_curse',
      'อสูรกายแห่งทะเลสาบปล่องภูเขาไฟอิเคดะ ในจังหวัดคาโกชิมะ เกาะคิวชู ประเทศญี่ปุ่น ตำนานเล่าถึงแม่ม้าสีขาวที่กระโดดลงสู่ทะเลสาบด้วยความเสียใจหลังจากสูญเสียลูกม้า จนกลายร่างเป็นอสูรทะเลสาบคอยาว ในปี 1978 ชายคนหนึ่งถ่ายภาพเงาดำขนาดมหึมาสองลูกที่เคลื่อนที่อย่างรวดเร็วในทะเลสาบจนกลายเป็นข่าวดังไปทั่วญี่ปุ่น และมีชาวบ้านกว่า 20 คนร่วมเป็นพยานพบเห็นสิ่งมีชีวิตขนาดยาวกว่า 5 เมตรในวันเดียวกัน',
      'Issie is Japan''s most celebrated lake monster inhabiting the caldera of Lake Ikeda in Kagoshima Prefecture. Born from a legend of a white mare transformed by grief into a water beast, Issie surged into nationwide headlines in 1978 when striking photographs and over twenty eyewitnesses spotted a 16-foot long, dark creature undulating through the crater lake.',
      'ภาพถ่ายวันที่ 3 กันยายน 1978 โดยนายโทชิอากิ มัทสึฮาระ สร้างกระแสความสนใจระดับชาติ ทางการท้องถิ่นจึงสร้างรูปปั้นอิซซี่สีทองไว้ริมทะเลสาบและมีการจัดทัวร์สำรวจอย่างเป็นทางการ',
      'The iconic September 1978 photograph snapped by Toshiaki Matsuhara triggered nationwide media coverage, leading to permanent lakeside monuments celebrating Issie.',
      'ห้ามส่งเสียงดังรบกวนหรือทิ้งขยะลงในปล่องภูเขาไฟศักดิ์สิทธิ์',
      'Show strict respect to the sacred volcanic waters and avoid loud disturbances along the shore.',
      'https://i.ytimg.com/vi/lFwVH9pkA5o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/lFwVH9pkA5o/hqdefault.jpg","title":"อิซซี่ (สัตว์ประหลาดแห่งทะเลสาบปากปล่องภูเขาไฟอิเคดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=lFwVH9pkA5o","title":"Issie Lake Monster: UMA Mystery of Japan’s Lake Ikeda (Sightings, Legends & Scientific Theories)","thumbnail":"https://i.ytimg.com/vi/lFwVH9pkA5o/hqdefault.jpg"}]'
    );